TURATH_CHUNK(8,[{"num":1600,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا تَوَضَّأَ خَلَّلَ لِحْيَتَهُ بِالْمَاءِ."],"takhrij":"حسن: رواه أحمد (25970، 25971) من وجهين عن عمر بن أبي وهب، وإسحاق في مسنده (1371) عن عبد الصمد بن عبد الوارث، عن عمر بن أبي وهب، الخراعي، ثنا موسى بن ثروان، عن طلحة بن عبيدالله بن كَريز، عن عائشة، فذكرت الحديث.","grade":"حسن","chapter_ar":"باب استحباب تخليل اللحية في الوضوء","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Aḥmad (25970, 25971) and Isḥāq in his Musnad (1371).","chapter_en":"The Recommendation of Running Water through the Beard During Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿĀʾishah said: When the Messenger of Allah ﷺ performed wuḍūʾ, he would run water through his beard."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (25970، 25971)، وإسحاق في مسنده (1371)."},{"num":1601,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا تَوَضَّأَ أَخَذَ كَفًّا مِنْ مَاءٍ فَأَدْخَلَهُ تَحْتَ حَنَكِهِ فَخَلَّلَ بِهِ لِحْيَتَهُ، وَقَالَ: هَكَذَا أَمَرَنِي رَبِّي عَزَّ وَجَلَّ."],"takhrij":"حسن: رواه أبو داود (145) عن أبي توبة –يعني الربيع بن نافع، حدثنا أبو المليح، عن الوليد بن زوران، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب استحباب تخليل اللحية في الوضوء","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (145) and al-Ḥākim (1/149).","chapter_en":"The Recommendation of Running Water through the Beard During Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Anas ibn Mālik reported that when the Messenger of Allah ﷺ performed wuḍūʾ, he would take a handful of water, place it beneath his chin, and run it through his beard. He said: “This is how my Lord commanded me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (145)، والحاكم (1/149)."},{"num":1602,"demo":false,"sanad":"","matn":["عَنْ عَاصِمِ بْنِ لَقِيطِ بْنِ صَبْرَةَ، عَنْ أَبِيهِ لَقِيطِ بْنِ صَبْرَةَ قَالَ: كُنْتُ وَافِدَ بَنِي الْمُنْتَفِقِ أَوْ فِي وَفْدِ بَنِي الْمُنْتَفِقِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرَ قِصَّةً نُزُولِهِ عَلَى عَائِشَةَ، وَأَنَّهَا أُمِرْت بِصُنْع خَزِيرَة إلَى أَنْ لَقِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا رَسُولَ اللَّهِ، أَخْبِرْنِي عَنِ الْوُضُوءِ، فَقَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَسْبِغْ الْوُضُوءَ وَخَلِّلْ بَيْنَ الْأَصَابِعِ وَبَالِغْ فِي الِاسْتِنْشَاقِ، إِلَّا أَنْ تَكُونَ صَائِمًا."],"takhrij":"صحيح: رواه أبو داود (142) مُطوَّلاً واللفظ له، والترمذي (38)، والنسائي (114)، وابن ماجه (407، 448) مُختصراً. كلهم من حديث إسماعيل بن كثير أبي هاشم المكي، عن عاصم بن لَقيط به.","grade":"صحيح","chapter_ar":"باب ما جاء في تخليل الأصابع","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (142), whose wording this is, al-Tirmidhī (38), al-Nasāʾī (114), and Ibn Mājah (407, 448).","chapter_en":"What Has Been Reported Concerning Washing between the Fingers and Toes","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["ʿĀṣim ibn Laqīṭ ibn Ṣabrah reported from his father, who said: I was the representative of Banū al-Muntafiq, or among the delegation of Banū al-Muntafiq. He then mentioned the account of his staying with ʿĀʾishah and her ordering that khazīrah be prepared. He then said: “O Messenger of Allah, tell me about wuḍūʾ.” The Messenger of Allah ﷺ said: “Perform wuḍūʾ thoroughly, wash between the fingers, and be thorough in drawing water into the nose, except when you are fasting.”"]},"buhuth":{"en":["In some narrations:","“When you perform wuḍūʾ, rinse your mouth.”","Al-Tirmidhī said: “Ḥasan ṣaḥīḥ.”","Khazīrah is meat cut into small pieces over which plenty of water is poured; when it is cooked, flour is sprinkled into it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (142)، واللفظ له، والترمذي (38)، والنسائي (114)، وابن ماجه (407، 448)."},{"num":1603,"demo":false,"sanad":"","matn":["عَنِ الْمُسْتَوْرِدِ بْنِ شَدَّادٍ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا تَوَضَّأَ يَدْلُكُ أَصَابِعَ رِجْلَيْهِ بِخِنْصَرِهِ."],"takhrij":"حسن: رواه أبو داود (148) والترمذي (40) وابن ماجه (446) كلهم من طريق قتيبة بن سعيد، حدَّثنا ابن لهيعة، عن يزيد بن عمرو، عن أبي عبدالرحمن الحُبُلِّي، عن المُستَوْرد بن شدَّاد فذكر مثله.","grade":"حسن","chapter_ar":"باب ما جاء في تخليل الأصابع","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (148), al-Tirmidhī (40), and Ibn Mājah (446). Al-Tirmidhī said: “This is a ḥasan gharīb hadith.”","chapter_en":"What Has Been Reported Concerning Washing between the Fingers and Toes","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Al-Mustawrid ibn Shaddād said: I saw the Messenger of Allah ﷺ, when performing wuḍūʾ, rub between the toes of his feet with his little finger."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (148)، والترمذي (40)، وابن ماجه (446). وقال الترمذي: «هذا حديث حسن غريب»."},{"num":1604,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: إِذَا تَوَضَّأْتَ فَخَلِّلْ بَيْنَ أَصَابِعِ يَدَيْكَ وَرِجْلَيْكَ."],"takhrij":"حسن: رواه الترمذي (39) وابن ماجه (447) كلاهما عن إبراهيم بن سعيد وهو الجوهري، ثنا سعد بن عبد الحميد بن جعفر، ثنا عبدالرحمن بن أبي الزناد، عن موسى بن عقبة، عن صالح مولى التوأمة، عن ابن عباس.","grade":"حسن","chapter_ar":"باب ما جاء في تخليل الأصابع","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by al-Tirmidhī (39) and Ibn Mājah (447). This wording is that of al-Tirmidhī.","chapter_en":"What Has Been Reported Concerning Washing between the Fingers and Toes","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās reported that the Messenger of Allah ﷺ said: “When you perform wuḍūʾ, wash between the fingers of your hands and the toes of your feet.”"]},"buhuth":{"en":["Ibn Mājah’s wording is:","“When you stand for prayer, perform wuḍūʾ thoroughly and cause the water to reach between the fingers of your hands and the toes of your feet.”","Al-Tirmidhī said: “Ḥasan gharīb.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (39)، وابن ماجه (447)، واللفظ للترمذي."},{"num":1605,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَتُنْتَهَكَنَّ الْأَصَابِعُ بِالطَّهُورِ، أَوْ لَتَنْتَهِكَنَّهَا النَّارُ."],"takhrij":"حسن: رواه الطبراني في الأوسط(2674) –مجمع البحرين (422) عن إبراهيم (هو ابن أحمد الوكيعي)، حدثنا شيبان بن فرّوخ، ثنا أبو عوانة، عن أبي مسكين، عن هزيل بن شرحبيل، عن عبدالله بن مسعود فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تخليل الأصابع","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ, as cited in Majmaʿ al-Baḥrayn (422).","chapter_en":"What Has Been Reported Concerning Washing between the Fingers and Toes","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd reported that the Messenger of Allah ﷺ said: “Be thorough in purifying between the fingers, or the Fire will thoroughly reach them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط — مجمع البحرين (422)."},{"num":1606,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا اسْتَيْقَظَ أُرَاهُ أَحَدُكُمْ مِنْ مَنَامِهِ، فَتَوَضَّأَ فَلْيَسْتَنْثِرْ ثَلَاثًا، فَإِنَّ الشَّيْطَانَ يَبِيتُ عَلَى خَيْشُومِهِ."],"takhrij":"متَّفقٌ عليه: رواه البخاري (3295) ومسلم (238)، كلاهما من طريق محمد ابن إبراهيم، عن عيسى بن طلحة، عن أبي هريرة فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب المضمضة والاستنشاق","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3295) and Muslim (238).","chapter_en":"Rinsing the Mouth and Drawing Water into the Nose","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “When one of you awakens from sleep and performs wuḍūʾ, let him expel water from his nose three times, for Satan spends the night upon his nostrils.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3295)، ومسلم (238)."},{"num":1607,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اسْتَنْثِرُوا مَرَّتَيْنِ بَالِغَتَيْنِ أَوْ ثَلَاثًا."],"takhrij":"حسن: رواه أبو داود (141) وابن ماجه (408) كلاهما من طريق وكيع، عن ابن أبي ذئب، عن قارظ بن شيبة، عن أبي غَطَفان المُريّ، عن ابن عباس، فذكر الحديث.","grade":"حسن","chapter_ar":"باب المضمضة والاستنشاق","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (141) and Ibn Mājah (408).","chapter_en":"Rinsing the Mouth and Drawing Water into the Nose","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Ibn ʿAbbās reported that the Messenger of Allah ﷺ said: “Expel water from the nose thoroughly twice, or three times.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (141)، وابن ماجه (408)."},{"num":1608,"demo":false,"sanad":"","matn":["عن عَبْدَ اللَّهِ بْنَ مُغَفَّلٍ، أَنَّهُ سَمِعَ ابْنَهُ يَقُولُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ الْقَصْرَ الْأَبْيَضَ عَنْ يَمِينِ الْجَنَّةِ إِذَا دَخَلْتُهَا، فَقَالَ: أَيْ بُنَيَّ، سَلِ اللَّهَ الْجَنَّةَ وَتَعَوَّذْ بِهِ مِنَ النَّارِ، فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّهُ سَيَكُونُ فِي هَذِهِ الْأُمَّةِ قَوْمٌ يَعْتَدُونَ فِي الطَّهُورِ وَالدُّعَاءِ."],"takhrij":"صحيح: رواه أبو داود (96) وابن ماجه (3864)، كلاهما من طريق حماد بن سلمة، ثنا سعيد الجُريري، عن أبي نعامة، عن عبدالله بن مغفل، فذكر الحديث، إلاَّ أنّ ابن ماجه لم يذكر الطهور، ولذا أكرر ذكر الحديث في الدعاء.","grade":"صحيح","chapter_ar":"باب النهي عن الإسراف في الماء","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (96) and Ibn Mājah (3864), except that Ibn Mājah’s narration does not mention “purification.”","chapter_en":"The Prohibition of Excess and Wastefulness in the Use of Water","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["ʿAbdullāh ibn Mughaffal heard his son saying: “O Allah, I ask You for the white palace on the right side of Paradise when I enter it.” He said: “My son, ask Allah for Paradise and seek refuge in Him from the Fire, for I heard the Messenger of Allah ﷺ say: ‘There will be people in this Ummah who transgress the proper limits in purification and supplication.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (96)، وابن ماجه (3864)، إلا أن ابن ماجه لم يذكر «الطهور»."},{"num":1609,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَأَلَهُ عَنِ الْوُضُوءِ ؟ فَأَرَاهُ ثَلَاثًا ثَلَاثًا، ثُمَّ قَالَ: هَذَا الْوُضُوءُ فَمَنْ زَادَ عَلَى هَذَا فَقَدْ أَسَاءَ أَوْ تَعَدَّى أَوْ ظَلَمَ."],"takhrij":"حسن: رواه ابن ماجه (422)، واللفظ له، وأبو داود (135)، والنسائي (140)، وأحمد (6684)، وابن خزيمة (174) كلهم من طريق موسى بن أبي عائشة، عن عمرو بن شعيب، عن أبيه، عن جده قال: فذكره.","grade":"حسن","chapter_ar":"باب النهي عن الإسراف في الماء","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Ibn Mājah (422), whose wording this is, Abū Dāwūd (135), al-Nasāʾī (1/88), Aḥmad (2684), and Ibn Khuzaymah (174).","chapter_en":"The Prohibition of Excess and Wastefulness in the Use of Water","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb narrated from his father, from his grandfather, that a Bedouin came to the Prophet ﷺ and asked him about wuḍūʾ. He showed him wuḍūʾ, washing each part three times, then said: “This is wuḍūʾ. Whoever goes beyond this has acted badly, exceeded the proper limit, or acted unjustly.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (422)، واللفظ له، وأبو داود (135)، والنسائي (140)، وأحمد (6684)، وابن خزيمة (174)."},{"num":1610,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: بِتُّ عِنْدَ خَالَتِي مَيْمُونَةَ، فَقَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَتَوَضَّأَ مِنْ شَنَّةٍ وُضُوءًا يُقَلِّلُهُ، فَقُمْتُ فَصَنَعْتُ كَمَا صَنَعَ."],"takhrij":"صحيح: رواه ابن ماجه (424) واللفظ له، وابن خزيمة (1533) كلاهما من حديث سفيان، عن عمرو بن دينار قال: سمعتُ كريبا مولى ابن عباس، عن ابن عباس قال: فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الإسراف في الماء","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (424), whose wording this is, and Ibn Khuzaymah (1533).","chapter_en":"The Prohibition of Excess and Wastefulness in the Use of Water","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Ibn ʿAbbās said: I spent the night at the house of my maternal aunt Maymūnah. The Prophet ﷺ got up and performed wuḍūʾ from a shannah, a water-skin, using only a small amount of water. I then got up and did as he had done."]},"buhuth":{"en":["A shannah is a water-skin.","The expression “using only a small amount” means that he did not use an excessive quantity of water. In another narration: “He performed a light wuḍūʾ,” and the meaning is the same."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (424)، واللفظ له، وابن خزيمة (1533)."},{"num":1611,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: أَسْبِغُوا الْوُضُوءَ، فَإِنَّ أَبَا الْقَاسِمِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَيْلٌ لِلْأَعْقَابِ مِنَ النَّارِ."],"takhrij":"متَّفقٌ عليه: رواه البخاري في الوضوء (165) واللفظ له، ومسلم في الطهارة (242) كلاهما من طريق شعبة، عن محمد بن زياد، عن أبي هريرة أنه رأى قوماً يتوضؤون من المِطْهَرة. وفي مسلم من طريق الربيع بن مسلم، عن محمد بن زياد عن أبي هريرة أن رسول الله صلى الله عليه وسلم رأى رجلاً لم يغسل عقِبيه فقال:ويلٌ للأعقاب من النار.","grade":"متفق عليه","chapter_ar":"باب وجوب استيعاب جميع أجزاء محل الطهارة","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (165), whose wording this is, and Muslim (242).","chapter_en":"The Obligation of Washing Every Part of the Area Required in Purification","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah said: “Perform wuḍūʾ thoroughly, for Abū al-Qāsim ﷺ said: ‘Woe to the heels from the Fire.’”"]},"buhuth":{"ar":["وفي مسلم أن رسول الله ﷺ رأى رجلًا لم يغسل عقبيه فقال:","«وَيْلٌ لِلْأَعْقَابِ مِنَ النَّارِ»."],"en":["In Muslim’s narration, the Messenger of Allah ﷺ saw a man who had not washed his heels and said:","“Woe to the heels from the Fire.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (165)، واللفظ له، ومسلم (242)."},{"num":1612,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: أَخْبَرَنِي عُمَرُ بْنُ الْخَطَّابِ أَنَّ رَجُلًا تَوَضَّأَ فَتَرَكَ مَوْضِعَ ظُفُرٍ عَلَى قَدَمِهِ، أَبْصَرَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: ارْجِعْ فَأَحْسِنْ وُضُوءَكَ، فَرَجَعَ ثُمَّ صَلَّى."],"takhrij":"صحيح: رواه مسلم في الطهارة (243) عن سلمة بن شبيب، حدَّثنا الحسن بن محمد بن أعين، حدَّثنا معقل، عن أبي الزبير، عن جابر فذكر الحديث.","grade":"صحيح","chapter_ar":"باب وجوب استيعاب جميع أجزاء محل الطهارة","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (243).","chapter_en":"The Obligation of Washing Every Part of the Area Required in Purification","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: ʿUmar ibn al-Khaṭṭāb informed me that a man performed wuḍūʾ but left an area on his foot the size of a fingernail dry. The Prophet ﷺ saw it and said: “Go back and perform your wuḍūʾ properly.” So he returned, then prayed."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (243)."},{"num":1613,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّهَا سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: وَيْلٌ لِلأَعْقَابِ مِنَ النَّارِ."],"takhrij":"صحيح: رواه مسلم في الطهارة (240) عن سالم بن عبدالله مولى شدَّاد قال: دخلت على عائشة زوج النبي صلى الله عليه وسلم يوم توفي سعد بن أبي وقاص، فدخل عبدالرحمن بن أبي بكر فتوضأ عندها، فقالت: يا عبدالرحمن! أسبغ الوضوء، فاني سمعت رسول الله صلى الله عليه وسلم يقول، فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب وجوب استيعاب جميع أجزاء محل الطهارة","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (240).","chapter_en":"The Obligation of Washing Every Part of the Area Required in Purification","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["ʿĀʾishah reported that she heard the Messenger of Allah ﷺ say: “Woe to the heels from the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (240)."},{"num":1614,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو قَالَ: تَخَلَّفَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنَّا فِي سَفْرَةٍ سَافَرْنَاهَا، فَأَدْرَكَنَا وَقَدْ أَرْهَقْنَا الْعَصْرَ، فَجَعَلْنَا نَتَوَضَّأُ وَنَمْسَحُ عَلَى أَرْجُلِنَا، فَنَادَى بِأَعْلَى صَوْتِهِ: وَيْلٌ لِلْأَعْقَابِ مِنَ النَّارِ مَرَّتَيْنِ أَوْ ثَلَاثًا."],"takhrij":"متَّفقٌ عليه: رواه البخاري في الوضوء (163) واللفظ له، ومسلم في الطهارة (241) كلاهما عن أبي عوانة، عن أبي بشْر، عن يوسف بن ماهَك، عن عبدالله بن عمرو به. وعند مسلم: وقد حضرت صلاةُ العصر. وفي رواية قال: رجعنا مع رسول الله صلى الله عليه وسلم من مكة إلى المدينة، حتَّى إذا كنا بماء بالطريق تعجّل قوم عند العصر، فتوضّأوا وهم عِجال، فانتهينا إليهم وأعقابهم تلوح لم يمسَّها الماءُ، فقال رسول الله صلى الله عليه وسلم:ويلٌ للأعقاب من النار، أسبغوا الوضوء. وتم تخريجه في المنة الكبرى (1/154).","grade":"متفق عليه","chapter_ar":"باب وجوب استيعاب جميع أجزاء محل الطهارة","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (163), whose wording this is, and Muslim (241).","chapter_en":"The Obligation of Washing Every Part of the Area Required in Purification","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ said: The Prophet ﷺ remained behind us during a journey. He caught up with us when the time for ʿAṣr had become pressing. We began performing wuḍūʾ and were merely passing water over our feet, so he called out at the top of his voice: “Woe to the heels from the Fire!” He repeated it two or three times."]},"buhuth":{"ar":["وفي رواية قال: رجعنا مع رسول الله ﷺ من مكة إلى المدينة، حتى إذا كنا بماء بالطريق تعجل قوم عند العصر، فتوضؤوا وهم عجال، فانتهينا إليهم وأعقابهم تلوح لم يمسها الماء، فقال رسول الله ﷺ:","«وَيْلٌ لِلْأَعْقَابِ مِنَ النَّارِ، أَسْبِغُوا الْوُضُوءَ»."],"en":["In another narration, he said:","We returned with the Messenger of Allah ﷺ from Makkah to Madinah. When we reached some water along the road, a group hurried because of ʿAṣr and performed wuḍūʾ hastily. We came upon them while their heels were visibly dry and had not been touched by water. The Messenger of Allah ﷺ said:","“Woe to the heels from the Fire. Perform wuḍūʾ thoroughly.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (163)، واللفظ له، ومسلم (241)."},{"num":1615,"demo":false,"sanad":"","matn":["عَنْ عَبْدَ اللَّهِ بْنَ الْحَارِثِ بْنِ جَزْءٍ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: وَيْلٌ لِلْأَعْقَابِ وَبُطُونِ الْأَقْدَامِ مِنَ النَّارِ."],"takhrij":"حسن: رواه الإمام أحمد (17710) قال: حدَّثنا حسن (وهو ابن موسى) قال: حدَّثنا ابن لهيعة، حدَّثنا حيوة بن شُريح، عن عُقبة بن مسلم قال: سمعتُ عبدالله بن الحارث بن جَزْء الزبيدي فذكر الحديث.","grade":"حسن","chapter_ar":"باب وجوب استيعاب جميع أجزاء محل الطهارة","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Aḥmad (17710), Ibn Khuzaymah (163), al-Dāraquṭnī (1/95), and al-Ḥākim (580).","chapter_en":"The Obligation of Washing Every Part of the Area Required in Purification","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["ʿAbdullāh ibn al-Ḥārith ibn Jazʾ al-Zubaydī said: I heard the Messenger of Allah ﷺ say: “Woe to the heels and the soles of the feet from the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (17710)، وابن خزيمة (163)، والدارقطني (316)، والحاكم (580)."},{"num":1616,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: وَيْلٌ لِلْعَرَاقِيبِ مِنَ النَّارِ."],"takhrij":"صحيح: رواه ابن ماجه (454) عن أبي بكر بن أبي شيبة، قال: حدَّثنا أبو الأحوص، عن أبي إسحاق، عن سعيد بن أبي كرْب، عن جابر بن عبدالله فذكره.","grade":"صحيح","chapter_ar":"باب وجوب استيعاب جميع أجزاء محل الطهارة","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (454) and Aḥmad (14965).","chapter_en":"The Obligation of Washing Every Part of the Area Required in Purification","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: I heard the Messenger of Allah ﷺ say: “Woe to the heels from the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (454)، وأحمد (14965)."},{"num":1617,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ قَالَ: وَاللَّهِ مَا خَصَّنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشَيْءٍ دُونَ النَّاسِ إِلَّا بِثَلَاثَةِ أَشْيَاءَ، فَإِنَّهُ أَمَرَنَا أَنْ نُسْبِغَ الْوُضُوءَ وَلَا نَأْكُلَ الصَّدَقَةَ وَلَا نُنْزِيَ الْحُمُرَ عَلَى الْخَيْلِ."],"takhrij":"حسن: رواه أبو داود (808) في الصلاة في حديث طويل، وسوف يعاد في باب قدر القراءة في صلاة الظهر والعصر. والنسائي (141) والترمذي (1710) واللفظ لهما، وابن ماجه (426) كلهم من حديث أبي جَهْضَم موسى بن سالم، عن عبدالله ابن عبيدالله بن عباس، عن ابن عباس.","grade":"حسن","chapter_ar":"باب وجوب استيعاب جميع أجزاء محل الطهارة","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (808), al-Nasāʾī (141), al-Tirmidhī (1710), whose wording is followed, and Ibn Mājah (426). Al-Tirmidhī said: Ḥasan Ṣaḥīḥ.","chapter_en":"The Obligation of Washing Every Part of the Area Required in Purification","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās said: “By Allah, the Messenger of Allah ﷺ did not single us out with anything apart from the rest of the people except three things: he commanded us to perform wuḍūʾ thoroughly, not to consume charity, and not to breed donkeys with horses.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (808)، والنسائي (141)، والترمذي (1710)، واللفظ لهما، وابن ماجه (426). وقال الترمذي: حسن صحيح."},{"num":1618,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَجُلًا جَاءَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَدْ تَوَضَّأَ وَتَرَكَ عَلَى قَدَمِهِ مِثْلَ مَوْضِعِ الظُّفْرِ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ارْجِعْ فَأَحْسِنْ وُضُوءَكَ."],"takhrij":"صحيح: أخرجه أبو داود (173) وابن ماجه (665) كلاهما من طريق عبدالله بن وهب، عن جرير بن حازم، أنه سمع قتادة بن دعامة،حدَّثنا أنس فذكره.","grade":"صحيح","chapter_ar":"باب وجوب استيعاب جميع أجزاء محل الطهارة","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (173) and Ibn Mājah (665).","chapter_en":"The Obligation of Washing Every Part of the Area Required in Purification","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Anas reported that a man came to the Prophet ﷺ after performing wuḍūʾ but had left an area on his foot about the size of a fingernail dry. The Messenger of Allah ﷺ said to him: “Go back and perform your wuḍūʾ properly.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (173)، وابن ماجه (665)."},{"num":1619,"demo":false,"sanad":"","matn":["عَنْ خَالِدِ بْنِ مَعْدَانَ، عَنْ بَعْضِ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى رَجُلًا يُصَلِّ وَفِي ظَهْرِ قَدَمِهِ لُمْعَةٌ قَدْرُ الدِّرْهَمِ لَمْ يُصِبْهَا الْمَاءُ، فَأَمَرَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُعِيدَ الْوُضُوءَ وَالصَّلَاةَ."],"takhrij":"حسن: رواه أبو داود (175) قال: حدَّثنا حيوة بن شريح، حدَّثنا بقية، عن بحير بن سعد، عن خالد، عن بعض أصحاب النبي صلى الله عليه وسلم. فذكره.","grade":"حسن","chapter_ar":"باب وجوب استيعاب جميع أجزاء محل الطهارة","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (175) and al-Bayhaqī (1/83).","chapter_en":"The Obligation of Washing Every Part of the Area Required in Purification","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Khālid ibn Maʿdān narrated from one of the Companions of the Prophet ﷺ that the Prophet ﷺ saw a man praying while there was a dry patch on the upper part of his foot, about the size of a dirham, which the water had not reached. The Prophet ﷺ ordered him to repeat both the wuḍūʾ and the prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (175)، والبيهقي (392)."},{"num":1620,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ قَالَ: الصَّفْقَةُ بِالصَّفْقَتَيْنِ رَبًّا، وَأَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِإِسْبَاغِ الْوُضُوءِ."],"takhrij":"حسن: رواه ابن خزيمة (176) من طريق سفيان، عن سماك، عن عبدالرحمن بن عبدالله، وهو ابن مسعود، عن أبيه، فذكر الحديث.","grade":"حسن","chapter_ar":"باب وجوب استيعاب جميع أجزاء محل الطهارة","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Ibn Khuzaymah (176).","chapter_en":"The Obligation of Washing Every Part of the Area Required in Purification","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Ibn Masʿūd said: “The Messenger of Allah ﷺ commanded us to perform wuḍūʾ thoroughly.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة (176)."},{"num":1621,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَلَا أَدُلُّكُمْ عَلَى مَا يَمْحُو اللَّهُ بِهِ الْخَطَايَا، وَيَرْفَعُ بِهِ الدَّرَجَاتِ ؟ قَالُوا: بَلَى يَا رَسُولَ اللَّهِ! قَالَ: إِسْبَاغُ الْوُضُوءِ عَلَى الْمَكَارِهِ، وَكَثْرَةُ الْخُطَا إِلَى الْمَسَاجِدِ، وَانْتِظَارُ الصَّلَاةِ بَعْدَ الصَّلَاةِ، فَذَلِكُمُ الرِّبَاطُ.","وَفِي رِوَايَةِ: فَذَلِكُمُ الرِّبَاطُ، فَذَلِكُمُ الرِّبَاطُ."],"takhrij":"صحيح: رواه مالك في السفر (55) عن العلاء بن عبدالرحمن، عن أبيه، عن أبي هريرة، ورواه مسلم في الطهارة (251) من أوجه أُخر عن العلاء بن عبدالرحمن، واللفظ له، وفي لفظ مالك كرّر ذلكم الرباط ثلاث مرات.","grade":"صحيح","chapter_ar":"باب فضل إسباغ الوضوء على المكاره","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik (55) and Muslim (251). In Mālik’s wording, “That is ribāṭ” is repeated three times.","chapter_en":"The Virtue of Performing Wuḍūʾ Thoroughly Despite Hardship","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “Shall I not direct you to that by which Allah erases sins and raises ranks?” They replied: “Yes, O Messenger of Allah.” He said: “Performing wuḍūʾ thoroughly despite hardship, taking many steps to the mosques, and waiting for one prayer after another. That is ribāṭ.”","In another narration: “That is ribāṭ; that is ribāṭ.”"]},"buhuth":{"en":["The word “hardships” refers to things that a person dislikes or finds difficult. The meaning includes performing wuḍūʾ despite severe cold or physical conditions in which contact with water causes discomfort.","The statement “That is ribāṭ” means the ribāṭ for which encouragement and reward are promised. The basic meaning of ribāṭ is remaining bound or steadfast upon something; it is as though the person restrains himself upon this act of obedience."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (55)، ومسلم (251). وفي لفظ مالك كرر: «ذلكم الرباط» ثلاث مرات."},{"num":1622,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِسْبَاغُ الْوُضُوءِ فِي الْمَكَارِهِ، وَإِعْمَالُ الْأَقْدَامِ إِلَى الْمَسَاجِدِ، وَانْتِظَارُ الصَّلَاةِ بَعْدَ الصَّلَاةِ تَغْسِلُ الْخَطَايَا غَسْلًا."],"takhrij":"حسن: رواه إسحاق واللفظ له، وعبد بن حميد (91) وأبويعلى (488)كلهم من طريق صفوان بن عيسى، أنا الحارث بن عبدالرحمن بن أبي ذباب، عن سعيد بن المسيب، عن علي بن أبي طالب، فذكر الحديث. المطالب العالية (79).","grade":"حسن","chapter_ar":"باب فضل إسباغ الوضوء على المكاره","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Isḥāq, whose wording this is, and ʿAbd ibn Ḥumayd (91).","chapter_en":"The Virtue of Performing Wuḍūʾ Thoroughly Despite Hardship","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib reported that the Prophet ﷺ said: “Performing wuḍūʾ thoroughly despite hardships, walking to the mosques, and waiting for one prayer after another wash away sins.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه إسحاق، واللفظ له، وعبد بن حميد (91)."},{"num":1623,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَلَا أَدُلُّكُمْ عَلَى مَا يُكَفِّرُ اللَّهُ بِهِ الْخَطَايَا، وَيَزِيدُ بِهِ فِي الْحَسَنَاتِ ؟ قَالُوا: بَلَى يَا رَسُولَ اللَّهِ، قَالَ: إِسْبَاغُ الْوُضُوءِ عَلَى الْمَكَارِهِ، وَكَثْرَةُ الْخُطَا إِلَى الْمَسَاجِدِ، وَانْتِظَارُ الصَّلَاةِ بَعْدَ الصَّلَاةِ.","وَفِي رِوَايَةٍ بِزِيَادَةٍ: مَا مِنْكُمْ مِنْ رَجُلٍ يَخْرُجُ مِنْ بَيْتِهِ مُتَطَهِّرًا، فَيُصَلِّي مَعَ الْمُسْلِمِينَ الصَّلَاةَ، ثُمَّ يَجْلِسُ فِي الْمَجْلِسِ يَنْتَظِرُ الصَّلَاةَ الْأُخْرَى، إِنَّ الْمَلَائِكَةَ تَقُولُ: اللَّهُمَّ اغْفِرْ لَهُ، اللَّهُمَّ ارْحَمْهُ، فَإِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَاعْدِلُوا صُفُوفَكُمْ، وَأَقِيمُوهَا، وَسُدُّوا الْفُرَجَ، فَإِنِّي أَرَاكُمْ مِنْ وَرَاءِ ظَهْرِي، فَإِذَا قَالَ إِمَامُكُمْ: اللَّهُ أَكْبَرُ، فَقُولُوا: اللَّهُ أَكْبَرُ، وَإِذَا رَكَعَ فَارْكَعُوا، وَإِذَا قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، فَقُولُوا: اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ، وَإِنَّ خَيْرَ الصُّفُوفِ صُفُوفِ الرِّجَالِ الْمُقَدَّمُ، وَشَرُّهَا الْمُؤَخَّرُ، وَخَيْرُ صُفُوفِ النِّسَاءِ الْمُؤَخَّرُ، وَشَرُّهَا الْمُقَدَّمُ يَا مَعْشَرَ النِّسَاءِ إِذَا سَجَدَ الرِّجَالُ فَاغْضُضْنَ أَبْصَارَكُنَّ لَا تَرَيْنَ عَوْرَاتِ الرِّجَالِ مِنْ ضِيقِ الْأُزُرِ."],"takhrij":"حسن: رواه ابن ماجه (427) عن أبي بكر بن أبي شيبة وهو في المصنف sh9944(44)، ثنا يحيى بن أبي كثير، ثنا زهير بن محمد، عن عبدالله بن محمد بن عقيل، عن سعيد بن المسيب، عن أبي سعيد الخدري. فذكره.","grade":"حسن","chapter_ar":"باب فضل إسباغ الوضوء على المكاره","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Ibn Mājah (427) and Abū Bakr ibn Abī Shaybah (1/7). The second, longer narration is narrated by Aḥmad (10994).","chapter_en":"The Virtue of Performing Wuḍūʾ Thoroughly Despite Hardship","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī reported that he heard the Messenger of Allah ﷺ say: “Shall I not tell you what Allah uses to expiate sins and increase good deeds?” They replied: “Yes, O Messenger of Allah.” He said: “Performing wuḍūʾ thoroughly despite hardship, taking many steps to the mosques, and waiting for one prayer after another.” In another narration, with an additional passage:","“No man among you leaves his home in a state of purification, prays the prayer with the Muslims, and then remains seated waiting for the next prayer, except that the angels say: ‘O Allah, forgive him. O Allah, have mercy upon him.’ When you stand for prayer, straighten your rows, establish them properly, and close the gaps, for I see you from behind my back. When your imam says, ‘Allāhu akbar,’ then say, ‘Allāhu akbar.’ When he bows, then bow. And when he says, ‘Allah hears whoever praises Him,’ then say, ‘O Allah, our Lord, to You belongs all praise.’ The best rows of the men are the front rows and the worst are the rear rows; and the best rows of the women are the rear rows and the worst are the front rows. O assembly of women, when the men prostrate, lower your gazes so that you do not see the private parts of the men because of the tightness of their waist-wrappers.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (427)، وأبو بكر بن أبي شيبة (1/7). والرواية الثانية الطويلة عند أحمد (10994)."},{"num":1624,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَوَضَّأُ عِنْدَ كُلِّ صَلَاةٍ.","قَالَ عَمْرُو بْنُ عَامِرٍ: كَيْفَ كُنْتُمْ تَصْنَعُونَ ؟ قَالَ: يُجْزِئُ أَحَدَنَا الْوُضُوءُ مَا لَمْ يُحْدِثْ."],"takhrij":"صحيح: رواه البخاري في الوضوء (214)، عن محمد بن يوسف، قال: حدَّثنا سفيان، عن عَمرو بن عامر، قال: سمعت أنساً .. فذكر الحديث. وعند الترمذي (58) من طريق حميد، عن أنس:طاهراً أو غير طاهر.","grade":"صحيح","chapter_ar":"باب ما جاء في الوضوء لكل صلاة","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (214).","chapter_en":"What Has Been Reported Concerning Performing Wuḍūʾ for Every Prayer","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["Anas said: “The Prophet ﷺ used to perform wuḍūʾ for every prayer.” ʿAmr ibn ʿĀmir asked: “What did you yourselves use to do?”","He replied: “One wuḍūʾ was sufficient for one of us so long as he had not broken it.”"]},"buhuth":{"en":["In al-Tirmidhī (58):","“The Prophet ﷺ used to perform wuḍūʾ for every prayer, whether he was already in a state of purity or not.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (214)."},{"num":1625,"demo":false,"sanad":"","matn":["عَنْ سُوَيْدُ بْنُ النُّعْمَانِ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ خَيْبَرَ حَتَّى إِذَا كُنَّا بِالصَّهْبَاءِ صَلَّى لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْعَصْرَ، فَلَمَّا صَلَّى دَعَا بِالْأَطْعِمَةِ فَلَمْ يُؤْتَ إِلَّا بِالسَّوِيقِ، فَأَكَلْنَا وَشَرِبْنَا، ثُمَّ قَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْمَغْرِبِ فَمَضْمَضَ، ثُمَّ صَلَّى لَنَا الْمَغْرِبَ وَلَمْ يَتَوَضَّأْ."],"takhrij":"صحيح: رواه البخاري في الوضوء (215)، من حديث يحيى بن سعيد، قال: أخبرني بُشَير بن يسار، قال: حدَّثني سُوَيد بن النعمان.. فذكر الحديث، ويذكر الحديث في باب ترك الوضوء مما مست النار.","grade":"صحيح","chapter_ar":"باب جواز الصلوات بوضوء واحد","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (215).","chapter_en":"The Permissibility of Performing Multiple Prayers with a Single Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Suwayd ibn al-Nuʿmān said: We went out with the Messenger of Allah ﷺ in the year of Khaybar. When we reached al-Ṣahbāʾ, the Messenger of Allah ﷺ led us in the ʿAṣr prayer. Afterward he called for food, but nothing was brought except sawīq. We ate and drank. Then the Prophet ﷺ stood for the Maghrib prayer, rinsed his mouth, and prayed Maghrib without performing a new wuḍūʾ."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (215)."},{"num":1626,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى الصَّلَوَاتِ يَوْمَ الْفَتْحِ بِوُضُوءٍ وَاحِدٍ، وَمَسَحَ عَلَى خُفَّيْهِ، فَقَالَ لَهُ عُمَرُ: لَقَدْ صَنَعْتَ الْيَوْمَ شَيْئًا لَمْ تَكُنْ تَصْنَعُهُ ؟ قَالَ: عَمْدًا صَنَعْتُهُ يَا عُمَرُ!."],"takhrij":"صحيح: رواه مسلم في الطهارة (277)، من حديث يحيى بن سعيد، عن سفيان، قال: حدَّثني علقمة بن مرثد، عن سليمان بن بُرَيدة، عن أبيه.. فذكره. وعند الترمذي (61): كان النبي صلى الله عليه وسلم يتوضأ لكل صلاة، فلما كان يوم الفتح صلَّى الصلوات كلها بوضوء واحد.","grade":"صحيح","chapter_ar":"باب جواز الصلوات بوضوء واحد","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (277).","chapter_en":"The Permissibility of Performing Multiple Prayers with a Single Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Buraydah reported that the Prophet ﷺ performed all the prayers on the Day of the Conquest with a single wuḍūʾ and wiped over his leather socks. ʿUmar said to him: “Today you have done something that you did not ordinarily do.” He replied: “I did it deliberately, O ʿUmar.”"]},"buhuth":{"en":["In al-Tirmidhī (61):","“The Prophet ﷺ used to perform wuḍūʾ for every prayer. On the Day of the Conquest, however, he performed all the prayers with a single wuḍūʾ.”","Also relevant to this chapter is the ruling that eating food cooked over fire does not require renewal of wuḍūʾ. Jābir reported that a sheep was slaughtered for the Prophet ﷺ and he ate from it, then stood for the Ẓuhr prayer. Later, the remainder of the sheep was brought to him, and when the next prayer became due, he stood and prayed without touching water. Thus, he performed two prayers with one wuḍūʾ, each prayer in its proper time."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (277)."},{"num":1627,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ، قَالَ: كَانَتْ عَلَيْنَا رِعَايَةُ الإِبِلِ، فَجَاءَتْ نَوْبَتِي، فَرَوَّحْتُهَا بِعَشِيٍّ، فَأَدْرَكْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَائِمًا يُحَدِّثُ النَّاسَ، فَأَدْرَكْتُ مِنْ قَوْلِهِ: مَا مِنْ مُسْلِمٍ يَتَوَضَّأُ، فَيُحْسِنُ وُضُوءَهُ، ثُمَّ يَقُومُ فَيُصَلِّي رَكْعَتَيْنِ، مُقْبِلٌ عَلَيْهِمَا بِقَلْبِهِ وَوَجْهِهِ، إِلَّا وَجَبَتْ لَهُ الْجَنَّةُ.","قَالَ: فَقُلْتُ: مَا أَجْوَدَ هَذِهِ ؟ فَإِذَا قَائِلٌ بَيْنَ يَدَيَّ، يَقُولُ: الَّتِي قَبْلَهَا أَجْوَدُ، فَنَظَرْتُ، فَإِذَا عُمَرُ، قَالَ: إِنِّي قَدْ رَأَيْتُكَ جِئْتَ آنِفًا، قَالَ: مَا مِنْكُمْ مِنْ أَحَدٍ يَتَوَضَّأُ، فَيُبْلِغُ، أَوْ فَيُسْبِغُ الْوَضُوءَ، ثُمَّ يَقُولُ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا عَبْدُ اللَّهِ وَرَسُولُهُ، إِلَّا فُتِحَتْ لَهُ أَبْوَابُ الْجَنَّةِ الثَّمَانِيَةُ، يَدْخُلُ مِنْ أَيِّهَا شَاءَ.","وَفِي رِوَايَةِ: قَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ."],"takhrij":"صحيح: رواه مسلم في الطهارة (234)، عن محمد بن حاتم بن ميمون، ثنا ابن مهدي، ثنا معاوية بن صالح، عن ربيعة بن يزيد، عن أبي إدريس الخولاني، عن عقبة بن عامر.. فذكره.","grade":"صحيح","chapter_ar":"باب ما يقول الرجل إذا توضأ","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (234).","chapter_en":"What a Person Says after Performing Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir said: We were responsible for tending the camels, and when my turn came, I brought them back in the evening. I reached the Messenger of Allah ﷺ while he was standing and speaking to the people, and I heard him say: “No Muslim performs wuḍūʾ and perfects his wuḍūʾ, then stands and prays two rakʿahs, directing his heart and face fully toward them, except that Paradise becomes guaranteed for him.” I said: “How excellent this is!” Then someone in front of me said:","“What came before it is even better.” I looked and saw that it was ʿUmar. He said: “I saw that you had only just arrived.” Then he related: “No one performs wuḍūʾ and completes—or perfects—the wuḍūʾ, then says: ‘I bear witness that there is no deity worthy of worship except Allah, and that Muḥammad is His servant and Messenger,’ except that the eight gates of Paradise are opened for him, and he may enter through whichever of them he wishes.” In another narration: “I bear witness that there is no deity worthy of worship except Allah alone, without partner, and I bear witness that Muḥammad is His servant and Messenger.”"]},"buhuth":{"en":["Al-Tirmidhī (55) adds after the testimony:","“O Allah, make me among those who constantly repent, and make me among those who purify themselves.”","Its chain is authentic."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (234)."},{"num":1628,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِذَا كَانَ جُنُبًا فَأَرَادَ أَنْ يَأْكُلَ أَوْ يَنَامَ، تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ."],"takhrij":"متَّفقٌ عليه: رواه البخاري في الغسل (288) من طريق الليث، عن عبيدالله بن أبي جعفر، عن محمد بن عبدالرحمن، عن عروة، عن عائشة قالت: كان النبي صلى الله عليه وسلم إذا أراد أن ينام وهو جنب غسل فرجه، وتوضأ للصلاة.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الجنب يريد أن يأكل وينام","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (288) and Muslim (305).","chapter_en":"What Has Been Reported Concerning a Person in Janābah Who Wishes to Eat or Sleep","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["ʿĀʾishah said: When the Messenger of Allah ﷺ was in a state of janābah and wished to eat or sleep, he would perform wuḍūʾ like the wuḍūʾ for prayer."]},"buhuth":{"en":["In another narration recorded by Abū Dāwūd (223) and al-Nasāʾī (257):","“When he wished to eat while in a state of janābah, he would wash his hands.”","Al-Nasāʾī’s wording is:","“When he wished to sleep while in a state of janābah, he would perform wuḍūʾ; and when he wished to eat or drink, he would wash his hands and then eat or drink.”","Aḥmad (24714) narrates:","“When the Messenger of Allah ﷺ wished to sleep while in a state of janābah, he would perform wuḍūʾ like that for prayer. When he wished to eat or drink, he would wash his palms and then eat or drink if he wished.”","Ibn Khuzaymah (218) also narrates:","“When the Prophet ﷺ wished to eat while in a state of janābah, he would wash his hands and then eat.”","These narrations show that when a person in a state of janābah wishes to sleep, he should perform wuḍūʾ like that for prayer. In contrast, when he wishes to eat or drink, washing the hands is sufficient."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (288)، ومسلم (305)."},{"num":1629,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ الْخَطَّابِ أَنَّهُ قَالَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ يُصِيبُهُ جَنَابَةٌ مِنَ اللَّيْلِ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَوَضَّأْ وَاغْسِلْ ذَكَرَكَ ثُمَّ نَمْ."],"takhrij":"متَّفقٌ عليه: رواه مالك في الطهارة (76) عن عبدالله بن دينار، عن عبدالله بن عمر، عن عمر بن الخطاب، فذكر الحديث،","grade":"متفق عليه","chapter_ar":"باب ما جاء في الجنب يريد أن يأكل وينام","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (76), al-Bukhārī (290), and Muslim (306).","chapter_en":"What Has Been Reported Concerning a Person in Janābah Who Wishes to Eat or Sleep","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["ʿUmar ibn al-Khaṭṭāb said to the Messenger of Allah ﷺ that he would become junub during the night. The Messenger of Allah ﷺ said to him: “Perform wuḍūʾ, wash your private part, and then sleep.”"]},"buhuth":{"en":["In another narration recorded by al-Bukhārī and Muslim, he was asked:","“May one of us sleep while he is junub?”","He replied:","“Yes, if he performs wuḍūʾ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (76)، والبخاري (290)، ومسلم (306)."},{"num":1630,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّهُ كَانَ تُصِيبُهُ الْجَنَابَةُ بِاللَّيْلِ فَيُرِيدُ أَنْ يَنَامَ، فَأَمَرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَتَوَضَّأَ ثُمَّ يَنَامَ."],"takhrij":"صحيح: رواه ابن ماجه (586) قال: حدَّثنا أبو مروان العثماني محمد بن عثمان، ثنا عبد العزيز بن محمد، عن يزيد بن عبدالله بن الهاد، عن عبدالله بن خَبّاب، عن أبي سعيد الخدري، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في الجنب يريد أن يأكل وينام","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (586) and Aḥmad (11523).","chapter_en":"What Has Been Reported Concerning a Person in Janābah Who Wishes to Eat or Sleep","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī reported that he would become junub during the night and wish to sleep, so the Messenger of Allah ﷺ instructed him to perform wuḍūʾ and then sleep."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (586)، وأحمد (11523)."},{"num":1631,"demo":false,"sanad":"","matn":["عَنْ أَبِي إِسْحَاق قَالَ: سَأَلْتُ الأَسْوَدَ بْنَ يَزِيدَ عَمَّا حَدَّثَتْهُ عَائِشَةُ، عَنْ صَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتِ: كَانَ يَنَامُ أَوَّلَ اللَّيْلِ وَيُحْيِ آخِرَهُ، ثُمَّ إِنْ كَانَتْ لَهُ حَاجَةٌ إِلَى أَهْلِهِ، قَضَى حَاجَتَهُ ثُمَّ يَنَامُ، فَإِذَا كَانَ عِنْدَ النِّدَاءِ الأَوَّلِ، قَالَتِ: وَثَبَ، وَلَا وَاللَّهِ مَا قَالَتِ، قَامَ فَأَفَاضَ عَلَيْهِ الْمَاءَ، وَلَا وَاللَّهِ مَا قَالَتِ، اغْتَسَلَ وَأَنَا أَعْلَمُ مَا تُرِيدُ، وَإِنْ لَمْ يَكُنْ جُنُبًا، تَوَضَّأَ وُضُوءَ الرَّجُلِ لِلصَّلَاةِ، ثُمَّ صَلَّى الرَّكْعَتَيْنِ."],"takhrij":"متَّفقٌ عليه: رواه البخاري في التهجد (1146) من حديث شعبة، ومسلم في صلاة المسافرين (739) من حديث زهير أبي خيثمة كلاهما، عن أبي إسحاق واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب جواز النوم للجنب بدون وضوء","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1146) and Muslim (739), whose wording this is; also narrated by Aḥmad (24706).","chapter_en":"The Permissibility of a Person in Janābah Sleeping without Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Abū Isḥāq said: I asked al-Aswad ibn Yazīd concerning what ʿĀʾishah had narrated to him about the prayer of the Messenger of Allah ﷺ. She said: “He used to sleep during the first part of the night and keep the latter part alive in worship. If he had a need for his wife, he would fulfill his need and then sleep. When the first call came, he would spring up”—and, by Allah, she did not say merely, “he stood”—“and he would pour water over himself.” And, by Allah, she did not say, “he performed ghusl,” and I know what you mean. If he was not junub, he would perform the wuḍūʾ of a man preparing for prayer and then pray the two rakʿahs."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1146)، ومسلم (739)، واللفظ لمسلم، ورواه أحمد (24706)."},{"num":1632,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا أَتَى أَحَدُكُمْ أَهْلَهُ، ثُمَّ أَرَادَ أَنْ يَعُودَ، فَلْيَتَوَضَّأْ.","زَادَ أَبُو بَكْرٍ فِي حَدِيثِهِ بَيْنَهُمَا وُضُوءًا، وَقَالَ: ثُمَّ أَرَادَ أَنْ يُعَاوِدَ.","وَفِي رِوَايَةِ: إِذَا أَتَى أَحَدُكُمْ أَهْلَهُ، ثُمَّ بَدَا لَهُ أَنْ يُعَاوِدَ، فَلْيَتَوَضَّأْ بَيْنَهُمَا وُضُوءًا."],"takhrij":"صحيح: رواه مسلم في الحيض (308) وأبو داود (220) من طرقٍ عن عاصم الأحول، عن أبي المُتوكِّل، عن أبي سعيد الخدري قال: فذكره.","grade":"صحيح","chapter_ar":"باب استحباب الوضوء للجنب إذا أراد أن يعود","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (308).","chapter_en":"The Recommendation for a Person in Janābah to Perform Wuḍūʾ before Returning to Intimacy","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":23,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī reported that the Messenger of Allah ﷺ said: “When one of you has relations with his wife and then wishes to return again, let him perform wuḍūʾ between the two occasions.”"]},"buhuth":{"en":["Ibn Khuzaymah (221) and Ibn Ḥibbān (1211) add:","“For it gives greater vigor for returning again.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (308)."},{"num":1633,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ، أَنَّ رَجُلًا سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَأَتَوَضَّأُ مِنْ لُحُومِ الْغَنَمِ ؟ قَالَ: إِنْ شِئْتَ فَتَوَضَّأْ، وَإِنْ شِئْتَ فَلَا تَوَضَّأْ، قَالَ: أَتَوَضَّأُ مِنْ لُحُومِ الإِبِلِ ؟ قَالَ: نَعَمْ، فَتَوَضَّأْ مِنْ لُحُومِ الإِبِلِ، قَالَ: أُصَلِّي فِي مَرَابِضِ الْغَنَمِ ؟ قَالَ: نَعَمْ، قَالَ: أُصَلِّي فِي مَبَارِكِ الإِبِلِ ؟ قَالَ: لَا."],"takhrij":"صحيح: أخرجه مسلم في الحيض (360)، عن أبي كامل الجحدري، ثنا أبو عوانة، عن عثمان بن عبدالله بن موهب، عن جعفر بن أبي ثور، عن جابر بن سمرة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب نقض الوضوء من لحوم الإبل","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (360).","chapter_en":"Wuḍūʾ Being Required after Eating Camel Meat","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":24,"content":{"translation":{"en":["Jābir ibn Samurah reported that a man asked the Messenger of Allah ﷺ: “Should I perform wuḍūʾ after eating sheep meat?” He said: “If you wish, perform wuḍūʾ, and if you wish, do not.” He asked: “Should I perform wuḍūʾ after eating camel meat?” He said: “Yes. Perform wuḍūʾ after eating camel meat.” He asked: “May I pray in sheep pens?” He replied: “Yes.” He asked: “May I pray in the resting places of camels?” He replied: “No.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (360)."},{"num":1634,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ قَالَ: سُئِلَ رَسُولُ اللّَهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْوُضُوءِ مِنْ لُحُومِ الْإِبِلِ، فَقَالَ: تَوَضَّئُوا مِنْهَا، وَسُئِلَ عَنْ لُحُومِ الْغَنَمِ، فَقَالَ: لَا تَوَضَّئُوا مِنْهَا، وَسُئِلَ عَنِ الصَّلَاةِ فِي مَبَارِكِ الْإِبِلِ، فَقَالَ: لَا تُصَلُّوا فِي مَبَارِكِ الْإِبِلِ فَإِنَّهَا مِنَ الشَّيَاطِينِ، وَسُئِلَ عَنِ الصَّلَاةِ فِي مَرَابِضِ الْغَنَمِ، فَقَالَ: صَلُّوا فِيهَا فَإِنَّهَا بَرَكَةٌ."],"takhrij":"حسن: رواه أبو داود (184) واللفظ له، والترمذي (81) وابن ماجه (494) مُختصراً، كلهم من حديث أبي معاوية، ثنا الأعمش، عن عبدالله بن عبدالله الرازي، عن عبدالرحمن بن أبي ليلى، عن البراء، فذكر الحديث.","grade":"حسن","chapter_ar":"باب نقض الوضوء من لحوم الإبل","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (184), whose wording this is, al-Tirmidhī (81), and Ibn Mājah (494).","chapter_en":"Wuḍūʾ Being Required after Eating Camel Meat","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":24,"content":{"translation":{"en":["Al-Barāʾ ibn ʿĀzib reported: The Messenger of Allah ﷺ was asked about performing wuḍūʾ after eating camel meat, and he said: “Perform wuḍūʾ after eating it.” He was asked about sheep meat, and he said: “Do not perform wuḍūʾ after eating it.” He was asked about praying in the resting places of camels, and he said: “Do not pray in the resting places of camels, for they are from the devils.” He was asked about praying in sheep pens, and he said: “Pray in them, for they are a blessing.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (184)، واللفظ له، والترمذي (81)، وابن ماجه (494)."},{"num":1635,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ ثَابِتٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: الْوُضُوءُ مِمَّا مَسَّتِ النَّارُ."],"takhrij":"صحيح: رواه مسلم في الحيض (351)، عن عبد الملك بن شعيب، حدَّثني أبي، عن جدِّي، حدّثني عقيل بن خالد، قال ابن شهاب: أخبرني عبدالملك بن أبي بكر بن عبدالرحمن بن الحارث بن هشام، أنَّ خارجة بن زيد أخبر أنَّ أباه زيد بن ثابت قال:فذكره.","grade":"صحيح","chapter_ar":"باب الوضوء مما مسته النار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (351).","chapter_en":"Performing Wuḍūʾ after Eating Food Touched by Fire","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":25,"content":{"translation":{"en":["Zayd ibn Thābit said: I heard the Messenger of Allah ﷺ say: “Wuḍūʾ is required because of what fire has touched.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (351)."},{"num":1636,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ إِبْرَاهِيمَ بْنِ قَارِظٍ أَخْبَرَهُ، أَنَّهُ وَجَدَ أَبَا هُرَيْرَةَ، يَتَوَضَّأُ عَلَى الْمَسْجِدِ فَقَالَ: إِنَّمَا أَتَوَضَّأُ مِنْ أَثْوَارِ أَقِطٍ أَكَلْتُهَا، لِأَنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: تَوَضَّئُوا مِمَّا مَسَّتِ النَّارُ."],"takhrij":"صحيح: رواه مسلم في الحيض (352) من حديث ابن شهاب، عن عمر بن عبد العزيز، أنَّ عبدالله بن إبراهيم بن قارظ أخبره .. فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الوضوء مما مسته النار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (352).","chapter_en":"Performing Wuḍūʾ after Eating Food Touched by Fire","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":25,"content":{"translation":{"en":["ʿAbdullāh ibn Ibrāhīm ibn Qāriẓ reported that he found Abū Hurayrah performing wuḍūʾ in the mosque. Abū Hurayrah said: “I am only performing wuḍūʾ because I ate pieces of aqiṭ, for I heard the Messenger of Allah ﷺ say: ‘Perform wuḍūʾ because of what fire has touched.’”"]},"buhuth":{"en":["Aqiṭ is dried, hardened milk. Athwār is the plural of thawr and here means pieces or chunks of aqiṭ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (352)."},{"num":1637,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَوَضَّئُوا مِمَّا مَسَّتِ النَّارُ."],"takhrij":"صحيح: رواه مسلم في الحيض (353) من حديث ابن شهاب، أخبرني سعيد بن خالد، أنَّه سأل عروة بن الزبير، عن الوضوء ممَّا مَسَّت النار. قال عروة: سمعت عائشة فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب الوضوء مما مسته النار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (353).","chapter_en":"Performing Wuḍūʾ after Eating Food Touched by Fire","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":25,"content":{"translation":{"en":["ʿĀʾishah reported that the Messenger of Allah ﷺ said: “Perform wuḍūʾ because of what fire has touched.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (353)."},{"num":1638,"demo":false,"sanad":"","matn":["عَنْ أَبِي طَلْحَةَ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: تَوَضَّئُوا مِمَّا أَنْضَجَتِ النَّارُ."],"takhrij":"صحيح: رواه النسائي (178) قال: أخبرنا هارون بن عبدالله قال: حدثني حَرَمِي بن عُمارة، قال: حدَّثنا شعبة، عن أبي بكر بن حفص، عن ابن شهاب، عن ابن أبي طلحة، عن أبي طلحة، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الوضوء مما مسته النار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasāʾī (178).","chapter_en":"Performing Wuḍūʾ after Eating Food Touched by Fire","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":25,"content":{"translation":{"en":["Abū Ṭalḥah reported that the Prophet ﷺ said: “Perform wuḍūʾ because of what fire has cooked.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (178)."},{"num":1639,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ أَنْهَا كَانَتْ تَشْهَدُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ: يَتَوَضَّأُ مِمَّا مَسَّتْ النَّارُ."],"takhrij":"حسن: رواه أحمد (26724)، والطبراني في الكبير (23/ح 924) كلاهما من طريق عبد العزيز بن محمد الدراوردي، عن محمد بن طحلاء، عن أبي سلمة، عن أم سلمة فذكرته.","grade":"حسن","chapter_ar":"باب الوضوء مما مسته النار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Aḥmad (26724) and al-Ṭabarānī in al-Muʿjam al-Kabīr (23/387).","chapter_en":"Performing Wuḍūʾ after Eating Food Touched by Fire","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":25,"content":{"translation":{"en":["Umm Salamah testified that the Messenger of Allah ﷺ used to perform wuḍūʾ because of what fire had touched."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (26724)، والطبراني في المعجم الكبير (23/387)."},{"num":1640,"demo":false,"sanad":"","matn":["عَنْ سُوَيْدِ بْنِ النُّعْمَانِ، أَنَّهُ أَخْبَرَهُ أَنَّهُ خَرَجَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ خَيْبَرَ . حَتَّى إِذَا كَانُوا بِالصَّهْبَاءِ، وَهِيَ مِنْ أَدْنَى خَيْبَرَ نَزَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَلَّى الْعَصْرَ، ثُمَّ دَعَا بِالْأَزْوَادِ فَلَمْ يُؤْتَ إِلَّا بِالسَّوِيقِ، فَأَمَرَ بِهِ فَثُرِّيَ، فَأَكَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَكَلْنَا، ثُمَّ قَامَ إِلَى الْمَغْرِبِ فَمَضْمَضَ وَمَضْمَضْنَا، ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ."],"takhrij":"صحيح: رواه مالك في الطهارة (20) عن يحيى بن سعيد، عن بُشَير بن يسار مولى بني حارثة، عن سُوَيد بن النعمان، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ترك الوضوء مما مسته النار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik (20) and al-Bukhārī (209).","chapter_en":"Not Performing Wuḍūʾ after Eating Food Touched by Fire","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["Suwayd ibn al-Nuʿmān reported that he went out with the Messenger of Allah ﷺ in the year of Khaybar. When they reached al-Ṣahbāʾ—which is near Khaybar—the Messenger of Allah ﷺ stopped and prayed ʿAṣr. He then called for provisions, but nothing was brought except sawīq. He ordered that it be moistened with water. The Messenger of Allah ﷺ ate, and we ate with him. He then rose for Maghrib. He rinsed his mouth and we rinsed ours, then he prayed without performing a new wuḍūʾ."]},"buhuth":{"en":["Al-Ṣahbāʾ is the feminine form of aṣhab. Yaḥyā ibn Saʿīd al-Anṣārī, the teacher of Mālik, explained that it is near Khaybar, on the side approached when traveling from Madinah. It has also been said to be the name of a mountain overlooking Khaybar from the south, today called Jabal ʿAṭwah. At al-Ṣahbāʾ there was a mosque near which the Messenger of Allah ﷺ married Ṣafiyyah bint Ḥuyayy, as mentioned in Wafāʾ al-Wafāʾ.","The word “thuriya,” with a ḍammah on the thāʾ and a doubled rāʾ, though the rāʾ may also be lightened, means that the sawīq was moistened with water after it had become dry."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (20)، والبخاري (209)."},{"num":1641,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَكَلَ كَتِفَ شَاةٍ ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ."],"takhrij":"متَّفقٌ عليه: رواه مالك في الطهارة (19) عن زيد بن أسلم، عن عطاء ابن يسار، عن عبدالله بن عباس، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ترك الوضوء مما مسته النار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (19), al-Bukhārī (207), and Muslim (354).","chapter_en":"Not Performing Wuḍūʾ after Eating Food Touched by Fire","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās reported that the Messenger of Allah ﷺ ate the shoulder of a sheep and then prayed without performing wuḍūʾ."]},"buhuth":{"en":["In Muslim’s wording:","“And he did not touch water.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (19)، والبخاري (207)، ومسلم (354)."},{"num":1642,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ، أَنَّهُ رَأَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَحْتَزُّ مِنْ كَتِفِ شَاةٍ، فَدُعِيَ إِلَى الصَّلَاةِ، فَأَلْقَى السِّكِّينَ، فَصَلَّى وَلَمْ يَتَوَضَّأْ."],"takhrij":"متَّفقٌ عليه: رواه البخاري في الوضوء (208) ومسلم في الحيض (355) كلاهما من حديث ابن شهاب، عن جعفر بن عمرو بن أمية الضمري، عن أبيه فذكر الحديث، وزاد مسلم:فأكل منها.","grade":"متفق عليه","chapter_ar":"باب ترك الوضوء مما مسته النار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (208) and Muslim (355).","chapter_en":"Not Performing Wuḍūʾ after Eating Food Touched by Fire","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["ʿAmr ibn Umayyah al-Ḍamrī reported that he saw the Messenger of Allah ﷺ cutting meat from the shoulder of a sheep. He was then called to prayer, so he put down the knife and prayed without performing wuḍūʾ."]},"buhuth":{"ar":["وزاد مسلم:","«فَأَكَلَ مِنْهَا»."],"en":["Muslim adds:","“And he ate from it.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (208)، ومسلم (355)."},{"num":1643,"demo":false,"sanad":"","matn":["عَنْ مَيْمُونَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَكَلَ عِنْدَهَا كَتِفًا، ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ."],"takhrij":"متَّفقٌ عليه: أخرجه البخاري (210) ومسلم في الحيض (356) كلاهما من حديث بكير بن الاشج، عن كُريب مولى ابن عباس، عن ميمونة رضي الله عنها فذكرت الحديث.","grade":"متفق عليه","chapter_ar":"باب ترك الوضوء مما مسته النار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (210) and Muslim (356).","chapter_en":"Not Performing Wuḍūʾ after Eating Food Touched by Fire","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["Maymūnah reported that the Messenger of Allah ﷺ ate a shoulder of meat in her presence, then prayed without performing wuḍūʾ."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (210)، ومسلم (356)."},{"num":1644,"demo":false,"sanad":"","matn":["عَنْ أَبِي رَافِعٍ قَالَ: أَشْهَدُ لَكُنْتُ أَشْوِي لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَطْنَ الشَّاةِ، ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ."],"takhrij":"صحيح: أخرجه مسلم في الحيض (357) من طريق عمرو، حدَّثني سعيد بن أبي هِلال، عن عبدالله بن عبيدالله بن أبي رافع، عن أبي غطفان، عن أبي رافع.. فذكره.","grade":"صحيح","chapter_ar":"باب ترك الوضوء مما مسته النار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (357).","chapter_en":"Not Performing Wuḍūʾ after Eating Food Touched by Fire","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["Abū Rāfiʿ said: “I testify that I used to roast the belly meat of a sheep for the Messenger of Allah ﷺ, and afterward he would pray without performing wuḍūʾ.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (357)."},{"num":1645,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ يَقُولُ: قَرَّبْتُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خُبْزًا وَلَحْمًا فَأَكَلَ ثُمَّ دَعَا بِوَضُوءٍ فَتَوَضَّأَ بِهِ ثُمَّ صَلَّى الظُّهْرَ، ثُمَّ دَعَا بِفَضْلِ طَعَامِهِ فَأَكَلَ ثُمَّ قَامَ إِلَى الصَّلَاةِ وَلَمْ يَتَوَضَّأْ."],"takhrij":"حسن: رواه أبو داود (191) قال: حدَّثنا إبراهيم بن الحسن الخثعمي، ثنا حجّاج، قال ابن جريج: أخبرني محمد بن المنكدر، قال: سمعتُ جابر بن عبدالله يقول، فذكره.","grade":"حسن","chapter_ar":"باب ترك الوضوء مما مسته النار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (191).","chapter_en":"Not Performing Wuḍūʾ after Eating Food Touched by Fire","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: I brought bread and meat to the Prophet ﷺ and he ate. He then called for water for wuḍūʾ and performed wuḍūʾ, then prayed Ẓuhr. Afterward he called for the remainder of his food and ate from it. Then he stood for prayer without performing a new wuḍūʾ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (191)."},{"num":1646,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: كَانَ آخِرَ الْأَمْرَيْنِ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَرْكُ الْوُضُوءِ مِمَّا غَيَّرَتِ النَّارُ."],"takhrij":"صحيح: رواه أبو داود (192) والنسائي (185) من حديث علي بن عياش، ثنا شُعيب بن أبي حمزة، عن محمد بن المنكدر، عن جابر. وفي رواية النسائي: قال محمد بن المنكدر سمعت جابراً.","grade":"صحيح","chapter_ar":"باب ترك الوضوء مما مسته النار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (192) and al-Nasāʾī (185); authenticated by Ibn Khuzaymah (43).","chapter_en":"Not Performing Wuḍūʾ after Eating Food Touched by Fire","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: “The latter of the two practices of the Messenger of Allah ﷺ was not performing wuḍūʾ because of food changed by fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (192)، والنسائي (185)، وصححه ابن خزيمة (43)."},{"num":1647,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ، قَالَ: ضِفْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ، فَأَمَرَ بِجَنْبٍ فَشُوِيَ، وَأَخَذَ الشَّفْرَةَ فَجَعَلَ يَحُزُّ لِي بِهَا مِنْهُ، قَالَ: فَجَاءَ بِلَالٌ فَآذَنَهُ بِالصَّلَاةِ، قَالَ: فَأَلْقَى الشَّفْرَةَ، وَقَالَ: مَا لَهُ تَرِبَتْ يَدَاهُ ؟ وَقَامَ يُصَلِّ.","زَادَ الْأَنْبَارِيُّ: وَكَانَ شَارِبِي وَفَى فَقَصَّهُ لِي عَلَى سِوَاكٍ، أَوْ قَالَ: أَقُصُّهُ لَكَ عَلَى سِوَاكٍ."],"takhrij":"حسن: رواه أبو داود (188) قال: حدَّثنا عثمان بن أبي شيبة ومحمد بن سليمان الأنباري – المعنى، ، قالا: حدَّثنا وكيع، عن مسعر، عن أبي صخرة جامع بن شدَّاد، عن المغيرة بن عبدالله (اليشكري الكوفي) عن المغيرة بن شعبة.. فذكر الحديث.","grade":"حسن","chapter_ar":"باب ترك الوضوء مما مسته النار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (188).","chapter_en":"Not Performing Wuḍūʾ after Eating Food Touched by Fire","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah said: I was a guest of the Prophet ﷺ one night. He ordered that a piece of meat be roasted, then took a knife and began cutting pieces from it for me. Bilāl came and informed him that it was time for prayer. He put down the knife and said: “What is the matter with him? May his hands be covered with dust!” Then he stood and prayed. Al-Anbārī added: My moustache had grown long, so he trimmed it for me over a siwāk, or he said:","“I will trim it for you over a siwāk.”"]},"buhuth":{"en":["The expression “he ordered a janb” means a piece of meat.","The expression “May his hands be covered with dust” is a conventional Arabic expression used in blame or reprimand. Its literal wording is a supplication for poverty or destitution, but the Arabs did not necessarily intend the literal occurrence of what was said. It is comparable to conventional expressions such as “No, by Allah” and “Yes, by Allah,” and is treated among expressions that carry no intended binding oath and therefore require no expiation. Al-Khaṭṭābī mentioned this in his commentary on Abū Dāwūd."]}},"tuhfa":{},"full":1,"dr":1,"rep":[1330],"tks":"حسن: رواه أبو داود (188)."},{"num":1648,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَكَلَ كَتِفًا، فَجَاءَهُ بِلَالٌ، فَخَرَجَ إِلَى الصَّلَاةِ وَلَمْ يَمَسَّ مَاءً."],"takhrij":"صحيح: رواه النسائي (182) وابن ماجه (491) كلاهما من حديث جعفر بن محمد، عن أبيه، عن علي بن الحسين، عن زينب بنت أم سلمة، عن أم سلمة، فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب ترك الوضوء مما مسته النار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasāʾī (182) and Ibn Mājah (491); authenticated by Ibn Khuzaymah (44).","chapter_en":"Not Performing Wuḍūʾ after Eating Food Touched by Fire","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["Umm Salamah reported that the Messenger of Allah ﷺ ate a shoulder of meat. Bilāl then came to him, so he went out to the prayer without touching water."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (182)، وابن ماجه (491)، وصححه ابن خزيمة (44)."},{"num":1649,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمُرُّ بِالْقِدْرِ، فَيَأْخُذُ الْعَرْقَ، فَيُصِيبُ مِنْهُ ثُمَّ يُصَلِّي وَلَمْ يَتَوَضَّأْ، وَلَمْ يَمَسَّ مَاءً."],"takhrij":"صحيح: رواه أحمد (25282)، وأبو يعلى (4449) كلاهما من طريق حسين بن علي، عن زائدة، عن عبد العزيز بن رُفيع، عن عكرمة وابن أبي مليكة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ترك الوضوء مما مسته النار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (25282) and Abū Yaʿlā (4449). Al-Bazzār in Kashf al-Astār (298) adds: “He neither performed wuḍūʾ nor rinsed his mouth.”","chapter_en":"Not Performing Wuḍūʾ after Eating Food Touched by Fire","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["ʿĀʾishah said: The Messenger of Allah ﷺ would pass by a cooking pot, take a bone with meat on it, let its juices drip, and then pray without performing wuḍūʾ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (25282)، وأبو يعلى (4449). وعند البزار في كشف الأستار (298): «فما توضأ ولا تمضمض»."},{"num":1650,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ جَزْءٍ الزُّبَيْدِيِّ قَالَ: كُنَّا يَوْمًا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الصُّفَّةِ، فَوُضِعَ لَنَا طَعَامٌ فَأَكَلْنَا، ثُمَّ أُقِيمَتْ الصَّلَاةُ، فَصَلَّيْنَا وَلَمْ نَتَوَضَّأْ."],"takhrij":"صحيح: رواه أحمد (17705) عن هارون – قال ابنه عبدالله أبو عبدالرحمن – وسمعتُه أنا من هارون قال: حدَّثنا عبدالله بن وهب، قال: أخبرني حيوة بن شُريح، قال: أخبرني عُقبة بن مسلم، عن عبدالله بن الحارث بن جَزْء فذكر مثله.","grade":"صحيح","chapter_ar":"باب ترك الوضوء مما مسته النار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (17705).","chapter_en":"Not Performing Wuḍūʾ after Eating Food Touched by Fire","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["ʿAbdullāh ibn al-Ḥārith ibn Jazʾ al-Zubaydī said: One day we were with the Messenger of Allah ﷺ in al-Ṣuffah. Food was placed before us and we ate. Then the prayer was established, and we prayed without performing wuḍūʾ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (17705)."},{"num":1651,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَكَلَ كَتِفَ شَاةٍ فَمَضْمَضَ، وَغَسَلَ يَدَيْهِ، وَصَلَّى."],"takhrij":"حسن: رواه ابن ماجه (493) قال:حدَّثنا محمد بن عبد الملك بن أبي الشوارب، ثنا عبد العزيز بن المختار، ثنا سهيل، عن أبيه، عن أبي هريرة، فذكر الحديث.","grade":"حسن","chapter_ar":"باب ترك الوضوء مما مسته النار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Ibn Mājah (493), Ibn Khuzaymah (42), and Ibn Ḥibbān (1051).","chapter_en":"Not Performing Wuḍūʾ after Eating Food Touched by Fire","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ ate the shoulder of a sheep, rinsed his mouth, washed his hands, and then prayed."]},"buhuth":{"en":["Ibn Ḥibbān’s wording states that Abū Hurayrah saw the Prophet ﷺ perform wuḍūʾ after eating a piece of dried curd, and later saw him eat the shoulder of a sheep and then pray without performing wuḍūʾ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (493)، وابن خزيمة (42)، وابن حبان (1051)."},{"num":1652,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ ،أ َنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَرِبَ لَبَنًا، ثُمَّ دَعَا بِمَاءٍ، فَتَمَضْمَضَ، وَقَالَ: إِنَّ لَهُ دَسَمًا."],"takhrij":"متَّفقٌ عليه: البخاري في الوضوء (211) ومسلم في الحيض(358) كلاهما عن قتيبة بن سعيد، ثنا الليث، عن عُقيل، عن الزهري، عن عبيدالله بن عبدالله، عن ابن عباس، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب المضمضة من شرب اللبن","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (211) and Muslim (358).","chapter_en":"Rinsing the Mouth after Drinking Milk","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās said: The Prophet ﷺ drank milk, then called for water, rinsed his mouth, and said: “It contains fat.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (211)، ومسلم (358)."},{"num":1653,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ يَقُولُ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَرِبَ لَبَنًا، فَلَمْ يُمَضْمِضْ وَلَمْ يَتَوَضَّأْ وَصَلَّى."],"takhrij":"حسن: رواه أبو داود (197) قال: حدَّثنا عثمان بن أبي شيبة، عن زيد بن الحباب، عن مطيع بن راشد، عن توبة العنبري، أنه سمع أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب المضمضة من شرب اللبن","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (197).","chapter_en":"Rinsing the Mouth after Drinking Milk","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ drank milk, did not rinse his mouth, did not perform wuḍūʾ, and then prayed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (197)."},{"num":1654,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: أُقِيمَتِ الصَّلَاةُ وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُنَاجِي رَجُلًا فِي جَانِبِ الْمَسْجِدِ، فَمَا قَامَ إِلَى الصَّلَاةِ حَتَّى نَامَ الْقَوْمُ."],"takhrij":"متَّفقٌ عليه: رواه البخاري في الاذان (642) وفي الاستئذان (6292) ومسلم في الحيض (376) كلاهما من طريق عبد العزيز بن صهيب، عن أنس، واللفظ للبخاري، وفي رواية مسلم عن قتادة قال: سمعت أنساً يقول:كان أصحاب رسول الله صلى الله عليه وسلم ينامون، ثم يصلون ولا يتوضأون. قال: قلت: سمعته من أنس؟ قال: إي والله!. وفي رواية أبي داود (200):ينتظرون العشاء الاخرة حتَّى تخفق رؤوسُهم، ثم يصلون ولا يتوضأون. وفي رواية عنده عن ثابت، عن أنس قال:أقيمت صلاة العشاء، فقال رجل: لي حاجة، فقام النبي صلى الله عليه وسلم يناجيه حتَّى نام القوم – أو بعض القوم – ثم صلوا. وفي البخاري (642):فحبسه بعدما أقيمتِ الصلاة.","grade":"متفق عليه","chapter_ar":"باب أن النوم ليس حدثًا بل مظنة للحدث","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6292, 642) and Muslim (376). This wording is that of al-Bukhārī.","chapter_en":"Sleep Is Not Itself a Nullifier, but Is a Likely Occasion for a Nullifier to Occur","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Anas ibn Mālik said: The prayer was established while the Prophet ﷺ was privately speaking with a man at the side of the mosque. He did not stand for the prayer until the people had fallen asleep."]},"buhuth":{"en":["In Muslim’s narration, Qatādah said: I heard Anas say:","“The Companions of the Messenger of Allah ﷺ used to sleep, then pray without performing wuḍūʾ.”","I asked:","“Did you hear this from Anas?”","He replied:","“Yes, by Allah.”","In Abū Dāwūd (200):","“They would wait for the later ʿIshāʾ prayer until their heads nodded from sleep, then they would pray without performing wuḍūʾ.”","In another narration of Abū Dāwūd from Thābit, from Anas: The ʿIshāʾ prayer was established, and a man said: “I have a need.” The Prophet ﷺ stood speaking privately with him until the people—or some of them—fell asleep, and then they prayed.","In al-Bukhārī (642):","“He kept him occupied after the prayer had already been established.”","Al-Khaṭṭābī said:","“This hadith contains the legal indication that sleep itself is not a nullifier. Were sleep itself a nullifier, then whenever it occurred it would invalidate purification regardless of its condition, just as with the other nullifiers, for which little and much, intentional and unintentional, are alike in invalidating purification. Rather, sleep is an indication and likely occasion for a nullifier, because such a nullifier commonly occurs from a sleeping person without his awareness.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6292، 642)، ومسلم (376)، واللفظ للبخاري."},{"num":1655,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شُغِلَ عَنْهَا (أَيْ صَلَاةِ الْعِشَاءِ) لَيْلَةً فَأَخَّرَهَا حَتَّى رَقَدْنَا فِي الْمَسْجِدِ، ثُمَّ اسْتَيْقَظْنَا، ثُمَّ رَقَدْنَا، ثُمَّ اسْتَيْقَظْنَا، ثُمَّ خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قَالَ: لَيْسَ أَحَدٌ مِنْ أَهْلِ الأَرْضِ اللَّيْلَةَ، يَنْتَظِرُ الصَّلَاةَ غَيْرُكُمْ."],"takhrij":"متَّفقٌ عليه: رواه البخاري في مواقيت الصلاة (570) ومسلم في المساجد (639) كلاهما من حديث عبد الرزاق قال: أخبرني ابن جريج، قال: أخبرني نافع، قال: حدَّثنا عبدالله بن عمر فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب أن النوم ليس حدثًا بل مظنة للحدث","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (570) and Muslim (639).","chapter_en":"Sleep Is Not Itself a Nullifier, but Is a Likely Occasion for a Nullifier to Occur","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Ibn ʿUmar reported that the Messenger of Allah ﷺ was occupied one night and delayed the ʿIshāʾ prayer until we slept in the mosque, then awoke, then slept again, then awoke again. The Prophet ﷺ then came out to us and said: “No one among the people of the earth is waiting for this prayer besides you.”"]},"buhuth":{"en":["The phrase “until we slept” does not mean that they lay down to sleep. Rather, they slept while seated. Sleep while seated in this manner does not invalidate wuḍūʾ, as is apparent from this hadith."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (570)، ومسلم (639)."},{"num":1656,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: أَعْتَمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْعِشَاءِ حَتَّى نَادَاهُ عُمَرُ الصَّلَاةَ نَامَ النِّسَاءُ وَالصِّبْيَانُ فَخَرَجَ، فَقَالَ: مَا يَنْتَظِرُهَا أَحَدٌ مِنْ أَهْلِ الْأَرْضِ غَيْرُكُمْ، قَالَ: وَلَا يُصَلَّى يَوْمَئِذٍ إِلَّا بِالْمَدِينَةِ...(فَذَكَرَتِ الْحَدِيثَ)."],"takhrij":"متَّفقٌ عليه: رواه البخاري في المواقيت (569) ومسلم في المساجد (638) كلاهما من طريق ابن شهاب، عن عروة، عن عائشة قالت، فذكرت الحديث. ومن وجه آخر عند مسلم: حتَّى نام أهل المسجد.","grade":"متفق عليه","chapter_ar":"باب أن النوم ليس حدثًا بل مظنة للحدث","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (569) and Muslim (638).","chapter_en":"Sleep Is Not Itself a Nullifier, but Is a Likely Occasion for a Nullifier to Occur","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["ʿĀʾishah said: The Messenger of Allah ﷺ delayed the ʿIshāʾ prayer until ʿUmar called out: “The prayer! The women and children have fallen asleep.” He came out and said: “No one among the people of the earth is waiting for it besides you.” At that time, it was not being prayed anywhere except Madinah."]},"buhuth":{"en":["In another route in Muslim:","“Until the people of the mosque had fallen asleep.”","Al-Nawawī, may Allah Most High have mercy on him, said:","“This is understood as sleep that does not invalidate wuḍūʾ, namely the sleep of a seated person whose sitting position remains firmly established. It is evidence that this kind of sleep does not invalidate wuḍūʾ. This is the position of the majority, and it is the correct view in our school.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (569)، ومسلم (638)."},{"num":1657,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: بِتُّ عِنْدَ خَالَتِي مَيْمُونَةَ لَيْلَةً، فَقَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ اللَّيْلِ، فَلَمَّا كَانَ فِي بَعْضِ اللَّيْلِ قَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَتَوَضَّأَ مِنْ شَنٍّ مُعَلَّقٍ وُضُوءًا خَفِيفًا يُخَفِّفُهُ عَمْرٌو وَيُقَلِّلُهُ، وَقَامَ يُصَلِّي فَتَوَضَّأْتُ نَحْوًا مِمَّا تَوَضَّأَ، ثُمَّ جِئْتُ فَقُمْتُ عَنْ يَسَارِهِ وَرُبَّمَا، قَالَ سُفْيَانُ: عَنْ شِمَالِهِ فَحَوَّلَنِي فَجَعَلَنِي عَنْ يَمِينِهِ، ثُمَّ صَلَّى مَا شَاءَ اللَّهُ، ثُمَّ اضْطَجَعَ فَنَامَ حَتَّى نَفَخَ، ثُمَّ أَتَاهُ الْمُنَادِي فَآذَنَهُ بِالصَّلَاةِ فَقَامَ مَعَهُ إِلَى الصَّلَاةِ فَصَلَّى وَلَمْ يَتَوَضَّأْ.","قُلْنَا لِعَمْرٍو: إِنَّ نَاسًا يَقُولُونَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَنَامُ عَيْنُهُ وَلَا يَنَامُ قَلْبُهُ؟ قَالَ عَمْرٌو: سَمِعْتُ عُبَيْدَ بْنَ عُمَيْرٍ يَقُولُ: رُؤْيَا الْأَنْبِيَاءِ وَحْيٌ، ثُمَّ قَرَأَ: ﴿إِنِّي أَرَى فِي الْمَنَامِ أَنِّي أَذْبَحُكَ﴾ [الصافات: 102]."],"takhrij":"متَّفقٌ عليه: رواه البخاري في الوضوء (138) واللفظ له، من حديث عمرو بن دينار، قال أخبرني كُريب، عن ابن عباس، فذكره. وفي مسلم، صلاة المسافرين (763): صلَّى من الليل ثلاث عشرة ركعة، ثم اضطجع فنام حتَّى نفخ، وكان إذا نام نفخ، فأتاه بلال فآذنه بالصلاة، فقام فصلى ولم يتوضأ. من حديث سلمة بن كُهَيل، عن كريب، عن ابن عباس، فذكر الحديث، وفيه ذكر للدعاء. ومن هذا الوجه أخرجه أيضاً البخاري في كتاب الدعاء (6316)، وسيأتي في كتاب الدعاء.","grade":"متفق عليه","chapter_ar":"باب أن النوم ليس حدثًا بل مظنة للحدث","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (138), whose wording this is, and Muslim (763).","chapter_en":"Sleep Is Not Itself a Nullifier, but Is a Likely Occasion for a Nullifier to Occur","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās said: I spent the night at the house of my maternal aunt Maymūnah. The Prophet ﷺ rose during the night, and after part of the night had passed, he performed a light wuḍūʾ from a hanging water-skin—ʿAmr would describe it as light and using little water—and then stood to pray. I performed wuḍūʾ similar to his and came and stood on his left. He moved me and placed me on his right. He then prayed for as long as Allah willed, afterward lay down and slept until he began breathing audibly. The caller then came and informed him that it was time for prayer. He arose with him, went to the prayer, and prayed without performing a new wuḍūʾ.","We said to ʿAmr: “Some people say that the eye of the Messenger of Allah ﷺ slept while his heart did not sleep.” ʿAmr said: I heard ʿUbayd ibn ʿUmayr say: “The dreams of the Prophets are revelation.” Then he recited: “Indeed, I have seen in a dream that I am sacrificing you.” [Sūrat al-Ṣāffāt 37:102]"]},"buhuth":{"ar":["وفي لفظ مسلم: صلى من الليل ثلاث عشرة ركعة، ثم اضطجع فنام حتى نفخ، وكان إذا نام نفخ، فأتاه بلال فآذنه بالصلاة، فقام فصلى ولم يتوضأ."],"en":["In Muslim’s wording, he prayed thirteen rakʿahs during the night, then lay down and slept until he breathed audibly. When he slept, he would breathe audibly. Bilāl then came to inform him of the prayer, and he stood and prayed without performing wuḍūʾ."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (138)، واللفظ له، ومسلم (763)."},{"num":1658,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنَامُ حَتَّى يَنْفُخَ، ثُمَّ يَقُومُ فَيُصَلِّي وَلَا يَتَوَضَّأُ.","قَالَ الطَّنَافِسِيُّ: قَالَ وَكِيعٌ: تَعْنِي وَهُوَ سَاجِدٌ."],"takhrij":"صحيح: رواه ابن ماجه (474) قال: حدَّثنا أبو بكر بن أبي شيبة وعلي بن محمد قالا: ثنا وكيع، ثنا الأعمش، عن إبراهيم، عن الأسود، عن عائشة، فذكر الحديث. والحديث في مصنف ابن أبي شيبة (1409). وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب أن النوم ليس حدثًا بل مظنة للحدث","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (474) and Ibn Abī Shaybah (1/132).","chapter_en":"Sleep Is Not Itself a Nullifier, but Is a Likely Occasion for a Nullifier to Occur","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["ʿĀʾishah said: The Messenger of Allah ﷺ would sleep until he breathed audibly, then rise and pray without performing wuḍūʾ. Al-Ṭanāfisī said: Wakīʿ said that she meant this occurred while he was in prostration."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (474)، وابن أبي شيبة (1409)."},{"num":1659,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنَامُ مُسْتَلْقِيًا حَتَّى يَنْفُخَ، ثُمَّ يَقُومُ فَيُصَلِّي وَلَا يَتَوَضَّأُ."],"takhrij":"صحيح: رواه أبو يعلى (5224) والبزار، زوائده (2437) كلاهما من طريق منصور بن أبي الأسود، عن الأعمش، عن إبراهيم، عن علقمة، عن عبدالله، فذكره.","grade":"صحيح","chapter_ar":"باب أن النوم ليس حدثًا بل مظنة للحدث","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Yaʿlā (3570) and al-Bazzār in his additional narrations (2437).","chapter_en":"Sleep Is Not Itself a Nullifier, but Is a Likely Occasion for a Nullifier to Occur","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd reported that the Messenger of Allah ﷺ would sleep lying on his back until he breathed audibly, then rise and pray without performing wuḍūʾ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو يعلى (5224)، والبزار في زوائده (2437)."},{"num":1660,"demo":false,"sanad":"","matn":["عَنْ جَدَّتِهَا أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ أَنَّهَا قَالَتْ: أَتَيْتُ عَائِشَةَ زَوْجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ خَسَفَتِ الشَّمْسُ، فَإِذَا النَّاسُ قِيَامٌ يُصَلُّونَ، وَإِذَا هِيَ قَائِمَةٌ تُصَلِّي، فَقُلْتُ: مَا لِلنَّاسِ ؟ فَأَشَارَتْ بِيَدِهَا نَحْوَ السَّمَاءِ، وَقَالَتْ: سُبْحَانَ اللَّهِ، فَقُلْتُ: آيَةٌ، فَأَشَارَتْ أَيْ نَعَمْ، فَقُمْتُ حَتَّى تَجَلَّانِي الْغَشْيُ وَجَعَلْتُ أَصُبُّ فَوْقَ رَأْسِي مَاءً، فَلَمَّا انْصَرَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: مَا مِنْ شَيْءٍ كُنْتُ لَمْ أَرَهُ إِلَّا قَدْ رَأَيْتُهُ فِي مَقَامِي هَذَا حَتَّى الْجَنَّةَ وَالنَّارَ، وَلَقَدْ أُوحِيَ إِلَيَّ أَنَّكُمْ تُفْتَنُونَ فِي الْقُبُورِ مِثْلَ أَوْ قَرِيبًا مِنْ فِتْنَةِ الدَّجَّالِ لَا أَدْرِي أَيَّ ذَلِكَ، قَالَتْ أَسْمَاءُ: يُؤْتَى أَحَدُكُمْ، فَيُقَالُ لَهُ مَا عِلْمُكَ بِهَذَا الرَّجُلِ ؟ فَأَمَّا الْمُؤْمِنُ أَوِ الْمُوقِنُ لَا أَدْرِي أَيَّ ذَلِكَ، قَالَتْ أَسْمَاءُ: فَيَقُولُ هُوَ مُحَمَّدٌ رَسُولُ اللَّهِ جَاءَنَا بِالْبَيِّنَاتِ وَالْهُدَى فَأَجَبْنَا وَآمَنَّا وَاتَّبَعْنَا، فَيُقَالُ لَهُ صَالِحًا: فَقَدْ عَلِمْنَا إِنْ كُنْتَ لَمُؤْمِنًا، وَأَمَّا الْمُنَافِقُ أَوِ الْمُرْتَابُ لَا أَدْرِي أَيَّ ذَلِكَ، قَالَتْ أَسْمَاءُ: فَيَقُولُ لَا أَدْرِي سَمِعْتُ النَّاسَ يَقُولُونَ شَيْئًا فَقُلْتُ."],"takhrij":"متَّفقٌ عليه: رواه مالك في الكسوف (4) عن هشام بن عروة، عن فاطمة بنت المنذر (وهي امرأته)، عن أسماء بنت أبي بكر (وهي جدتها) فذكرت الحديث، ومن طريقه البخاري (184).","grade":"متفق عليه","chapter_ar":"باب من لم يتوضأ من الغشي إلا إذا كان مثقلًا","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (4), al-Bukhārī (184), and Muslim (905).","chapter_en":"Faintness Does Not Require Wuḍūʾ Unless It Becomes Complete Unconsciousness","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Asmāʾ bint Abī Bakr said: I came to ʿĀʾishah, the wife of the Prophet ﷺ, when the sun was eclipsed. The people were standing in prayer, and she too was standing and praying. I asked: “What is happening to the people?” She pointed toward the sky and said: “Glory be to Allah!” I asked: “Is it a sign?” She indicated: “Yes.” I stood until faintness overcame me, and I began pouring water over my head. When the Messenger of Allah ﷺ finished, he praised Allah and extolled Him, then said: “There is nothing that I had not previously seen except that I have now seen it from this standing place of mine, even Paradise and the Fire. It has been revealed to me that you will be tested in your graves with a trial like—or close to—the trial of the Dajjāl.” Asmāʾ said that she did not know which of the two expressions had been used. “One of you will be brought and asked: ‘What did you know about this man?’ “As for the believer—or the one possessing certainty”—and Asmāʾ was unsure which wording was used—“he will say: ‘He is Muḥammad, the Messenger of Allah. He came to us with clear proofs and guidance, so we responded, believed, and followed.’” It will be said to him: ‘Sleep in righteousness. We have known that you were truly a believer.’ “As for the hypocrite—or the doubter”—and Asmāʾ was unsure which wording was used—“he will say: ‘I do not know. I heard the people saying something, so I said the same.’”"]},"buhuth":{"en":["Faintness is less severe than complete unconsciousness. Complete unconsciousness invalidates wuḍūʾ by scholarly consensus. The fact that Asmāʾ herself continued pouring water over her head demonstrates that her senses and awareness remained present."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (4)، والبخاري (184)، ومسلم (905)."},{"num":1661,"demo":false,"sanad":"","matn":["عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ يَقُولُ: دَخَلْتُ عَلَى مَرْوَانَ بْنِ الْحَكَمِ فَتَذَاكَرْنَا مَا يَكُونُ مِنْهُ الْوُضُوءُ، فَقَالَ مَرْوَانُ: وَمِنْ مَسِّ الذَّكَرِ الْوُضُوءُ، فَقَالَ عُرْوَةُ: مَا عَلِمْتُ هَذَا، فَقَالَ مَرْوَانُ بْنُ الْحَكَمِ: أَخْبَرَتْنِي بُسْرَةُ بِنْتُ صَفْوَانَ، أَنَّهَا سَمِعَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِذَا مَسَّ أَحَدُكُمْ ذَكَرَهُ فَلْيَتَوَضَّأْ."],"takhrij":"صحيح: رواه مالك في الطهارة (58) عن عبدالله بن أبي بكر بن محمد بن عمرو ابن حزم، أنه سمع عُروة، فذكر الحديث. ومن طريق مالك رواه أبو داود (181) والنسائي (163). وفي رواية عند النسائي (164) قال عروة: فلم أزل أُماري مروان حتَّى دعا رجلاً من حرسه، فأرسله إلى بُسْرَة يسألها عما حدّثتْ من ذلك، فأرسلتْ بسرةُ بمثل الذي حدَّثني عنها مروان.","grade":"صحيح","chapter_ar":"باب الوضوء من مس الفرج","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik (58), Abū Dāwūd (181), and al-Nasāʾī (163).","chapter_en":"Wuḍūʾ after Touching the Private Part","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":30,"content":{"translation":{"en":["ʿUrwah ibn al-Zubayr said: I entered upon Marwān ibn al-Ḥakam, and we discussed the things that require wuḍūʾ. Marwān said: “Wuḍūʾ is required after touching the penis.” ʿUrwah said: “I did not know this.” Marwān ibn al-Ḥakam replied: “Busrah bint Ṣafwān informed me that she heard the Messenger of Allah ﷺ say: ‘When one of you touches his penis, let him perform wuḍūʾ.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (58)، وأبو داود (181)، والنسائي (163)."},{"num":1662,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا أَفْضَى أَحَدُكُمْ بِيَدِهِ إِلَى فَرْجِهِ، وَلَيْسَ بَيْنَهُمَا سِتْرٌ وَلا حِجَابٌ، فَلْيَتَوَضَّأْ."],"takhrij":"حسن: رواه الطبراني في الأوسط (1871) والصغير sh13068(110) وابن حبّان (1118) كلُّهم من طريق أحمد بن سعيد الهمداني، قال: حدَّثنا أصبغ بن الفرج، قال: حدَّثنا عبدالرحمن بن القاسم، عن نافع بن أبي نعيم القاري، عن سعيد المقبري، عن أبي هريرة، فذكر الحديث.","grade":"حسن","chapter_ar":"باب الوضوء من مس الفرج","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ (1871), al-Muʿjam al-Ṣaghīr (110), and Ibn Ḥibbān (1118).","chapter_en":"Wuḍūʾ after Touching the Private Part","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":30,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “When one of you directly touches his private part with his hand, with no covering or barrier between them, let him perform wuḍūʾ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في المعجم الأوسط (1871)، والمعجم الصغير (110)، وابن حبان (1118)."},{"num":1663,"demo":false,"sanad":"","matn":["عَنْ أُمِّ حَبِيبَةَ قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ مَسَّ فَرْجَهُ فَلْيَتَوَضَّأْ."],"takhrij":"صحيح: رواه ابن ماجه (481) من وجهين عن الهيثم بن حميد، قال: حدثنا العلاء بن الحارث، عن مكحول، عن عنبسة بن أبي سفيان، عن أم حبيبة فذكرته.","grade":"صحيح","chapter_ar":"باب الوضوء من مس الفرج","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (481).","chapter_en":"Wuḍūʾ after Touching the Private Part","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":30,"content":{"translation":{"en":["Umm Ḥabībah said: I heard the Messenger of Allah ﷺ say: “Whoever touches his private part must perform wuḍūʾ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (481)."},{"num":1664,"demo":false,"sanad":"","matn":["عَنْ قَيْسِ بْنِ طَلْقٍ، عَنْ أَبِيهِ قَالَ: قَدِمْنَا عَلَى نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَ رَجُلٌ كَأَنَّهُ بَدَوِيٌّ فَقَالَ: يَا نَبِيَّ اللَّهِ! مَا تَرَى فِي مَسِّ الرَّجُلِ ذَكَرَهُ بَعْدَ مَا يَتَوَضَّأُ ؟ فَقَالَ: هَلْ هُوَ إِلَّا مُضْغَةٌ مِنْهُ ؟ أَوْ قَالَ: بَضْعَةٌ مِنْهُ."],"takhrij":"حسن: رواه أبو داود (182) والترمذي (85) واللفظ لهما، ورواه أيضاً النسائي (165) ولفظه:حتَّى قدمنا على رسول الله صلى الله عليه وسلم، فبايعناه وصلينا معه، فلما قضى الصلاة جاء رجل كأنه بدوي فقال: يا رسول الله! ما ترى في رجـل مسّ ذكره في الصـلاة؟ قال: وهل هو إلاَّ مُضغة منك؟، أو بَضْعة منك. كلهم رووه من حديث ملازم بن عمرو الحنفي، حدَّثنا عبدالله بن بدر، عن قيس بن طلق به.","grade":"حسن","chapter_ar":"باب ترك الوضوء من مس الذكر","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (183), al-Tirmidhī (85), whose wording they share, and al-Nasāʾī (165).","chapter_en":"Not Requiring Wuḍūʾ after Touching the Penis","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":31,"content":{"translation":{"en":["Ṭalq ibn ʿAlī said: We came to the Prophet of Allah ﷺ. A man who appeared to be a Bedouin came and asked: “O Prophet of Allah, what do you think about a man touching his penis after having performed wuḍūʾ?” He replied: “Is it anything other than a morsel of flesh from him?” Or he said: “A part of him.”"]},"buhuth":{"en":["Al-Nasāʾī’s wording states: We came to the Messenger of Allah ﷺ, pledged allegiance to him, and prayed with him. After he completed the prayer, a man resembling a Bedouin came and asked:","“O Messenger of Allah, what do you say concerning a man who touches his penis during prayer?”","He replied:","“Is it anything other than a morsel of flesh from you?”","Or:","“A part of you.”","Muḍghah means a bite-sized piece of flesh.","Baḍʿah means a piece of flesh larger than a muḍghah.","The conclusion stated here is that if the touching occurs with desire, wuḍūʾ is invalidated; if it occurs without desire, wuḍūʾ is not invalidated. This reconciliation is regarded here as preferable to the position that the hadith of Ṭalq ibn ʿAlī was abrogated by the hadith of Busrah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (182)، والترمذي (85)، واللفظ لهما، والنسائي (165)."},{"num":1665,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ الْمُسَيِّبِ وَعَبَّادِ بْنِ تَمِيمٍ عَنْ عَمِّهِ شُكِيَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، الرَّجُلُ يُخَيَّلُ إِلَيْهِ أَنَّهُ يَجِدُ الشَّيْءَ فِي الصَّلَاةِ، قَالَ: لَا يَنْصَرِفُ حَتَّى يَسْمَعَ صَوْتًا، أَوْ يَجِدَ رِيحًا."],"takhrij":"متَّفقٌ عليه: رواه البخاري (137) ومسلم في الحيض (361) كلاهما من حديث سفيان بن عيينة، عن الزهري، عن سعيد وعبّاد، فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب إذا شك في الحدث","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (137) and Muslim (361).","chapter_en":"When One Doubts Whether Wuḍūʾ Has Been Broken","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":32,"content":{"translation":{"en":["Saʿīd ibn al-Musayyib and ʿAbbād ibn Tamīm narrated from his uncle that a man complained to the Prophet ﷺ that he imagined he felt something during prayer. He said: “He should not leave until he hears a sound or detects an odor.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (137)، ومسلم (361)."},{"num":1666,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا وَجَدَ أَحَدُكُمْ فِي بَطْنِهِ شَيْئًا فَأَشْكَلَ عَلَيْهِ، أَخَرَجَ مِنْهُ شَيْءٌ أَمْ لَا، فَلَا يَخْرُجَنَّ مِنَ الْمَسْجِدِ حَتَّى يَسْمَعَ صَوْتًا، أَوْ يَجِدَ رِيحًا."],"takhrij":"صحيح: رواه مسلم في الحيض (362) عن زهير بن حرب، عن جرير، عن سُهَيْل، عن أبيه، عن أبي هريرة.","grade":"صحيح","chapter_ar":"باب إذا شك في الحدث","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (362).","chapter_en":"When One Doubts Whether Wuḍūʾ Has Been Broken","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":32,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “If one of you feels something in his abdomen and becomes uncertain whether anything has come out of him or not, he must not leave the mosque until he hears a sound or detects an odor.”"]},"buhuth":{"en":["Al-Tirmidhī (74) and Ibn Mājah (515) narrate the wording:","“No wuḍūʾ is required except because of a sound or an odor.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (362)."},{"num":1667,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَأْتِي أَحَدَكُمُ الشَّيْطَانُ فِي صَلاتِهِ حَتَّى يَنْفُخَ فِي مَقْعَدَتِهِ، فَيُخَيَّلُ إِلَيْهِ أَنَّهُ قَدْ أَحْدَثَ وَلَمْ يُحْدِثْ، فَإِذَا وَجَدَ ذَلِكَ أَحَدُكُمْ، فَلا يَنْصَرِفَنَّ حَتَّى يَسْمَعَ صَوْتًا بِأُذُنِهِ، أَوْ يَجِدَ رِيحًا بِأَنْفِهِ."],"takhrij":"حسن: رواه البزار - كشف الأستار (281): حدَّثنا محمد بن عمر، ثنا إسماعيل بن صبيح، ثنا أبو أويس، عن ثور بن يزيد، عن عكرمة، عن ابن عباس، فذكره.","grade":"حسن","chapter_ar":"باب إذا شك في الحدث","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by al-Bazzār in Kashf al-Astār (281).","chapter_en":"When One Doubts Whether Wuḍūʾ Has Been Broken","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":32,"content":{"translation":{"en":["Ibn ʿAbbās reported that the Messenger of Allah ﷺ said: “Satan comes to one of you during his prayer and blows at his backside, making him imagine that he has broken his wuḍūʾ when he has not. If one of you experiences this, he must not leave until he hears a sound with his ear or detects an odor with his nose.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (281)."},{"num":1668,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يَزَالُ الْعَبْدُ فِي صَلَاةٍ مَا كَانَ فِي الْمَسْجِدِ يَنْتَظِرُ الصَّلَاةَ، مَا لَمْ يُحْدِثْ.فَقَالَ رَجُلٌ أَعْجَمِيٌّ: مَا الْحَدَثُ يَا أَبَا هُرَيْرَةَ ؟ قَالَ: الصَّوْتُ يَعْنِي الضَّرْطَةَ.","وَفِي لَفْظُ: لَا تُقْبَلُ صَلَاةُ أَحَدِكُمْ إِذَا أَحْدَثَ، حَتَّى يَتَوَضَّأَ."],"takhrij":"متَّفقٌ عليه: رواه البخاري في الوضوء (176)، من طريق سعيد المقبري، ومسلم في الطهارة (225)، من طريق همَّام بن منبِّه، كلاهما عن أبي هريرة.. فذكر الحديث. وسيأتي بقية الأحاديث في كتاب الصلاة باب انتظار الصلاة.","grade":"متفق عليه","chapter_ar":"باب ما جاء في نقض الوضوء من خروج الصوت من الدبر","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (176) and Muslim (225).","chapter_en":"What Has Been Reported Concerning Wuḍūʾ Being Invalidated by Passing Wind","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":33,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said: “A servant continues to be regarded as being in prayer so long as he remains in the mosque waiting for the prayer, provided that he does not break his wuḍūʾ.” A non-Arab man asked: “What does breaking wuḍūʾ mean, O Abū Hurayrah?” He replied: “A sound,” meaning passing wind. In another wording:","“The prayer of one of you is not accepted after he breaks his wuḍūʾ until he performs wuḍūʾ.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (176)، ومسلم (225)."},{"num":1669,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا وُضُوءَ إِلَّا مِنْ صَوْتٍ أَوْ رِيحٍ."],"takhrij":"صحيح: رواه الترمذي (74) وابن ماجه (515) كلاهما من طريق شعبة، عن سهيل بن أبي صالح، عن أبيه، عن أبي هريرة.","grade":"صحيح","chapter_ar":"باب ما جاء في نقض الوضوء من خروج الصوت من الدبر","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (74) and Ibn Mājah (515). Al-Tirmidhī said: “Ḥasan ṣaḥīḥ,” and Ibn Khuzaymah authenticated it.","chapter_en":"What Has Been Reported Concerning Wuḍūʾ Being Invalidated by Passing Wind","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":33,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “No wuḍūʾ is required except because of a sound or an odor.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (74)، وابن ماجه (515). وقال الترمذي: حسن صحيح، وصححه ابن خزيمة."},{"num":1670,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: أَتَتْ سَلْمَى مَوْلَاةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوْ امْرَأَةُ أَبِي رَافِعٍ مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَسْتَأْذِنُهُ عَلَى أَبِي رَافِعٍ قَدْ ضَرَبَهَا، قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَبِي رَافِعٍ: مَا لَكَ وَلَهَا يَا أَبَا رَافِعٍ ؟ قَالَ: تُؤْذِينِي يَا رَسُولَ اللَّهِ! فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: بِمَ آذَيْتِيهِ يَا سَلْمَى ؟ قَالَتْ: يَا رَسُولَ اللَّهِ! مَا آذَيْتُهُ بِشَيْءٍ، وَلَكِنَّهُ أَحْدَثَ وَهُوَ يُصَلِّي، فَقُلْتُ لَهُ: يَا أَبَا رَافِعٍ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ أَمَرَ الْمُسْلِمِينَ إِذَا خَرَجَ مِنْ أَحَدِهِمْ الرِّيحُ أَنْ يَتَوَضَّأَ، فَقَامَ فَضَرَبَنِي، فَجَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَضْحَكُ وَيَقُولُ: يَا أَبَا رَافِعٍ! إِنَّهَا لَمْ تَأْمُرْكَ إِلَّا بِخَيْرٍ."],"takhrij":"حسن: رواه أحمد (26339) عن يعقوب، وهو ابن إبراهيم، ، قال: حدثني أبي، عن محمد بن إسحاق قال: حدثني هشام بن عروة، عن أبيه، عن عائشة، فذكرت الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في نقض الوضوء من خروج الصوت من الدبر","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Aḥmad (26339) and al-Bazzār in Kashf al-Astār (280).","chapter_en":"What Has Been Reported Concerning Wuḍūʾ Being Invalidated by Passing Wind","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":33,"content":{"translation":{"en":["ʿĀʾishah said: Salmā, the freedwoman of the Messenger of Allah ﷺ—or the wife of Abū Rāfiʿ, the freedman of the Messenger of Allah ﷺ—came to the Messenger of Allah ﷺ seeking permission to complain about Abū Rāfiʿ because he had struck her. The Messenger of Allah ﷺ said to Abū Rāfiʿ: “What is the matter between you and her, O Abū Rāfiʿ?” He replied: “She harms me, O Messenger of Allah.” The Messenger of Allah ﷺ asked: “How did you harm him, O Salmā?” She said: “O Messenger of Allah, I did not harm him at all. Rather, he broke his wuḍūʾ while praying, so I said to him: ‘O Abū Rāfiʿ, the Messenger of Allah ﷺ has instructed the Muslims that when wind comes out from one of them, he should perform wuḍūʾ.’ So he got up and struck me.” The Messenger of Allah ﷺ began laughing and said: “O Abū Rāfiʿ, she only instructed you to do something good.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (26339)، والبزار في كشف الأستار (280)."},{"num":1671,"demo":false,"sanad":"","matn":["عن أَبِي الدَّرْدَاءِ قَالَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَاءَ فَأَفْطَرَ،( قَالَ: مَعْدَانُ ابْنُ أَبِي طَلْحَةَ ) فَلَقِيتُ ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَسْجِدِ دِمَشْقَ فَقُلْتُ: إِنَّ أَبَا الدَّرْدَاءِ حدَّثَنِي أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَاءَ فَأَفْطَرَ، قَالَ: صَدَقَ، وَأَنَا صَبَبْتُ لَهُ وَضُوءَهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه أبو داود (2381) واللفظ له، والترمذي (87) كلاهما عن عبد الوارث، عن حسين بن ذكوان المعلم، عن يحيى بن أبي كثير، حدثني عبدالرحمن بن عمرو الأوزاعي، عن يعيش بن الوليد بن هشام، أن أباه حدثه، حدثني معدان بن أبي طلحة، أن أبا الدرداء حدثه، فذكر الحديث. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب من يرى الوضوء من القيء","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (2381), whose wording this is, and al-Tirmidhī (87).","chapter_en":"Those Who Hold That Vomiting Requires Wuḍūʾ","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":34,"content":{"translation":{"en":["Abū al-Dardāʾ said: The Messenger of Allah ﷺ vomited and broke his fast. Maʿdān ibn Abī Ṭalḥah said: I met Thawbān, the freedman of the Messenger of Allah ﷺ, in the mosque of Damascus and said: “Abū al-Dardāʾ told me that the Prophet ﷺ vomited and broke his fast.” He replied: “He spoke the truth, and I poured out his water for wuḍūʾ for him.”"]},"buhuth":{"en":["Al-Tirmidhī’s wording is:","“He vomited and then performed wuḍūʾ.”","Aḥmad (27502) also narrated it, and Ibn Khuzaymah (1957) authenticated the wording:","“He vomited and broke his fast.”","Those who understand Thawbān’s statement, “He vomited and broke his fast, and I poured his wuḍūʾ water for him,” as indicating wuḍūʾ after vomiting use it as evidence for that ruling.","As for the words “he vomited and broke his fast,” they require interpretation as meaning that he induced vomiting, because involuntary vomiting does not invalidate the fast."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2381)، واللفظ له، والترمذي (87)."},{"num":1672,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ قَالَ: كُنْتُ رَجُلًا مَذَّاءً، وَكُنْتُ أَسْتَحْيِي أَنْ أَسْأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِمَكَانِ ابْنَتِهِ، فَأَمَرْتُ الْمِقْدَادَ بْنَ الأَسْوَدِ فَسَأَلَهُ فَقَالَ: يَغْسِلُ ذَكَرَهُ وَيَتَوَضَّأُ."],"takhrij":"متَّفقٌ عليه: رواه البخاري في الوضوء (178) ومسلم في الحيض (303) كلاهما من طريق الأعمش، عن منذر بن يعلى (أبي يعلى)، عن محمد بن الحنفية، عن عليّ، فذكره. واللفظ لمسلم، وفي لفظ عند البخاري (269) من وجه آخر: توضّاْ، واغْسلْ ذكرَك قوله: واغْسل ذكرَك هذا مما لا خلاف فيه.","grade":"متفق عليه","chapter_ar":"باب الوضوء من المذي، والنضح بعده","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (178) and Muslim (303). This wording is that of Muslim.","chapter_en":"Wuḍūʾ Due to Madhy and Sprinkling Water afterward","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":35,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib said: I was a man who frequently experienced madhy, and I felt shy to ask the Prophet ﷺ because of his daughter, so I instructed al-Miqdād ibn al-Aswad to ask him. He said: “He should wash his penis and perform wuḍūʾ.”"]},"buhuth":{"en":["In al-Bukhārī (269):","“Perform wuḍūʾ and wash your penis.”","In Muslim, ʿAlī said: We sent al-Miqdād ibn al-Aswad to the Messenger of Allah ﷺ, and the wording includes:","“Perform wuḍūʾ and wash your private part.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (178)، ومسلم (303)، واللفظ لمسلم."},{"num":1673,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ حُنَيْفٍ قَالَ: كُنْتُ أَلْقَى مِنَ الْمَذْيِ شِدَّةً، وَكُنْتُ أُكْثِرُ مِنَ الِاغْتِسَالِ، فَسَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ، فَقَالَ: إِنَّمَا يُجْزِيكَ مِنْ ذَلِكَ الْوُضُوءُ، قُلْتُ: يَا رَسُولَ اللَّهِ، فَكَيْفَ بِمَا يُصِيبُ ثَوْبِي مِنْهُ ؟ قَالَ: يَكْفِيكَ بِأَنْ تَأْخُذَ كَفًّا مِنْ مَاءٍ فَتَنْضَحَ بِهَا مِنْ ثَوْبِكَ حَيْثُ تَرَى أَنَّهُ أَصَابَهُ."],"takhrij":"حسن: رواه أبو داود (210) والترمذي (115) وابن ماجه (506) كلهم من حديث محمد بن إسحاق، حدثني سعيد بن عبيد السبّاق، عن أبيه، عن سهل بن حُنيف، فذكره.","grade":"حسن","chapter_ar":"باب الوضوء من المذي، والنضح بعده","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (210), al-Tirmidhī (115), and Ibn Mājah (506). Al-Tirmidhī said: “Ḥasan ṣaḥīḥ.”","chapter_en":"Wuḍūʾ Due to Madhy and Sprinkling Water afterward","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":35,"content":{"translation":{"en":["Sahl ibn Ḥunayf said: I suffered greatly from madhy and used to perform ghusl frequently because of it. I asked the Messenger of Allah ﷺ about this, and he said: “Wuḍūʾ is sufficient for you because of that.” I asked: “O Messenger of Allah, what about what gets onto my garment from it?” He replied: “It is sufficient for you to take a handful of water and sprinkle it over the part of your garment where you think it has reached.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (210)، والترمذي (115)، وابن ماجه (506). وقال الترمذي: حسن صحيح."},{"num":1674,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ سَعْدٍ الْأَنْصَارِيِّ قَالَ: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَمَّا يُوجِبُ الْغُسْلَ، وَعَنِ الْمَاءِ يَكُونَ بَعْدَ الْمَاءِ، فَقَالَ: ذَاكَ الْمَذْيُ، وَكُلُّ فَحْلٍ يَمْذِي، فَتَغْسِلُ مِنْ ذَلِكَ فَرْجَكَ وَأُنْثَيَيْكَ وَتَوَضَّأْ وُضُوءَكَ لِلصَّلَاةِ."],"takhrij":"حسن: رواه أبو داود (211) قال: حدَّثنا إبراهيم بن موسى، أخبرنا عبدالله بن وهب، حدَّثنا معاوية، يعني ابن صالح، عن العلاء بن الحارث، عن حرام بن حكيم، عن عمه عبدالله بن سعد الأنصاري، فذكر الحديث.","grade":"حسن","chapter_ar":"باب الوضوء من المذي، والنضح بعده","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (211).","chapter_en":"Wuḍūʾ Due to Madhy and Sprinkling Water afterward","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":35,"content":{"translation":{"en":["ʿAbdullāh ibn Saʿd al-Anṣārī said: I asked the Messenger of Allah ﷺ about what makes ghusl obligatory and about the fluid that comes after the fluid. He said: “That is madhy, and every male emits madhy. So because of it, wash your private part and your testicles, and perform wuḍūʾ as you do for prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (211)."},{"num":1675,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِغُلَامٍ وَهُوَ يَسْلُخُ شَاةً، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَنَحَّ حَتَّى أُرِيَكَ، فَأَدْخَلَ يَدَهُ بَيْنَ الْجِلْدِ وَاللَّحْمِ فَدَحَسَ بِهَا حَتَّى تَوَارَتْ إِلَى الْإِبْطِ، ثُمَّ مَضَى فَصَلَّى لِلنَّاسِ وَلَمْ يَتَوَضَّأْ.","قَالَ أَبُو دَاوُد: زَادَ عَمْرٌو فِي حَدِيثِهِ يَعْنِي لَمْ يَمَسَّ مَاءً، وَقَالَ: عَنْ هِلَالِ بْنِ مَيْمُونٍ الرَّمْلِيِّ."],"takhrij":"حسن: رواه أبو داود (185) وابن ماجه (3179) كلاهما من طريق مروان بن معاوية، أخبرنا هلال بن ميمون الجُهَني، عن عطاء بن يزيد الليثي، قال هلال: لا أعلمه إلاَّ عن أبي سعيد، وقال أيوب وعمر: وأراه عن أبي سعيد، فذكروا الحديث.","grade":"حسن","chapter_ar":"باب ترك الوضوء من مس اللحم النيء","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (185) and Ibn Mājah (3179); authenticated by Ibn Ḥibbān (1163).","chapter_en":"Not Requiring Wuḍūʾ after Touching Raw Meat","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":36,"content":{"translation":{"en":["Abū Saʿīd reported that the Prophet ﷺ passed by a boy who was skinning a sheep. The Messenger of Allah ﷺ said to him: “Move aside so that I may show you.” He inserted his hand between the skin and the flesh and pushed it in until his hand disappeared up to his armpit. He then went and prayed without performing wuḍūʾ.","Abū Dāwūd said that ʿAmr added in his narration: meaning that he did not touch water."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (185)، وابن ماجه (3179)، وصححه ابن حبان (1163)."},{"num":1676,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَغْتَسِلُ وَيُصَلِّي الرَّكْعَتَيْنِ وَصَلَاةَ الْغَدَاةِ، وَلَا أَرَاهُ يُحْدِثُ وُضُوءًا بَعْدَ الْغُسْلِ."],"takhrij":"صحيح: رواه أبو داود (250) واللفظ له، والترمذي (107) والنسائي (252) وابن ماجه (579) كلهم من حديث أبي إسحاق، عن الأسود، عن عائشة، فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب ترك الوضوء من بعد الغسل","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (250), al-Tirmidhī (107), and al-Nasāʾī (252).","chapter_en":"Not Performing a Separate Wuḍūʾ after Ghusl","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":37,"content":{"translation":{"en":["ʿĀʾishah said: The Messenger of Allah ﷺ would perform ghusl, pray the two rakʿahs and the dawn prayer, and I do not think that he would perform a separate wuḍūʾ after the ghusl."]},"buhuth":{"en":["Al-Tirmidhī said: “Ḥasan ṣaḥīḥ.”","In another wording:","“The Messenger of Allah ﷺ would not perform wuḍūʾ after ghusl.”","Ibn Mājah (579) specifies:","“After ghusl from janābah.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1471],"tks":"صحيح: رواه أبو داود (250)، والترمذي (107)، والنسائي (252)."},{"num":1677,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ مِنَ الْخَلَاءِ، فَأُتِيَ بِطَعَامٍ، فَذَكَرُوا لَهُ الْوُضُوءَ، فَقَالَ: أُرِيدُ أَنْ أُصَلِّيَ فَأَتَوَضَّأَ؟.","وَفِي رِوَايَةِ: كُنَّا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَاءَ مِنَ الْغَائِطِ، وَأُتِيَ بِطَعَامٍ، فَقِيلَ لَهُ: أَلَا تَوَضَّأُ؟ فَقَالَ: لِمَ ؟ أَأُصَلِّي فَأَتَوَضَّأَ؟.","وَفِي رِوَايَةِ: قَالَ: لِمَ أَلِلصَّلَاةِ؟.","وَفِي رِوَايَةِ: مَا أَرَدْتُ صَلَاةً فَأَتَوَضَّأَ؟."],"takhrij":"صحيح: رواه مسلم في الحيض (374) من طريق عمرو بن دينار، عن سعيد بن الحُوَيْرِث، عن ابن عباس، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في جواز أكل الطعام للمحدث وأنه لا كراهة في ذلك","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (374).","chapter_en":"The Permissibility of Eating While in a State of Minor Ritual Impurity, and That There Is No Dislike in It","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":38,"content":{"translation":{"en":["Ibn ʿAbbās reported that the Prophet ﷺ came out after relieving himself, and food was brought to him. Wuḍūʾ was mentioned to him, so he said: “Do I intend to pray, such that I should perform wuḍūʾ?”","In another narration: We were with the Prophet ﷺ when he came after relieving himself and food was brought. He was asked: “Will you not perform wuḍūʾ?” He replied:","“For prayer?” In another wording: “I do not intend to pray, such that I should perform wuḍūʾ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (374)."},{"num":1678,"demo":false,"sanad":"","matn":["عَنِ الْمُهَاجِرِ بْنِ قُنْفُذٍ أَنَّهُ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَبُولُ فَسَلَّمَ عَلَيْهِ، فَلَمْ يَرُدَّ عَلَيْهِ حَتَّى تَوَضَّأَ، ثُمَّ اعْتَذَرَ إِلَيْهِ فَقَالَ: إِنِّي كَرِهْتُ أَنْ أَذْكُرَ اللَّهَ عَزَّ وَجَلَّ إِلا عَلَى طُهْرٍ، أَوْ قَالَ: عَلَى طَهَارَةٍ."],"takhrij":"صحيح: رواه أبو داود (17) واللفظ له، والنسائي (38) وابن ماجه (350) كلهم من طريق سعيد بن أبي عروبة، عن قتادة، عن الحسن، عن حُضين بن المنذر أبي ساسان، عن المهاجر بن قنفذ بن عمير فذكر مثله،","grade":"صحيح","chapter_ar":"باب الوضوء لرد السلام","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (17), whose wording this is, al-Nasāʾī (38), and Ibn Mājah (350).","chapter_en":"Performing Wuḍūʾ in Order to Return the Greeting of Salām","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":39,"content":{"translation":{"en":["Al-Muhājir ibn Qunfudh reported that he came to the Prophet ﷺ while he was urinating and greeted him with salām. The Prophet ﷺ did not return the greeting until he had performed wuḍūʾ. He then apologized and said: “I disliked mentioning Allah, Mighty and Majestic, except while in a state of purity.” Or he said: “While in a state of purification.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1445,10797],"tks":"صحيح: رواه أبو داود (17)، واللفظ له، والنسائي (38)، وابن ماجه (350)."},{"num":1679,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ قَالَ: كُنْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ فِي سَفَرٍ فَقَالَ: أَمَعَكَ مَاءٌ ؟ قُلْتُ: نَعَمْ، فَنَزَلَ عَنْ رَاحِلَتِهِ فَمَشَى حَتَّى تَوَارَى عَنِّي فِي سَوَادِ اللَّيْلِ، ثُمَّ جَاءَ فَأَفْرَغْتُ عَلَيْهِ الْإِدَاوَةَ، فَغَسَلَ وَجْهَهُ وَيَدَيْهِ، وَعَلَيْهِ جُبَّةٌ مِنْ صُوفٍ، فَلَمْ يَسْتَطِعْ أَنْ يُخْرِجَ ذِرَاعَيْهِ مِنْهَا حَتَّى أَخْرَجَهُمَا مِنْ أَسْفَلِ الْجُبَّةِ، فَغَسَلَ ذِرَاعَيْهِ ثُمَّ مَسَحَ بِرَأْسِهِ، ثُمَّ أَهْوَيْتُ لِأَنْزِعَ خُفَّيْهِ، فَقَالَ: دَعْهُمَا، فَإِنِّي أَدْخَلْتُهُمَا طَاهِرَتَيْنِ، فَمَسَحَ عَلَيْهِمَا."],"takhrij":"متَّفقٌ عليه: رواه البخاري في اللباس (5799)، ومسلم في الطهارة (274: 79) كلاهما من طريق زكريا، عن عامر، أخبرني عروة بن المغيرة، عن أبيه، فذكره.","grade":"متفق عليه","chapter_ar":"باب المسح على الخفين والعمامة والناصية والخمار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5799) and Muslim (274).","chapter_en":"Wiping over the Leather Socks, the Turban, the Forelock, and the Khimār","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":40,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah said: I was with the Prophet ﷺ one night during a journey. He asked: “Do you have water with you?” I replied: “Yes.” He dismounted from his riding animal and walked until he disappeared from my sight in the darkness of the night. He then returned, and I poured water for him from the water vessel. He washed his face and hands. He was wearing a woolen cloak with tight sleeves and could not bring his forearms out through them, so he brought his arms out from beneath the cloak and washed them. He then wiped his head. I bent down to remove his leather socks, but he said: “Leave them, for I put them on while I was in a state of purity.” He then wiped over them."]},"buhuth":{"en":["A note: Mālik narrated it in al-Ṭahārah (41) from Ibn Shihāb, from ʿAbbād ibn Ziyād—described as being from the descendants of al-Mughīrah ibn Shuʿbah—from his father, from al-Mughīrah ibn Shuʿbah.","Al-Bukhārī and Muslim did not include Mālik’s route in their Ṣaḥīḥs; rather, they transmitted the report through other routes, in both abbreviated and fuller forms. This was, and Allah knows best, because of two errors in Mālik’s chain noted by al-Dāraquṭnī: first, describing ʿAbbād as a descendant of al-Mughīrah, whereas the correct description is that he was a client of al-Mughīrah, as stated by al-Shāfiʿī, Muṣʿab al-Zubayrī, and others; and second, omitting ʿUrwah and Ḥamzah, the two sons of al-Mughīrah.","ʿAbbād did not hear from al-Mughīrah and did not see him. Al-Zuhrī transmits it from ʿAbbād, from ʿUrwah and Ḥamzah, the two sons of al-Mughīrah, from their father; at times al-Zuhrī narrates it from ʿUrwah alone without Ḥamzah. The hadith also has other routes from al-Mughīrah ibn Shuʿbah. See al-Minnah al-Kubrā (1/170–171).","In one narration of Muslim, he said: “Leave them, for I put them on while in a state of purity,” and he wiped over them. In another Muslim narration: “He wiped over the leather socks and the front of his head, and over his turban.” In another: “He wiped his forelock, his turban, and his leather socks.”","Al-Nasāʾī (109) narrates that al-Mughīrah ibn Shuʿbah said: “There are two matters about which I will not ask anyone after having witnessed them from the Messenger of Allah ﷺ. We were with him on a journey. He went away to relieve himself, then returned and performed wuḍūʾ, wiping his forelock and both sides of his turban and wiping over his leather socks. The other matter is the imam praying behind a man from among his subjects. I witnessed the Messenger of Allah ﷺ on a journey when the prayer became due. The Prophet ﷺ was delayed, so they established the prayer and put Ibn ʿAwf forward to lead them. The Messenger of Allah ﷺ arrived and prayed behind Ibn ʿAwf for the remainder of the prayer. When Ibn ʿAwf gave salām, the Prophet ﷺ stood and completed what he had missed.”","After narrating the hadith (100) concerning wiping over the leather socks and the turban, al-Tirmidhī said that a number of scholars among the Companions of the Prophet ﷺ, including Abū Bakr, ʿUmar, and Anas, permitted wiping over the turban; this was also the view of al-Awzāʿī, Aḥmad, and Isḥāq. Other scholars among the Companions and Tābiʿūn held that one should not wipe over the turban unless one also wipes part of the head with it; this was the view of Sufyān al-Thawrī, Mālik ibn Anas, Ibn al-Mubārak, and al-Shāfiʿī. Al-Tirmidhī also reported from Wakīʿ ibn al-Jarrāḥ that wiping over the turban suffices because of the transmitted report.","Al-Khaṭṭābī related from Imām Aḥmad that reports permitting wiping over the turban came from the Prophet ﷺ through five routes. He said that those who permitted it stipulated that the turban be put on after complete purification, just as with leather socks. He also stated that most jurists did not permit wiping over the turban alone. They interpreted the reports to mean that the Prophet ﷺ wiped part of his head without having to remove or undo the turban. They regarded the report of al-Mughīrah ibn Shuʿbah as explanatory, because it says that he wiped his forelock and his turban together. The obligatory wiping of the head was thus fulfilled by wiping the forelock, which is part of the head, while the turban followed it.","Ibn ʿAbd al-Barr said that a group of early scholars from the Companions and Tābiʿūn permitted wiping over the turban; among those who held this view were al-Awzāʿī, Abū ʿUbayd al-Qāsim ibn Sallām, Aḥmad, Isḥāq, and Abū Thawr, based on the transmitted reports—including the hadith of ʿAmr ibn Umayyah al-Ḍamrī in al-Bukhārī—and by analogy with the leather socks. He added that those who did not permit wiping over the turban or head-covering included ʿUrwah ibn al-Zubayr, al-Qāsim ibn Muḥammad, al-Shaʿbī, al-Nakhaʿī, and Ḥammād ibn Abī Sulaymān; this was also the position of Mālik, Abū Ḥanīfah, al-Shāfiʿī, and their followers. See al-Istidhkār (2/219).","His statement, “Leave them, for I put them on while in a state of purity,” is evidence that wiping over the leather socks is only permitted when they were put on after purification, meaning after wuḍūʾ. This is nearly agreed upon among those who permit wiping over the khuffs, with the exception of Dāwūd al-Ẓāhirī, who understood “purity” here as freedom from physical impurity even if the person was not yet in a state permitting prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5799)، ومسلم (274)."},{"num":1680,"demo":false,"sanad":"","matn":["عَنْ جَرِيرِ بْنِ عَبْدِ اللَّهِ الْبَجَلِيُّ أَنَّهُ بَالَ، ثُمَّ تَوَضَّأَ، وَمَسَحَ عَلَى خُفَّيْهِ، فَقِيلَ: تَفْعَلُ هَذَا؟ فَقَالَ: نَعَمْ، رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَالَ، ثُمَّ تَوَضَّأَ، وَمَسَحَ عَلَى خُفَّيْهِ."],"takhrij":"متَّفقٌ عليه: رواه البخاري في الصلاة (387) ومسلم في الطهارة (272) واللفظ له، كلاهما عن الأعمش، عن إبراهيم، عن همام بن الحارث قال: رأيت جريراً بال، وذكره.","grade":"متفق عليه","chapter_ar":"باب المسح على الخفين والعمامة والناصية والخمار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (387) and Muslim (272).","chapter_en":"Wiping over the Leather Socks, the Turban, the Forelock, and the Khimār","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":40,"content":{"translation":{"en":["Jarīr ibn ʿAbdillāh al-Bajalī urinated, then performed wuḍūʾ and wiped over his leather socks. He was asked: “Do you do this?” He replied: “Yes. I saw the Messenger of Allah ﷺ urinate, then perform wuḍūʾ and wipe over his leather socks.” Al-Aʿmash said that Ibrāhīm and the scholars with him particularly liked this hadith because Jarīr accepted Islam after the revelation of Sūrat al-Māʾidah."]},"buhuth":{"en":["In a narration of al-Tirmidhī, Jarīr was asked:","“When did you accept Islam?”","He replied:","“After al-Māʾidah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (387)، ومسلم (272)."},{"num":1681,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ، أَنَّهُ رَأَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمْسَحُ عَلَى الْخُفَّيْنِ."],"takhrij":"صحيح: رواه البخاري (204) وأحمد ( 22478 ،22486 ،17247، 17246) كلهم من طريق يحيى، عن أبي سلمة، عن جعفر بن عمرو بن أُميَّة الضَّمري، أنَّ أباه أخبره، فذكره.","grade":"صحيح","chapter_ar":"باب المسح على الخفين والعمامة والناصية والخمار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (204).","chapter_en":"Wiping over the Leather Socks, the Turban, the Forelock, and the Khimār","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":40,"content":{"translation":{"en":["ʿAmr ibn Umayyah al-Ḍamrī reported that he saw the Messenger of Allah ﷺ wiping over his leather socks."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (204)."},{"num":1682,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمْسَحُ عَلَى عِمَامَتِهِ وَخُفَّيْهِ."],"takhrij":"صحيح: رواه البخاري (205) عن عبدان، أخبرنا عبد الله، أخبرنا الأوزاعي، عن يحيى، عن أبي سلمة، عن جعفر بن عمرو بن أُميَّة الضَّمري، عن أبيه قال: فذكره.","grade":"صحيح","chapter_ar":"باب المسح على الخفين والعمامة والناصية والخمار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (205).","chapter_en":"Wiping over the Leather Socks, the Turban, the Forelock, and the Khimār","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":40,"content":{"translation":{"en":["ʿAmr ibn Umayyah al-Ḍamrī said: “I saw the Prophet ﷺ wiping over his turban and his leather socks.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (205)."},{"num":1683,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ أَنَّهُ قَالَ: أَنَّ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ مَسَحَ عَلَى الْخُفَّيْنِ، وَأَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ سَأَلَ عُمَرَ عَنْ ذَلِكَ؟ فَقَالَ: نَعَمْ، إِذَا حَدَّثَكَ شَيْئًا سَعْدٌ عَنِ النَّبِيّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَا تَسْأَلْ عَنْهُ غَيْرَهُ."],"takhrij":"صحيح: رواه البخاري في الوضوء (202)، عن أصبغ بن الفرج المصري، عن ابن وهب، قال: حدَّثني عمرو، حدَّثني أبو النضر، عن أبي سلمة بن عبدالرحمن، عن عبدالله بن عمر، عن سعد بن وقاص.. فذكر الحديث..","grade":"صحيح","chapter_ar":"باب المسح على الخفين والعمامة والناصية والخمار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (202).","chapter_en":"Wiping over the Leather Socks, the Turban, the Forelock, and the Khimār","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":40,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ reported that the Messenger of Allah ﷺ wiped over his leather socks. Ibn ʿUmar asked his father about this, and he replied: “Yes. If Saʿd narrates something to you from the Prophet ﷺ, then do not ask anyone else about it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (202)."},{"num":1684,"demo":false,"sanad":"","matn":["عَنْ بِلَالِ بْنِ رَبَاحٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَسَحَ عَلَى الْخُفَّيْنِ وَالْخِمَارِ."],"takhrij":"صحيح: رواه مسلم في الطهارة (275)، من طريق الأعمش، عن الحكم، عن عبدالرحمن بن أبي ليلى، عن كعب بن عُجرة، عن بلال.. فذكره.","grade":"صحيح","chapter_ar":"باب المسح على الخفين والعمامة والناصية والخمار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (275).","chapter_en":"Wiping over the Leather Socks, the Turban, the Forelock, and the Khimār","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":40,"content":{"translation":{"en":["Bilāl ibn Rabāḥ reported that the Messenger of Allah ﷺ wiped over his leather socks and the khimār."]},"buhuth":{"en":["The khimār here means the turban, as clarified in the other narrations.","A mūq is a type of leather footwear similar to the khuff."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (275)."},{"num":1685,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ حُصَيْبٍ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى الصَّلَوَاتِ يَوْمَ الْفَتْحِ بِوُضُوءٍ وَاحِدٍ، وَمَسَحَ عَلَى خُفَّيْهِ، فَقَالَ لَهُ عُمَرُ: لَقَدْ صَنَعْتَ الْيَوْمَ شَيْئًا لَمْ تَكُنْ تَصْنَعُهُ ؟ قَالَ: عَمْدًا صَنَعْتُهُ يَا عُمَرُ."],"takhrij":"صحيح: رواه مسلم في الطهارة (277) من حديث علقمة بن مَرْثَد، عن سليمان بن بُريدة، عن أبيه.. فذكر الحديث.","grade":"صحيح","chapter_ar":"باب المسح على الخفين والعمامة والناصية والخمار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (277).","chapter_en":"Wiping over the Leather Socks, the Turban, the Forelock, and the Khimār","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":40,"content":{"translation":{"en":["Buraydah ibn al-Ḥuṣayb reported that the Prophet ﷺ performed the prayers on the Day of the Conquest with a single wuḍūʾ and wiped over his leather socks. ʿUmar said to him: “Today you have done something you did not ordinarily do.” He replied: “I did it deliberately, O ʿUmar.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (277)."},{"num":1686,"demo":false,"sanad":"","matn":["عَنْ أَبِي عُبَيْدَةَ بْنِ مُحَمَّدِ بْنِ عَمَّارِ بْنِ يَاسِرٍ قَالَ: سَأَلْتُ جَابِرَ بْنَ عَبْدِ اللَّهِ عَنِ الْمَسْحِ عَلَى الْخُفَّيْنِ فَقَالَ: السُّنَّةُ يَا ابْنَ أَخِي قَالَ: وَسَأَلْتُهُ عَنِ الْمَسْحِ عَلَى الْعِمَامَةِ فَقَالَ: أَمِسَّ الشَّعَرَ الْمَاءَ."],"takhrij":"حسن: رواه الترمذي (102) قال: حدَّثنا قتيبة بن سعيد، حدَّثنا بشر بن المُفضَّل، عن عبدالرحمن بن إسحاق القرشي، عن أبي عبيدة به.","grade":"حسن","chapter_ar":"باب المسح على الخفين والعمامة والناصية والخمار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by al-Tirmidhī (102).","chapter_en":"Wiping over the Leather Socks, the Turban, the Forelock, and the Khimār","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":40,"content":{"translation":{"en":["Abū ʿUbaydah ibn Muḥammad ibn ʿAmmār ibn Yāsir said: I asked Jābir ibn ʿAbdillāh about wiping over the leather socks, and he replied: “It is the Sunnah, my nephew.” I also asked him about wiping over the turban, and he said: “Until the water touches the hair.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (102)."},{"num":1687,"demo":false,"sanad":"","matn":["عَنْ أَبِي يَعْفُورٍ قَالَ: سَأَلْتُ أَنَسَ بْنَ مَالِكٍ عَنِ الْمَسْحِ عَلَى الْخُفِينِ فَقَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمْسَحُ عَلَيْهِمَا."],"takhrij":"صحيح: رواه ابن حبان ( 1318) قال: أخبرنا محمد ابن عبيدالله بن الجنيد بِبُست، قال: حدَّثنا قتيبة بن سعيد، قال: حدَّثنا أبو عوانة، عن أبي يعفور، فذكره.","grade":"صحيح","chapter_ar":"باب المسح على الخفين والعمامة والناصية والخمار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Ḥibbān (1318).","chapter_en":"Wiping over the Leather Socks, the Turban, the Forelock, and the Khimār","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":40,"content":{"translation":{"en":["Abū Yaʿfūr said: I asked Anas ibn Mālik about wiping over the leather socks, and he said: “The Messenger of Allah ﷺ used to wipe over them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن حبان (1318)."},{"num":1688,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ قَالَ: بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَرِيَّةً فَأَصَابَهُمُ الْبَرْدُ، فَلَمَّا قَدِمُوا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَهُمْ أَنْ يَمْسَحُوا عَلَى الْعَصَائِبِ وَالتَّسَاخِينِ."],"takhrij":"حسن: رواه أبو داود (146): حدَّثنا أحمد بن محمد بن حنبل، ثنا يحيى بن سعيد، عن ثور، عن راشد بن سعد، عن ثوبان، فذكره.","grade":"حسن","chapter_ar":"باب المسح على الخفين والعمامة والناصية والخمار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (146) and Aḥmad (22383).","chapter_en":"Wiping over the Leather Socks, the Turban, the Forelock, and the Khimār","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":40,"content":{"translation":{"en":["Thawbān said: The Messenger of Allah ﷺ sent out a detachment, and they were afflicted by severe cold. When they returned to the Messenger of Allah ﷺ, he instructed them to wipe over the head-wraps and the tasākhīn."]},"buhuth":{"en":["Tasākhīn refers to anything worn upon the feet for warmth, such as leather socks, ordinary socks, and similar footwear."]}},"tuhfa":{},"full":1,"dr":1,"rep":[1700],"tks":"حسن: رواه أبو داود (146)، وأحمد (22383)."},{"num":1689,"demo":false,"sanad":"","matn":["عَنْ أَبِي طَلْحَةَ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ، فَمَسَحَ عَلَى الْخُفَّيْنِ وَالْخِمَارِ."],"takhrij":"حسن: رواه الطبراني في الصغير (1031) قال: حدَّثنا محمد بن الفضل ابن الأسود النضري، ثنا عمر بن شبة النميري، ثنا حرمى بن عُمارة، ثنا شعبة، عن عمرو بن دينار، عن يحيى بن جعدة، عن عبدالرحمن بن عبد القارّي، عن أبي طلحة، فذكره.","grade":"حسن","chapter_ar":"باب المسح على الخفين والعمامة والناصية والخمار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by al-Ṭabarānī in al-Muʿjam al-Ṣaghīr (1031).","chapter_en":"Wiping over the Leather Socks, the Turban, the Forelock, and the Khimār","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":40,"content":{"translation":{"en":["Abū Ṭalḥah reported that the Prophet ﷺ performed wuḍūʾ and wiped over his leather socks and the khimār."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في المعجم الصغير (1031)."},{"num":1690,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمْسَحُ عَلَى الْمُوقَيْنِ وَالْخِمَارِ."],"takhrij":"حسن: رواه الطبراني في الأوسط (6220) قال: حدَّثنا محمد بن علي الصائغ، ثنا المسيب بن واضح، ثنا مُخلد بن الحسين، عن هشام بن حسَّان، عن حُميد بن هلال، عن عبدالله بن الصامت، عن أبي ذر، فذكر مثله.","grade":"حسن","chapter_ar":"باب المسح على الخفين والعمامة والناصية والخمار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ (6261).","chapter_en":"Wiping over the Leather Socks, the Turban, the Forelock, and the Khimār","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":40,"content":{"translation":{"en":["Abū Dharr said: “I saw the Messenger of Allah ﷺ wiping over the mūqayn and the khimār.”"]},"buhuth":{"en":["The mūqayn are a type of footwear similar to leather socks, worn upon the feet."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في المعجم الأوسط (6220)."},{"num":1691,"demo":false,"sanad":"","matn":["عَنْ أَبِي أَيُّوبَ نَزَعَ خُفَّيْهِ، فَنَظَرُوا إِلَيْهِ، فَقَالَ: أَمَا إِنِّي قَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمْسَحُ عَلَيْهِمَا، وَلَكِنْ حُبب إِلَيَّ الْوُضُوءُ."],"takhrij":"صحيح: أخرجه أحمد (23574) قال: حدَّثنا محمد بن عبيد، ثنا الأعمش، عن المسيب بن رافع، عن علي بن مدرك قال: رأيت أبا أيوب نزع خفيه، فذكره.","grade":"صحيح","chapter_ar":"باب المسح على الخفين والعمامة والناصية والخمار","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (23574), al-Ṭabarānī in al-Muʿjam al-Kabīr, and Ibn Abī Shaybah.","chapter_en":"Wiping over the Leather Socks, the Turban, the Forelock, and the Khimār","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":40,"content":{"translation":{"en":["Abū Ayyūb removed his leather socks, and the people looked at him. He said: “I have indeed seen the Messenger of Allah ﷺ wipe over them, but performing a complete wuḍūʾ has become more beloved to me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (23574)، والطبراني في المعجم الكبير، وابن أبي شيبة."},{"num":1692,"demo":false,"sanad":"","matn":["عَنْ شُرَيْحِ بْنِ هَانِئٍ قَالَ: أَتَيْتُ عَائِشَةَ، أَسْأَلُهَا عَنِ الْمَسْحِ عَلَى الْخُفَّيْنِ ؟ فَقَالَتْ: عَلَيْكَ بِابْنِ أَبِي طَالِبٍ، فَسَلْهُ، فَإِنَّهُ كَانَ يُسَافِرُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَأَلْنَاهُ، فَقَالَ: جَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَلَاثَةَ أَيَّامٍ وَلَيَالِيَهُنَّ لِلْمُسَافِرِ، وَيَوْمًا وَلَيْلَةً لِلْمُقِيمِ."],"takhrij":"صحيح: رواه مسلم في الطهارة (276) عن إسحاق بن إبراهيم الحنظلي، أخبرنا عبد الرزاق، أخبرنا الثوري، عن عمرو بن قيس المُلائي، عن الحكم بن عُتَيبة، عن القاسم بن مُخيمِرة، عن شُريح بن هانئ، قال: أتيتُ عائشة، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في التوقيت في المسح على الخفين","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (276).","chapter_en":"What Has Been Reported Concerning the Time-Limit for Wiping over the Leather Socks","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":41,"content":{"translation":{"en":["Shurayḥ ibn Hāniʾ said: I went to ʿĀʾishah to ask her about wiping over the leather socks. She said: “Go to ʿAlī ibn Abī Ṭālib and ask him, for he used to travel with the Messenger of Allah ﷺ.” So we asked him, and he said: “The Messenger of Allah ﷺ fixed three days and their nights for the traveler, and one day and one night for the resident.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (276)."},{"num":1693,"demo":false,"sanad":"","matn":["عَنْ صَفْوَانَ بْنِ عَسَّالٍ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُنَا إِذَا كُنَّا سَفَرًا أَنْ لَا نَنْزِعَ خِفَافَنَا ثَلَاثَةَ أَيَّامٍ وَلَيَالِيهِنَّ إِلَّا مِنْ جَنَابَةٍ، وَلَكِنْ مِنْ غَائِطٍ وَبَوْلٍ وَنَوْمٍ."],"takhrij":"حسن: رواه الترمذي (96) والنسائي (126، 127) وابن ماجه (478) من حديث عاصم بن أبي النجود، عن زِرِّ بن حُبَيش، عن صفوان بن عسّال، فذكر مثله.","grade":"حسن","chapter_ar":"باب ما جاء في التوقيت في المسح على الخفين","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by al-Tirmidhī (96), who said: “Ḥasan ṣaḥīḥ.”","chapter_en":"What Has Been Reported Concerning the Time-Limit for Wiping over the Leather Socks","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":41,"content":{"translation":{"en":["Ṣafwān ibn ʿAssāl said: “The Messenger of Allah ﷺ used to instruct us, when we were traveling, not to remove our leather socks for three days and nights except because of janābah, but not because of defecation, urination, or sleep.”"]},"buhuth":{"en":["In Aḥmad’s wording:","“We would not remove them because of defecation, urination, or sleep; rather, we would remove them because of janābah.”","The expression “when we were traveling” means while we were travelers.","The words concerning defecation, urination, and sleep mean that the leather socks need not be removed for these forms of minor ritual impurity; rather, they may be wiped over. Janābah, however, requires their removal and the performance of ghusl."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (96)، وقال: حسن صحيح."},{"num":1694,"demo":false,"sanad":"","matn":["عَنْ خُزَيْمَةَ بْنِ ثَابِتٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْمَسْحُ عَلَى الْخُفَّيْنِ لِلْمُسَافِرِ ثَلَاثَةُ أَيَّامٍ، وَلِلْمُقِيمِ يَوْمٌ وَلَيْلَةٌ."],"takhrij":"صحيح: رواه أبو داود (157) عن حفص بن عمر، ثنا شعبة، عن الحكم وحماد، عن إبراهيم، عن أبي عبدالله الجدلي، عن خزيمة بن ثابت، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في التوقيت في المسح على الخفين","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (157) and authenticated by Ibn Ḥibbān.","chapter_en":"What Has Been Reported Concerning the Time-Limit for Wiping over the Leather Socks","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":41,"content":{"translation":{"en":["Khuzaymah ibn Thābit reported that the Prophet ﷺ said: “Wiping over the leather socks is for the traveler for three days, and for the resident for one day and one night.”"]},"buhuth":{"en":["This hadith is a foundational text establishing the time-limit for wiping: three days and nights for the traveler and one day and one night for the resident."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (157)، وصححه ابن حبان."},{"num":1695,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ رَخَّصَ لِلْمُسَافِرِ إِذَا تَوَضَّأَ وَلَبِسَ خُفَّيْهِ، ثُمَّ أَحْدَثَ وُضُوءًا أَنْ يَمْسَحَ ثَلَاثَةَ أَيَّامٍ وَلَيَالِيَهُنَّ، وَلِلْمُقِيمِ يَوْمًا وَلَيْلَةً."],"takhrij":"حسن: رواه ابن ماجه (556) قال: حدَّثنا محمد بن بشّار وبشر بن هلال الصواف، قالا: حدَّثنا عبد الوهاب بن عبد المجيد قال: حدَّثنا المهاجر أبو مخلَد، عن عبدالرحمن بن أبي بكرة، عن أبيه، فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في التوقيت في المسح على الخفين","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Ibn Mājah (556), Ibn Khuzaymah (192), and Ibn Ḥibbān (1324).","chapter_en":"What Has Been Reported Concerning the Time-Limit for Wiping over the Leather Socks","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":41,"content":{"translation":{"en":["Abū Bakrah reported that the Prophet ﷺ granted a concession to the traveler who performs wuḍūʾ, puts on his leather socks, and later breaks his wuḍūʾ, allowing him to wipe over them for three days and nights; and for the resident, one day and one night."]},"buhuth":{"en":["This indicates the condition that the leather socks are put on while in a state of purification. If wuḍūʾ is subsequently broken, wiping over them is permitted within the prescribed period."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (556)، وابن خزيمة (192)، وابن حبان (1324)."},{"num":1696,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْمَسْحِ عَلَى الْخُفَّيْنِ: لِلْمُقِيمِ يَوْمٌ وَلَيْلَةٌ، وَلِلْمُسَافِرِ ثَلَاثَةُ أَيَّامٍ وَلَيَالِيهِنَّ."],"takhrij":"حسن: رواه الطبراني في الأوسط (4530)، مجمع البحرين (469) قال: حدَّثنا عبدان بن محمد المروزي، عن قتيبة بن سعيد، عن حميد بن عبدالرحمن الرواسي، عن الحسن القصاب، عن نافع، عن ابن عمر، فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في التوقيت في المسح على الخفين","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ, as cited in Majmaʿ al-Baḥrayn (469).","chapter_en":"What Has Been Reported Concerning the Time-Limit for Wiping over the Leather Socks","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":41,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar said: “The Messenger of Allah ﷺ instructed us to wipe over the leather socks for one day and one night while resident, and for the traveler, three.”"]},"buhuth":{"en":["“While resident” means for one who is not traveling.","“Three” means three days for the traveler, as explained by the preceding hadith of Khuzaymah and other reports carrying the same meaning."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في المعجم الأوسط، كما في مجمع البحرين (469)."},{"num":1697,"demo":false,"sanad":"","matn":["عَنْ عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِالْمَسْحِ عَلَى الْخُفَّيْنِ فِي غَزْوَةِ تَبُوكَ: ثَلَاثَةُ أَيَّامٍ لِلْمُسَافِرِ وَلَيَالِيهِنَّ، وَلِلْمُقِيمِ يَوْمٌ وَلَيْلَةٌ."],"takhrij":"حسن: رواه أحمد (23995) والبزار (2757) والطبراني في الكبير (18/ح 69) وفي الأوسط (1167) والدارقطني (764) كلهم من طريق هشيم، قال: أنبأنا داود بن عمرو، عن بسر بن عبيدالله الحضرمي، عن أبي إدريس الخولاني، عن عوف بن مالك الأشجعي، فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في التوقيت في المسح على الخفين","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Aḥmad (23995), Ibn Abī Shaybah (1864), al-Bazzār (2757), and al-Ṭabarānī in al-Muʿjam al-Awsaṭ (1145).","chapter_en":"What Has Been Reported Concerning the Time-Limit for Wiping over the Leather Socks","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":41,"content":{"translation":{"en":["ʿAwf ibn Mālik al-Ashjaʿī reported that during the expedition of Tabūk, the Prophet ﷺ instructed that the traveler wipe over the leather socks for three days and nights, and the resident for one day and one night."]},"buhuth":{"en":["This provides a practical application during the expedition of Tabūk of the prescribed time-limits for both the traveler and the resident.","As for when the prescribed period for wiping begins, three opinions are mentioned:","The first is that it begins from the time one first breaks wuḍūʾ after putting on the leather socks.","Thus, if a man performs wuḍūʾ for Fajr, puts on the leather socks, and then breaks his wuḍūʾ at 10:00 a.m., the period begins from that time. He may therefore wipe and pray Ẓuhr, ʿAṣr, Maghrib, ʿIshāʾ, and the following Fajr until 10:00 a.m. the next day.","This is the position of Abū Ḥanīfah and al-Shāfiʿī, and it is the strongest narration from Aḥmad.","The second is that the period begins from the wuḍūʾ performed after breaking wuḍūʾ.","Thus, if he puts the leather socks on after his Fajr wuḍūʾ, then breaks wuḍūʾ at 10:00 a.m., the period does not begin merely with the occurrence of the nullifier. Rather, it begins when he subsequently performs wuḍūʾ and wipes over them.","This is narrated from Imām Aḥmad in one report and was also held by al-Awzāʿī, Dāwūd, Abū Thawr, and others.","The third is that the period begins from the time the leather socks are first put on.","Thus, if he performs wuḍūʾ for Fajr and then puts them on, the period is calculated from the time of wearing them: one day and one night for the resident and three days and nights for the traveler.","This view was transmitted by al-Māwardī and al-Shāshī from al-Ḥasan al-Baṣrī, as mentioned by al-Nawawī in Sharḥ al-Muhadhdhab (1/487).","Each position has its reasoning, and the issue is discussed in detail in the books of fiqh."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (23995)، وابن أبي شيبة (1864)، والبزار (2757)، والطبراني في المعجم الأوسط (1167)."},{"num":1698,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ، أَنَّهُ قَدِمَ عَلَى عُمَرَ بْنِ الْخَطَّابِ مِنْ مِصْرَ، فَقَالَ: مُنْذُ كَمْ لَمْ تَنْزِعْ خُفَّيْكَ ؟ قَالَ: مِنَ الْجُمُعَةِ إِلَى الْجُمُعَةِ، قَالَ: أَصَبْتَ السُّنَّةَ."],"takhrij":"حسن: رواه ابن ماجه (558)، والدارقطني (766) كلاهما من طريق حيوة بن شريح، عن يزيد بن أبي حبيب، عن الحكم بن عبد الله البلوي، عن علي بن رباح اللخمي، عن عقبة بن عامر قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في المسح بغير توقيت","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Ibn Mājah (558) and al-Dāraquṭnī (1/199).","chapter_en":"What Has Been Reported Concerning Wiping without a Fixed Time-Limit","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":42,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir al-Juhanī reported that he came to ʿUmar ibn al-Khaṭṭāb from Egypt. ʿUmar asked: “How long has it been since you removed your leather socks?” He replied: “From one Friday until the next Friday.” ʿUmar said: “You have followed the Sunnah.”"]},"buhuth":{"en":["It is also established from ʿUmar ibn al-Khaṭṭāb that he held the standard time-limits stated by the majority: three days for the traveler and one day and one night for the resident.","ʿAbd al-Razzāq (797) narrated through Zayd ibn Wahb al-Juhanī:","“We were in Azerbaijan, and ʿUmar ibn al-Khaṭṭāb wrote to us instructing us to wipe over the leather socks for three days when traveling and for one night when resident.”","Al-Bayhaqī said in al-Sunan al-Kubrā (1/280):","“We have narrated from ʿUmar ibn al-Khaṭṭāb the prescribed time-limit. Either he returned to that position when confirmation regarding the time-limit from the Messenger of Allah ﷺ reached him, or his statement that agrees with the well-known Sunnah is more deserving of being followed.”","Some scholars interpreted ʿUmar’s words, “You have followed the Sunnah,” as referring to a case of necessity, such as a traveler for whom repeatedly removing and replacing the leather socks would cause hardship, like an official courier dispatched for the public interests of the Muslims. This is mentioned in Ikhtiyārāt Shaykh al-Islām Ibn Taymiyyah (p. 65)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (558)، والدارقطني (766)."},{"num":1699,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ وَمَسَحَ عَلَى الْجَوْرَبَيْنِ وَالنَّعْلَيْنِ."],"takhrij":"حسن: رواه أبو داود (159) والترمذي (99) وابن ماجه (559) كلهم من حديث سفيان، عن أبي قيس الأودي، عن الهزيل بن شرحبيل، عن المغيرة بن شعبة، فذكر الحديث. ورواه الإمام أحمد (18206) من هذا الوجه.","grade":"حسن","chapter_ar":"باب ما جاء في المسح على الجوربين والنعلين","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (159), al-Tirmidhī (99), Ibn Mājah (559), and Aḥmad (18206).","chapter_en":"What Has Been Reported Concerning Wiping over Socks and Sandals","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":43,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah said: “The Prophet ﷺ performed wuḍūʾ and wiped over his socks and sandals.”"]},"buhuth":{"en":["Those who permit wiping over socks use this hadith as evidence, particularly when the socks cover the required area and are suitable for continued walking."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (159)، والترمذي (99)، وابن ماجه (559)، وأحمد (18206)."},{"num":1700,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ قَالَ: بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَرِيَّةً فَأَصَابَهُمُ الْبَرْدُ، فَلَمَّا قَدِمُوا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَهُمْ أَنْ يَمْسَحُوا عَلَى الْعَصَائِبِ وَالتَّسَاخِينِ."],"takhrij":"حسن: رواه أبو داود (146) عن أحمد بن محمد بن حنبل، ثنا يحيى بن سعيد، عن ثور، عن راشد بن سعد، عن ثوبان، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في المسح على الجوربين والنعلين","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (146) and Aḥmad (22383).","chapter_en":"What Has Been Reported Concerning Wiping over Socks and Sandals","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":43,"content":{"translation":{"en":["Thawbān said: “The Messenger of Allah ﷺ sent out a detachment, and they were afflicted by cold. When they returned to the Messenger of Allah ﷺ, he instructed them to wipe over the head-wraps and the tasākhīn.”"]},"buhuth":{"en":["Tasākhīn means anything worn upon the feet for warmth, including leather socks, ordinary socks, and similar footwear."]}},"tuhfa":{},"full":1,"dr":1,"rep":[1688],"tks":"حسن: رواه أبو داود (146)، وأحمد (22383)."},{"num":1701,"demo":false,"sanad":"","matn":["عَنْ عُبَيْدِ بْنِ جُرَيْجٍ، أَنَّهُ قَالَ لِعَبْدِ اللَّهِ بْنِ عُمَرَ: يَا أَبَا عَبْدِ الرَّحْمَنِ رَأَيْتُكَ تَصْنَعُ أَرْبَعًا لَمْ أَرَ أَحَدًا مِنْ أَصْحَابِكَ يَصْنَعُهَا، قَالَ: وَمَا هُنَّ يَا ابْنَ جُرَيْجٍ ؟... رَأَيْتُكَ تَلْبَسُ النِّعَالَ السِّبْتِيَّةَ، فَذَكَرَ مِنْ الْأَرْبَعِ: فَقَالَ: وَأَمَّا النِّعَالُ السِّبْتِيَّةُ فَإِنِّي رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَلْبَسُ النِّعَالَ الَّتِي لَيْسَ فِيهَا شَعَرٌ، وَيَتَوَضَّأُ فِيهَا فَأَنَا أُحِبُّ أَنْ أَلْبَسَهَا...(فَذَكَرَ الْحَدِيثَ)."],"takhrij":"متّفق عليه: رواه مالك في الحجِّ (31) عن سعيد بن أبي سعيد المقبري، عن عبيد بن جريج.. فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب غسل الرجلين في النعلين وأنه لا يُمسح عليهما","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (31), al-Bukhārī (166, 5850), and Muslim (1187).","chapter_en":"Washing the Feet While Wearing Sandals, and That the Sandals Themselves Are Not Wiped Over","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":44,"content":{"translation":{"en":["ʿUbayd ibn Jurayj said to ʿAbdullāh ibn ʿUmar: “O Abū ʿAbd al-Raḥmān, I have seen you do four things that I have not seen any of your companions do.” He asked: “What are they, O Ibn Jurayj?” Among the four things he mentioned: “I have seen you wear sabtī sandals.” Ibn ʿUmar replied: “As for the sabtī sandals, I saw the Messenger of Allah ﷺ wearing sandals from which the hair had been removed, and he would perform wuḍūʾ while wearing them. Therefore, I like to wear them.”"]},"buhuth":{"en":["The term “sabtī,” with a kasrah on the letter sīn, refers to sandals from which the hair has been removed. The term is derived either from sabt, meaning shaving or removing hair, or from the leather having been tanned until it became soft and smooth."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (31)، والبخاري (166، 5850)، ومسلم (1187)."},{"num":1702,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ قَالَ: لَوْ كَانَ الدِّينُ بِالرَّأْيِ لَكَانَ أَسْفَلُ الْخُفِّ أَوْلَى بِالْمَسْحِ مِنْ أَعْلَاهُ، وَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمْسَحُ عَلَى ظَاهِرِ خُفَّيْهِ."],"takhrij":"صحيح: رواه أبو داود (162) قال: حدَّثنا محمد بن العلاء، ثنا حفص، يعني ابن غياث، عن الأعمش، عن أبي إسحاق، عن عبد خير، عن عليّ، فذكره.","grade":"صحيح","chapter_ar":"باب المسح على ظاهر الخفين","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (162).","chapter_en":"Wiping over the Upper Surface of the Leather Socks","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":45,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib said: “If the religion were based merely upon personal reasoning, then the underside of the leather sock would be more deserving of being wiped than its upper surface. But I saw the Messenger of Allah ﷺ wiping over the upper surface of his leather socks.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (162)."},{"num":1703,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمْسَحُ عَلَى الْخُفَّيْنِ عَلَى ظَاهِرِهِمَا."],"takhrij":"حسن: رواه أبو داود (161) عن محمد بن الصباح البزار، كما رواه أيضاً الترمذي (98) عن علي بن حُجْر، كلاهما عن عبدالرحمن بن أبي الزِناد، عن أبيه، عن عروة بن الزبير، عن المغيرة بن شعبة، فذكر الحديث. واللفظ للترمذي، ولفظ أبي داود:كان يمسح على الخفين.","grade":"حسن","chapter_ar":"باب المسح على ظاهر الخفين","chapter_ur":"","part_ar":"كتاب الوضوء","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (161) and al-Tirmidhī (98). This wording is that of al-Tirmidhī.","chapter_en":"Wiping over the Upper Surface of the Leather Socks","part_en":"The Book of Wuḍūʾ","group_ar":"","group_en":"","part_no":7,"group_no":0,"chapter_no":45,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah said: “I saw the Prophet ﷺ wiping over the leather socks, over their upper surfaces.”"]},"buhuth":{"en":["Abū Dāwūd’s wording is:","“He used to wipe over the leather socks.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (161)، والترمذي (98)، واللفظ للترمذي."},{"num":1704,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّهَا قَالَتْ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَعْضِ أَسْفَارِهِ، حَتَّى إِذَا كُنَّا بِالْبَيْدَاءِ أَوْ بِذَاتِ الْجَيْشِ انْقَطَعَ عِقْدٌ لِي، فَأَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْتِمَاسِهِ وَأَقَامَ النَّاسُ مَعَهُ، وَلَيْسُوا عَلَى مَاءٍ وَلَيْسَ مَعَهُمْ مَاءٌ، فَأَتَى النَّاسُ إِلَى أَبِي بَكْرٍ الصِّدِّيقِ، فَقَالُوا: أَلَا تَرَى مَا صَنَعَتْ عَائِشَةُ ؟ أَقَامَتْ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَبِالنَّاسِ، وَلَيْسُوا عَلَى مَاءٍ وَلَيْسَ مَعَهُمْ مَاءٌ، فَجَاءَ أَبُو بَكْرٍ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَاضِعٌ رَأْسَهُ عَلَى فَخِذِي قَدْ نَامَ، فَقَالَ: حَبَسْتِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالنَّاسَ وَلَيْسُوا عَلَى مَاءٍ وَلَيْسَ مَعَهُمْ مَاءٌ، قَالَتْ عَائِشَةُ: فَعَاتَبَنِي أَبُو بَكْرٍ، وَقَالَ: مَا شَاءَ اللَّهُ أَنْ يَقُولَ، وَجَعَلَ يَطْعُنُنِي بِيَدِهِ فِي خَاصِرَتِي، وَلَا يَمْنَعُنِي مِنَ التَّحَرُّكِ إِلَّا مَكَانُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى فَخِذِي، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى أَصْبَحَ عَلَى غَيْرِ مَاءٍ، فَأَنْزَلَ اللَّهُ آيَةَ ﴿التَّيَمُّمِ فَتَيَمَّمُوا﴾ [ النساء: 43].","فَقَالَ أُسَيْدُ بْنُ الْحُضَيْرِ: مَا هِيَ بِأَوَّلِ بَرَكَتِكُمْ يَا آلَ أَبِي بَكْرٍ ؟.","قَالَتْ: فَبَعَثْنَا الْبَعِيرَ الَّذِي كُنْتُ عَلَيْهِ فَأَصَبْنَا الْعِقْدَ تَحْتَهُ."],"takhrij":"متَّفقٌ عليه: رواه مالك في الطهارة (89) عن عبدالرحمن بن القاسم، عن أبيه، عن عائشة، واللفظ له، ومن طريقه البخاري في التيمم (334) ومسلم في الحيض (367).","grade":"متفق عليه","chapter_ar":"باب ما جاء في التيمم","chapter_ur":"","part_ar":"كتاب التيمم","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (89), al-Bukhārī (334), and Muslim (367).","chapter_en":"What Has Been Reported Concerning Tayammum","part_en":"The Book of Tayammum","group_ar":"","group_en":"","part_no":8,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿĀʾishah, the Mother of the Believers, may Allah be pleased with her, said: We went out with the Messenger of Allah ﷺ on one of his journeys. When we reached al-Baydāʾ—or Dhāt al-Jaysh—a necklace of mine broke and was lost. The Messenger of Allah ﷺ remained there searching for it, and the people remained with him. They were not near water and had no water with them. The people went to Abū Bakr al-Ṣiddīq and said: “Do you not see what ʿĀʾishah has done? She has detained the Messenger of Allah ﷺ and the people at a place where there is no water, and they have no water with them.” ʿĀʾishah said: Abū Bakr came while the Messenger of Allah ﷺ was sleeping with his head upon my thigh. He said: “You have detained the Messenger of Allah ﷺ and the people when they are not near water and have no water with them!” She said: Abū Bakr reproached me and said whatever Allah willed that he should say, and he began poking me in my side with his hand. Nothing prevented me from moving except that the head of the Messenger of Allah ﷺ was resting upon my thigh. The Messenger of Allah ﷺ slept until morning while there was still no water. Then Allah, Blessed and Exalted, revealed the verse of tayammum, so they performed tayammum. Usayd ibn Ḥuḍayr said: “This is not the first of your blessings, O family of Abū Bakr.”","ʿĀʾishah said: We then made the camel upon which I had been riding stand up and found the necklace underneath it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (89)، والبخاري (334)، ومسلم (367)."},{"num":1705,"demo":false,"sanad":"","matn":["عَنْ عَمَّارِ بْنِ يَاسِرٍ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَرَّسَ بِأَوَّلَاتِ الْجَيْشِ وَمَعَهُ عَائِشَةُ، فَانْقَطَعَ عِقْدٌ لَهَا مِنْ جَزْعِ ظَفَارِ، فَحُبِسَ النَّاسُ ابْتِغَاءَ عِقْدِهَا ذَلِكَ حَتَّى أَضَاءَ الْفَجْرُ وَلَيْسَ مَعَ النَّاسِ مَاءٌ، فَتَغَيَّظَ عَلَيْهَا أَبُو بَكْرٍ، وَقَالَ: حَبَسْتِ النَّاسَ وَلَيْسَ مَعَهُمْ مَاءٌ، فَأَنْزَلَ اللَّهُ تَعَالَى عَلَى رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رُخْصَةَ التَّطَهُّرِ بِالصَّعِيدِ الطَّيِّبِ، فَقَامَ الْمُسْلِمُونَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَضَرَبُوا بِأَيْدِيهِمْ إِلَى الْأَرْضِ ثُمَّ رَفَعُوا أَيْدِيَهُمْ وَلَمْ يَقْبِضُوا مِنَ التُّرَابِ شَيْئًا فَمَسَحُوا بِهَا وُجُوهَهُمْ وَأَيْدِيَهُمْ إِلَى الْمَنَاكِبِ، وَمِنْ بِطُونِ أَيْدِيهِمْ إِلَى الْآبَاطِ."],"takhrij":"صحيح: رواه أبو داود (320)، والنسائي (314)، وأحمد (18322) كلهم من حديث يعقوب بن إبراهيم، قال: حدثنا أبي، عن صالح، عن ابن شهاب، قال: حدثني عبيدالله بن عبد الله بن عتبة، عن ابن عباس، عن عمار بن ياسر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في التيمم","chapter_ur":"","part_ar":"كتاب التيمم","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (320), al-Nasāʾī (314), and Aḥmad (18322).","chapter_en":"What Has Been Reported Concerning Tayammum","part_en":"The Book of Tayammum","group_ar":"","group_en":"","part_no":8,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿAmmār ibn Yāsir, may Allah be pleased with him, reported that the Messenger of Allah ﷺ stopped for rest at Dhāt al-Jaysh while ʿĀʾishah was with him. A necklace of hers made from ẓafārī agate broke, so the people were detained searching for it until dawn appeared, and the people had no water. Abū Bakr became upset with her and said: “You have detained the people while they have no water!” Then Allah Most High revealed to the Messenger of Allah ﷺ the concession of purification with clean earth. The Muslims stood with the Messenger of Allah ﷺ and struck the ground with their hands. They then raised their hands without taking any soil into them and wiped their faces and arms up to the shoulders, and from the palms of their hands up to the armpits."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (320)، والنسائي (314)، وأحمد (18322)."},{"num":1706,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ ( فَذَكَرَ الْحَدِيثَ): قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَجُعِلَتْ لِي الْأَرْضُ مَسْجِدًا وَطَهُورًا، فَأَيُّمَا رَجُلٍ مِنْ أُمَّتِي أَدْرَكَتْهُ الصَّلَاةُ فَلْيُصَلِّ...الْحَدِيث."],"takhrij":"متَّفقٌ عليه: أخرجه البخاري في التيمم (335) ومسلم في المساجد (521) كلاهما من طريق هشيم، عن سيار، عن يزيد الفقير، عن جابر بن عبدالله.. فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب في التيمم وأن الصعيد الطيب هو التراب","chapter_ur":"","part_ar":"كتاب التيمم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (335) and Muslim (521).","chapter_en":"Tayammum, and That Clean Ṣaʿīd Is Soil","part_en":"The Book of Tayammum","group_ar":"","group_en":"","part_no":8,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “The earth has been made for me a place of prayer and a means of purification. Therefore, wherever any man from my Ummah is overtaken by the time of prayer, let him pray.”"]},"intro":{"ar":["قال الله تعالى:","﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ وَامْسَحُوا بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى الْكَعْبَيْنِ ۚ وَإِنْ كُنْتُمْ جُنُبًا فَاطَّهَّرُوا ۚ وَإِنْ كُنْتُمْ مَرْضَىٰ أَوْ عَلَىٰ سَفَرٍ أَوْ جَاءَ أَحَدٌ مِنْكُمْ مِنَ الْغَائِطِ أَوْ لَامَسْتُمُ النِّسَاءَ فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ مِنْهُ ۚ مَا يُرِيدُ اللَّهُ لِيَجْعَلَ عَلَيْكُمْ مِنْ حَرَجٍ وَلَٰكِنْ يُرِيدُ لِيُطَهِّرَكُمْ وَلِيُتِمَّ نِعْمَتَهُ عَلَيْكُمْ لَعَلَّكُمْ تَشْكُرُونَ﴾ [المائدة: ٦]."],"en":["“O you who believe, when you rise for prayer, wash your faces and your hands up to the elbows, wipe your heads, and wash your feet up to the ankles. If you are in a state of major ritual impurity, then purify yourselves. But if you are ill, on a journey, one of you comes from relieving himself, or you have had intimate contact with women and you do not find water, then perform tayammum with clean earth and wipe your faces and hands with it. Allah does not intend to place hardship upon you, but He intends to purify you and complete His favor upon you so that you may be grateful.” [Sūrat al-Māʾidah 5:6]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (335)، ومسلم (521)."},{"num":1707,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَجُعِلَتْ لِيَ الأَرْضُ طَهُورًا وَمَسْجِدًا. مُخْتَصَراً."],"takhrij":"صحيح: رواه مسلم في المساجد (523) من طريق إسماعيل بن جعفر، عن العلاء، عن أبيه، عن أبي هريرة في حديث طويل.","grade":"صحيح","chapter_ar":"باب في التيمم وأن الصعيد الطيب هو التراب","chapter_ur":"","part_ar":"كتاب التيمم","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (523).","chapter_en":"Tayammum, and That Clean Ṣaʿīd Is Soil","part_en":"The Book of Tayammum","group_ar":"","group_en":"","part_no":8,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “The earth has been made for me a place of prayer and a means of purification.” Abridged."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (523)."},{"num":1708,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: جُعِلَتْ لَنَا الأَرْضُ كُلُّهَا مَسْجِدًا، وَجُعِلَتْ تُرْبَتُهَا لَنَا طَهُورًا، إِذَا لَمْ نَجِدِ الْمَاءَ. مُخْتَصَراً."],"takhrij":"صحيح: رواه مسلم في المساجد (522) من حديث أبي مالك الأشجعي، عن ربعي، عن حذيفة.. فذكر الحديث.","grade":"صحيح","chapter_ar":"باب في التيمم وأن الصعيد الطيب هو التراب","chapter_ur":"","part_ar":"كتاب التيمم","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (522).","chapter_en":"Tayammum, and That Clean Ṣaʿīd Is Soil","part_en":"The Book of Tayammum","group_ar":"","group_en":"","part_no":8,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Ḥudhayfah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “The whole earth has been made for us a place of prayer, and its soil has been made for us a means of purification when we do not find water.” Abridged."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (522)."},{"num":1709,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: جُعِلَتْ لِي الْأَرْضُ طَهُورًا وَمَسْجِدًا."],"takhrij":"صحيح: رواه أبـو داود (498) عن عثمان بن أبي شيبة، حدَّثنا جرير، عن الأعمش، عن مجاهد بن جَبْر، عن عبيدالله بن عمر الليثي، عن أبي ذر، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب في التيمم وأن الصعيد الطيب هو التراب","chapter_ur":"","part_ar":"كتاب التيمم","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (498).","chapter_en":"Tayammum, and That Clean Ṣaʿīd Is Soil","part_en":"The Book of Tayammum","group_ar":"","group_en":"","part_no":8,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Abū Dharr, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “The earth has been made for me a means of purification and a place of prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (498)."},{"num":1710,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ: أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: جُعِلَتْ لِي الْأَرْضُ مَسَاجِدَ وَطَهُورًا أَيْنَمَا أَدْرَكَتْنِي الصَّلَاةُ تَمَسَّحْتُ وَصَلَّيْتُ، وَكَانَ مَنْ قَبْلِي يُعَظِّمُونَ ذَلِكَ، إِنَّمَا كَانُوا يُصَلُّونَ فِي كَنَائِسِهِمْ وَبِيَعِهِمْ .... مُخْتَصَراً."],"takhrij":"حسن: رواه أحمد (7068) قال: حدَّثنا قتيبة بن سعيد، حدَّثنا بكر بن مُضَر، عن ابن الهاد، عن عمرو بن شعيب، عن أبيه، عن جده، فذكر الحديث بطوله.","grade":"حسن","chapter_ar":"باب في التيمم وأن الصعيد الطيب هو التراب","chapter_ur":"","part_ar":"كتاب التيمم","part_ur":"","takhrij_en":"Good: Narrated by Aḥmad (7068).","chapter_en":"Tayammum, and That Clean Ṣaʿīd Is Soil","part_en":"The Book of Tayammum","group_ar":"","group_en":"","part_no":8,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb narrated from his father, from his grandfather, that the Messenger of Allah ﷺ said: “The earth has been made for me a place of prayer and a means of purification. Wherever the time of prayer reaches me, I perform tayammum and pray. Those who came before me regarded this matter differently; they would only pray in their churches and synagogues…” Abridged."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (7068)."},{"num":1711,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَخْرُجُ، فَيُهَرِيقُ الْمَاءَ، فَيَتَمَسَّحُ بِالتُّرَابِ، فَأَقُولُ: يَا رَسُولَ اللَّهِ، إِنَّ الْمَاءَ مِنْكَ قَرِيبٌ، فَيَقُولُ: وَمَا يُدْرِينِي لَعَلِّي لَا أَبْلُغُهُ."],"takhrij":"حسن: رواه الإمام أحمد (2614) من طريق عبد الله بن المبارك –وهو في الزهد له (292): أخبرنا ابنُ لهيعة، عن عبد الله بن هبيرة، عن حنش، عن ابن عباس قال: فذكره.","grade":"حسن","chapter_ar":"باب في التيمم وأن الصعيد الطيب هو التراب","chapter_ur":"","part_ar":"كتاب التيمم","part_ur":"","takhrij_en":"Good: Narrated by Imām Aḥmad (2614).","chapter_en":"Tayammum, and That Clean Ṣaʿīd Is Soil","part_en":"The Book of Tayammum","group_ar":"","group_en":"","part_no":8,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them both, reported that the Messenger of Allah ﷺ would go out after passing water and then perform tayammum with soil. I would say: “O Messenger of Allah, water is close to you.” He would reply: “How do I know? Perhaps I may not reach it.”"]},"buhuth":{"en":["This contains encouragement to perform the prayer with tayammum when water is unavailable. The prayer is not to be delayed merely in order to obtain water when there is fear that its prescribed time will end."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (2614)."},{"num":1712,"demo":false,"sanad":"","matn":["عَنْ شَقِيقِ بْنِ سَلَمَةَ قَالَ: كُنْتُ جَالِسًا مَعَ عَبْدِ اللَّهِ، وَأَبِي مُوسَى، فَقَالَ أَبُو مُوسَى: يَا أَبَا عَبْدِ الرَّحْمَنِ، أَرَأَيْتَ لَوْ أَنَّ رَجُلًا أَجْنَبَ فَلَمْ يَجِدِ الْمَاءَ شَهْرًا، كَيْفَ يَصْنَعُ بِالصَّلَاةِ؟ فَقَالَ عَبْدُ اللَّهِ: لَا يَتَيَمَّمُ وَإِنْ لَمْ يَجِدِ الْمَاءَ شَهْرًا، فَقَالَ أَبُو مُوسَى: فَكَيْفَ بِهَذِهِ الآيَةِ فِي سُورَةِ الْمَائِدَةِ: ﴿فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا﴾ [المائدة 6] فَقَالَ عَبْدُ اللَّهِ: لَوْ رُخِّصَ لَهُمْ فِي هَذِهِ الآيَةِ، لَأَوْشَكَ إِذَا بَرَدَ عَلَيْهِمُ الْمَاءُ، أَنْ يَتَيَمَّمُوا بِالصَّعِيدِ، فَقَالَ أَبُو مُوسَى لِعَبْدِ اللَّهِ: أَلَمْ تَسْمَعْ قَوْلَ عَمَّارٍ، بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَاجَةٍ، فَأَجْنَبْتُ، فَلَمْ أَجِدِ الْمَاءَ، فَتَمَرَّغْتُ فِي الصَّعِيدِ كَمَا تَمَرَّغُ الدَّابَّةُ، ثُمَّ أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرْتُ ذَلِكَ لَهُ، فَقَالَ: إِنَّمَا كَانَ يَكْفِيكَ أَنْ تَقُولَ بِيَدَيْكَ هَكَذَا، ثُمَّ ضَرَبَ بِيَدَيْهِ الأَرْضَ ضَرْبَةً وَاحِدَةً، ثُمَّ مَسَحَ الشِّمَالَ عَلَى الْيَمِينِ وَظَاهِرَ كَفَّيْهِ وَوَجْهَهُ، فَقَالَ عَبْدُ اللَّهِ: أَوَلَمْ تَرَ عُمَرَ لَمْ يَقْنَعْ بِقَوْلِ عَمَّارٍ؟."],"takhrij":"متَّفقٌ عليه: رواه البخاري في التيمم (347) ومسلم في الحيض (368) كلاهما من طريق أبي معاوية، عن الأعمش، عن شقيق فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في صفة التيمم","chapter_ur":"","part_ar":"كتاب التيمم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (347) and Muslim (368).","chapter_en":"What Has Been Reported Concerning the Manner of Performing Tayammum","part_en":"The Book of Tayammum","group_ar":"","group_en":"","part_no":8,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Shaqīq ibn Salamah said: I was sitting with ʿAbdullāh and Abū Mūsā. Abū Mūsā said: “O Abū ʿAbd al-Raḥmān, what do you say about a man who becomes junub and cannot find water for an entire month? What should he do concerning prayer?” ʿAbdullāh replied: “He should not perform tayammum, even if he does not find water for a month.” Abū Mūsā said: “Then what about this verse in Sūrat al-Māʾidah: ‘And if you do not find water, then perform tayammum with clean earth.’ [Sūrat al-Māʾidah 5:6]” ʿAbdullāh replied: “If they were given this concession whenever they wished, then when water became cold for them they would soon resort to tayammum with earth.” Abū Mūsā said to ʿAbdullāh: “Have you not heard what ʿAmmār said? The Messenger of Allah ﷺ sent me on an errand and I became junub. I could not find water, so I rolled in the earth as an animal rolls. Then I came to the Prophet ﷺ and mentioned that to him. He said: ‘It would have been sufficient for you to do this with your hands.’ He then struck the ground once with his hands, wiped the left hand over the right, and wiped the backs of his hands and his face.” ʿAbdullāh said: “Did you not see that ʿUmar was not satisfied with ʿAmmār’s statement?”"]},"buhuth":{"en":["In al-Bukhārī’s wording, he struck the ground with his palms, blew upon them, and then wiped his face and hands."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (347)، ومسلم (368)."},{"num":1713,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى: أَنَّ رَجُلًا أَتَى عُمَرَ بْنِ الْخَطَّابِ فَقَالَ: إِنِّي أَجْنَبْتُ فَلَمْ أَجِدْ مَاءً ؟ فَقَالَ: لَا تُصَلِّ، فَقَالَ عَمَّارٌ: أَمَا تَذْكُرُ يَا أَمِيرَ الْمُؤْمِنِينَ! إِذْ أَنَا وَأَنْتَ فِي سَرِيَّةٍ، فَأَجْنَبْنَا فَلَمْ نَجِدْ مَاءً، فَأَمَّا أَنْتَ فَلَمْ تُصَلِّ، وَأَمَّا أَنَا، فَتَمَعَّكْتُ فِي التُّرَابِ وَصَلَّيْتُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّمَا كَانَ يَكْفِيكَ أَنْ تَضْرِبَ بِيَدَيْكَ الأَرْضَ، ثُمَّ تَنْفُخَ، ثُمَّ تَمْسَحَ بِهِمَا وَجْهَكَ وَكَفَّيْكَ.","فَقَالَ عُمَرُ: اتَّقِ اللَّهَ يَا عَمَّارُ! قَالَ: إِنْ شِئْتَ لَمْ أُحَدِّثْ بِهِ. فَقَالَ عُمَرُ: نُوَلِّيكَ مَا تَوَلَّيْتَ."],"takhrij":"متَّفقٌ عليه: أخرجه البخاري في الوضوء (338) ومسلم في الحيض (368) كلاهما من طريق شعبة، قال: حدثني الحكم، عن ذَرّ، عن سعيد بن عبدالرحمن بن أبْزَى، عن أبيه فذكر الحديث. واللفظ لمسلمٍ.","grade":"متفق عليه","chapter_ar":"باب ما جاء في صفة التيمم","chapter_ur":"","part_ar":"كتاب التيمم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (338) and Muslim (368). This wording is that of Muslim.","chapter_en":"What Has Been Reported Concerning the Manner of Performing Tayammum","part_en":"The Book of Tayammum","group_ar":"","group_en":"","part_no":8,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Abzā reported that a man came to ʿUmar ibn al-Khaṭṭāb and said: “I have become junub and cannot find water.” ʿUmar said: “Do not pray.” ʿAmmār said: “Do you not remember, O Commander of the Believers, when you and I were in a military detachment and we both became junub but could not find water? You did not pray, while I rolled in the soil and prayed. The Prophet ﷺ said: ‘It would have been sufficient for you to strike the earth with your hands, then blow upon them, then wipe your face and your palms with them.’” ʿUmar said: “Fear Allah, O ʿAmmār!”","He replied: “If you wish, I will not narrate it.” ʿUmar said: “We leave you responsible for what you have undertaken.”"]},"buhuth":{"en":["In one narration of al-Bukhārī:","“He blew upon them.”","In another:","“He lightly spat upon them.”","In Muslim:","“He shook the dust from his hands and wiped his face and palms.”","This indicates the recommendation of reducing excess dust before wiping."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: أخرجه البخاري (338)، ومسلم (368)، واللفظ لمسلم."},{"num":1714,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانُ بْنُ حُصَيْنٍ الْخُزَاعِيُّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى رَجُلًا مُعْتَزِلًا لَمْ يُصَلِّ فِي الْقَوْمِ، فَقَالَ: يَا فُلَانُ، مَا مَنَعَكَ أَنْ تُصَلِّيَ فِي الْقَوْمِ ؟ فَقَالَ: يَا رَسُولَ اللَّهِ أَصَابَتْنِي جَنَابَةٌ وَلَا مَاءَ، قَالَ: عَلَيْكَ بِالصَّعِيدِ فَإِنَّهُ يَكْفِيكَ."],"takhrij":"متَّفقٌ عليه: رواه البخاري في التيمم (344، 347) ومسلم في المساجد (682) كلاهما من طريق أبي رجاء العُطارديّ، عن عمران بن حصين فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب ما جاء في صفة التيمم","chapter_ur":"","part_ar":"كتاب التيمم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (344) and Muslim (682).","chapter_en":"What Has Been Reported Concerning the Manner of Performing Tayammum","part_en":"The Book of Tayammum","group_ar":"","group_en":"","part_no":8,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn reported that the Messenger of Allah ﷺ saw a man standing apart who had not prayed with the people. He asked: “O so-and-so, what prevented you from praying with the people?” He replied: “O Messenger of Allah, I am in a state of janābah and there is no water.” He said: “Use clean earth, for it is sufficient for you.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12163],"tks":"متفق عليه: رواه البخاري (344)، ومسلم (682)."},{"num":1715,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)، عَنْ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الصَّعِيدُ الطَّيِّبُ وَضُوءُ الْمُسْلِمِ وَلَوْ إِلَى عَشْرِ سِنِينَ، فَإِذَا وَجَدْتَ الْمَاءَ فَأَمِسَّهُ جِلْدَكَ فَإِنَّ ذَلِكَ خَيْرٌ."],"takhrij":"حسن: رواه أبو داود (332) والترمذي (124) كلاهما من حديث خالد الحذاء، والنسائي (322) من حديث أيوب، كلاهما، أعني خالد وأيوب، عن أبي قِلابة، عن عمرو بن بُجدان، عن أبي ذر، فذكره مختصراً هكذا. وتفصيله ما ذكره أبو داود: قال أبو ذرٍّ: اجتمعت غُنيمةٌ عند رسول الله صلى الله عليه وسلم فقال: يا أبا ذرٍّ! أبدُ فيها، فبدوتُ إلى الربذة، فكانت تصيبني الجنابةُ، فأمكث الخميس والسبت، فأتيت النبي صلى الله عليه وسلم فقال: أبو ذرٍّ، فسكتُّ، فقال: ثكلتك أمك أبا ذرٍّ!، لأمك الويل!، فدعا لي بجارية سوداء، فجاءت بعسٍ فيه ماء فَسَتَرتْني بثوب، واستترتُ بالراحلــــــة واغتسلتُ، فكأنِّي أَلْقَيتُ عني جبلاً، فقـــــــال رسول الله صلى الله عليه وسلم: الصعيد الطيب...الخ فذكر الحديث.","grade":"حسن","chapter_ar":"باب الصعيد الطيب طهور المسلم إذا لم يجد الماء","chapter_ur":"","part_ar":"كتاب التيمم","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (332), al-Tirmidhī (124), and al-Nasāʾī (322).","chapter_en":"Clean Earth Is the Muslim’s Means of Purification When Water Cannot Be Found","part_en":"The Book of Tayammum","group_ar":"","group_en":"","part_no":8,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abū Dharr, may Allah be pleased with him, reported that the Prophet ﷺ said: “Clean earth is the purification of the Muslim even if he does not find water for ten years. When you find water, then let it touch your skin, for that is better.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (332)، والترمذي (124)، والنسائي (322)."},{"num":1716,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الصَّعِيدُ وَضُوءُ الْمُسْلِمِ، وَإِنْ لَمْ يَجِدِ الْمَاءَ عَشْرَ سِنِينَ، فَإِذَا وَجَدَ الْمَاءَ فَلْيَتَّقِ اللَّهَ وَلْيَمَسَّهُ بَشَرُهُ، فَإِنَّ ذَلِكَ خَيْرٌ."],"takhrij":"صحيح: رواه البزار - كشف الأستار (310) قال: حدَّثنا مُقدَّم بن محمد بن علي بن مُقدَّم المقدمي، حدثني عمي القاسم بن يحيى بن عطاء بن مُقدَّم، ثنا هشام بن حسَّان، عن محمد بن سيرين، عن أبي هريرة، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الصعيد الطيب طهور المسلم إذا لم يجد الماء","chapter_ur":"","part_ar":"كتاب التيمم","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzār in Kashf al-Astār (310).","chapter_en":"Clean Earth Is the Muslim’s Means of Purification When Water Cannot Be Found","part_en":"The Book of Tayammum","group_ar":"","group_en":"","part_no":8,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “Clean earth is the Muslim’s purification even if he does not find water for ten years. When he finds water, let him fear Allah and let the water touch his skin, for that is better.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البزار في كشف الأستار (310)."},{"num":1717,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ الْعَاص قَالَ: احْتَلَمْتُ فِي لَيْلَةٍ بَارِدَةٍ فِي غَزْوَةِ ذَاتِ السُّلَاسِلِ فَأَشْفَقْتُ إِنِ اغْتَسَلْتُ أَنْ أَهْلِكَ، فَتَيَمَّمْتُ ثُمَّ صَلَّيْتُ بِأَصْحَابِي الصُّبْحَ، فَذَكَرُوا ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا عَمْرُو! صَلَّيْتَ بِأَصْحَابِكَ وَأَنْتَ جُنُبٌ ؟ فَأَخْبَرْتُهُ بِالَّذِي مَنَعَنِي مِنَ الِاغْتِسَالِ، وَقُلْتُ: إِنِّي سَمِعْتُ اللَّهَ يَقُولُ: ﴿وَلا تَقْتُلُوا أَنْفُسَكُمْ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا﴾ [سورة النساء: 29] فَضَحِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَمْ يَقُلْ شَيْئًا."],"takhrij":"حسن: أخرجه أبو داود (334)، وأحمد (17812)، والحاكم (629) كلهم من طريق عمران بن أبي أنس، عن عبدالرحمن بن جبير، عن عمرو بن العاص، فذكره.","grade":"حسن","chapter_ar":"باب إذا خاف الجنب البرد أيتيمم؟","chapter_ur":"","part_ar":"كتاب التيمم","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (334, 335); authenticated by al-Ḥākim (629).","chapter_en":"If a Person in Janābah Fears Harm from the Cold, May He Perform Tayammum?","part_en":"The Book of Tayammum","group_ar":"","group_en":"","part_no":8,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿAmr ibn al-ʿĀṣ said: I had a wet dream on an extremely cold night during the expedition of Dhāt al-Salāsil. I feared that if I performed ghusl I might die, so I performed tayammum and then led my companions in the Fajr prayer. They mentioned this to the Prophet ﷺ, who said: “O ʿAmr, did you lead your companions in prayer while you were junub?” I informed him of what had prevented me from bathing and said: “I heard Allah say: ‘And do not kill yourselves. Indeed, Allah is ever Merciful to you.’ [Sūrat al-Nisāʾ 4:29]” The Messenger of Allah ﷺ laughed and said nothing."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: أخرجه أبو داود (334، 335)، وصححه الحاكم (629)."},{"num":1718,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ رَجُلا أَجْنَبَ فِي شِتَاءٍ فَسَأَلَ، فَأُمِرَ بِالْغُسْلِ، فَاغْتَسَلَ فَمَاتَ، فَذُكِرَ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: مَا لَهُمْ ؟ قَتَلُوهُ قَتَلَهُمُ اللَّهُ ثَلاثًا، قَدْ جَعَلَ اللَّهُ الصَّعِيدَ أَوِ التَّيَمُّمَ طَهُورًا."],"takhrij":"حسن: رواه ابن خزيمة (273)، وابن حبان (1314)، وابن الجارود (128)، والحاكم (165) كلهم من طريق عمر بن حفص بن غياث، حدثنا أبي، قال: أخبرني إياه الوليد بن عبيد الله بن أبي رباح، أن عطاء حدّثه عن ابن عباس قال: فذكره.","grade":"حسن","chapter_ar":"باب الجريح يتيمم","chapter_ur":"","part_ar":"كتاب التيمم","part_ur":"","takhrij_en":"Good: Narrated by Ibn Khuzaymah (273), Ibn Ḥibbān (1314), Ibn al-Jārūd (128), and al-Ḥākim (585).","chapter_en":"An Injured Person May Perform Tayammum","part_en":"The Book of Tayammum","group_ar":"","group_en":"","part_no":8,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Ibn ʿAbbās reported that a man became junub during winter. He asked for a ruling and was instructed to perform ghusl. He performed ghusl and died. This was mentioned to the Prophet ﷺ, who said: “What is wrong with them? They killed him! May Allah deal with them!”—three times—“Allah has made clean earth—or tayammum—a means of purification.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة (273)، وابن حبان (1314)، وابن الجارود (128)، والحاكم (585)."},{"num":1719,"demo":false,"sanad":"","matn":["عَنْ أَبِي الْجُهَيْمِ بْنِ الْحَارِثِ بْنِ الصِّمَّةِ قَالَ: أَقْبَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ نَحْوِ بِئْرِ جَمَلٍ، فَلَقِيَهُ رَجُلٌ فَسَلَّمَ عَلَيْهِ، فَلَمْ يَرُدَّ عَلَيْهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى أَقْبَلَ عَلَى الْجِدَارِ فَمَسَحَ بِوَجْهِهِ وَيَدَيْهِ، ثُمَّ رَدَّ عَلَيْهِ السَّلَامَ."],"takhrij":"متَّفقٌ عليه: أخرجه البخاري (337) ومسلم في الحيض (369) كلاهما من الليث بن سعد، عن جعفر بن ربيعة، عن عبدالرحمن بن هرمز، قال: سمعت عُميراً مولى ابن عباس قال: أقبلت أنا وعبدالله بن يسار مولى ميمونة زوج النبي صلى الله عليه وسلم حتَّى دخلنا على أبي جُهيم فقال أبو جُهيم: فذكر الحديث. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب التيمم لرد السلام","chapter_ur":"","part_ar":"كتاب التيمم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (337) and Muslim (369). This wording is that of al-Bukhārī.","chapter_en":"Performing Tayammum in Order to Return the Greeting of Salām","part_en":"The Book of Tayammum","group_ar":"","group_en":"","part_no":8,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abū Juhaym ibn al-Ḥārith ibn al-Ṣimmah said: The Prophet ﷺ came from the direction of Biʾr Jamal. A man met him and greeted him with salām, but the Prophet ﷺ did not return the greeting until he went to a wall, wiped his face and hands, and then returned the salām."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: أخرجه البخاري (337)، ومسلم (369)، واللفظ للبخاري."},{"num":1720,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ رَجُلًا مَرَّ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَبُولُ، فَسَلَّمَ، فَلَمْ يَرُدَّ عَلَيْهِ."],"takhrij":"صحيح: رواه مسلم في الحيض (370) عن محمد بن عبدالله بن نمير، حدَّثنا أبي، حدَّثنا سفيان، عن الضحاك بن عثمان، عن نافع، عن ابن عمر، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب التيمم لرد السلام","chapter_ur":"","part_ar":"كتاب التيمم","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (370).","chapter_en":"Performing Tayammum in Order to Return the Greeting of Salām","part_en":"The Book of Tayammum","group_ar":"","group_en":"","part_no":8,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿUmar reported that a man passed by while the Messenger of Allah ﷺ was urinating and greeted him with salām, but he did not return the greeting."]}},"tuhfa":{},"full":1,"dr":1,"rep":[1443,14246],"tks":"صحيح: رواه مسلم (370)."},{"num":1721,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ قَالَ: أَقْبَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْغَائِطِ فَلَقِيَهُ رَجُلٌ عِنْدَ بِئْرِ جَمَلٍ فَسَلَّمَ عَلَيْهِ، فَلَمْ يَرُدَّ عَلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى أَقْبَلَ عَلَى الْحَائِطِ فَوَضَعَ يَدَهُ عَلَى الْحَائِطِ ثُمَّ مَسَحَ وَجْهَهُ وَيَدَيْهِ، ثُمَّ رَدَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الرَّجُلِ السَّلَامَ."],"takhrij":"حسن: رواه أبو داود (331) عن جعفر بن مسافر، ثنا عبدالله بن يحيى البُرلُّسي، حدَّثنا حيوة بن شريح، عن ابن الهاد، أن نافعاً حدثه عن ابن عمر، فذكره.","grade":"حسن","chapter_ar":"باب التيمم لرد السلام","chapter_ur":"","part_ar":"كتاب التيمم","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (331).","chapter_en":"Performing Tayammum in Order to Return the Greeting of Salām","part_en":"The Book of Tayammum","group_ar":"","group_en":"","part_no":8,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ returned after relieving himself and met a man near Biʾr Jamal. The man greeted him with salām, but the Messenger of Allah ﷺ did not respond until he went to a wall, placed his hand upon it, wiped his face and hands, and then returned the man’s greeting."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (331)."},{"num":1722,"demo":false,"sanad":"","matn":["عَنْ طَارِقِ بْنِ شِهَابٍ، أَنَّ رَجُلًا أَجْنَبَ فَلَمْ يُصَلِّ، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ فَقَالَ: أَصَبْتَ، فَأَجْنَبَ رَجُلٌ آخَرَ فَتَيَمَّمَ وَصَلَّى، فَأَتَاهُ فَقَالَ: نَحْوَ مَا قَالَ لِلْآخَرِ يَعْنِي أَصَبْتَ."],"takhrij":"صحيح: رواه النسائي (324) قال: حدَّثنا محمد بن عبد الأعلى، قال: حدَّثنا خالد (بن الحارث) قال: أنبأنا شعبة، أن مخارقا أخبرهم، عن طارق، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب أجنب رجلان فتيمم أحدهما وصلى، ولم يصل الآخر","chapter_ur":"","part_ar":"كتاب التيمم","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasāʾī (324).","chapter_en":"Two Men Became Junub: One Performed Tayammum and Prayed, While the Other Did Not Pray","part_en":"The Book of Tayammum","group_ar":"","group_en":"","part_no":8,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Ṭāriq ibn Shihāb reported that a man became junub and did not pray. He came to the Prophet ﷺ and mentioned what he had done. He said: “You acted correctly.” Another man became junub, performed tayammum, and prayed. He then came to the Prophet ﷺ, who said to him something similar to what he had said to the first man, meaning: “You acted correctly.”"]},"buhuth":{"en":["In a narration of Aḥmad (18832):","“He did not criticize either of them.”","The Prophet’s ﷺ statement to both of them, “You acted correctly,” is explained here by the fact that each acted according to his own ijtihād, and the Prophet ﷺ acknowledged both efforts without declaring either of them mistaken.","It is also possible that this incident occurred before the revelation of the verse of tayammum while no water was available.","The phrase “he did not pray” means that he left the prayer during its prescribed time until he could perform ghusl and would then perform it as a make-up prayer after the time had ended."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (324)."},{"num":1723,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: خَرَجَ رَجُلَانِ فِي سَفَرٍ فَحَضَرَتِ الصَّلَاةُ وَلَيْسَ مَعَهُمَا مَاءٌ فَتَيَمَّمَا صَعِيدًا طَيِّبًا فَصَلَّيَا، ثُمَّ وَجَدَا الْمَاءَ فِي الْوَقْتِ فَأَعَادَ أَحَدُهُمَا الصَّلَاةَ وَالْوُضُوءَ وَلَمْ يُعِدِ الْآخَرُ، ثُمَّ أَتَيَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَا ذَلِكَ لَهُ، فَقَالَ لِلَّذِي لَمْ يُعِدْ: أَصَبْتَ السُّنَّةَ وَأَجْزَأَتْكَ صَلَاتُكَ، وَقَالَ لِلَّذِي تَوَضَّأَ وَأَعَادَ: لَكَ الْأَجْرُ مَرَّتَيْنِ."],"takhrij":"صحيح: رواه أبو داود (338) والنسائي (433) كلاهما من طريق عبدالله بن نافع، عن الليث بن سعد، عن بكر بن سوادة، عن عطاء بن يسار، عن أبي سعيد، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب المتيمم يجد الماء بعد ما صلى في الوقت","chapter_ur":"","part_ar":"كتاب التيمم","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (338) and al-Nasāʾī (433).","chapter_en":"A Person Who Performed Tayammum Finds Water after Having Prayed within the Prayer Time","part_en":"The Book of Tayammum","group_ar":"","group_en":"","part_no":8,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī said: Two men set out on a journey. The time for prayer arrived while they had no water, so they performed tayammum with clean earth and prayed. They later found water while the prayer time had not yet ended. One of them repeated his wuḍūʾ and prayer, while the other did not repeat the prayer. They then came to the Messenger of Allah ﷺ and told him what had happened. He said to the one who did not repeat: “You followed the Sunnah, and your prayer was sufficient for you.” He said to the one who performed wuḍūʾ and repeated the prayer: “You have the reward twice.”"]},"buhuth":{"en":["This hadith indicates that the person who has performed tayammum is treated as one who has attained ritual purification and may pray at the beginning of the prescribed time or later within it. If he subsequently finds water before the prayer time ends, the majority of scholars hold that he does not repeat the prayer. Al-Awzāʿī considered repetition recommended but did not regard it as obligatory."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (338)، والنسائي (433)."},{"num":1724,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كَانَ أَبُو ذَرٍّ يُحَدِّثُ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فُرِجَ عَنْ سَقْفِ بَيْتِي وَأَنَا بِمَكَّةَ، فَنَزَلَ جِبْرِيلُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَفَرَجَ صَدْرِي، ثُمَّ غَسَلَهُ بِمَاءِ زَمْزَمَ، ثُمَّ جَاءَ بِطَسْتٍ مِنْ ذَهَبٍ مُمْتَلِئٍ حِكْمَةً وَإِيمَانًا، فَأَفْرَغَهُ فِي صَدْرِي، ثُمَّ أَطْبَقَهُ، ثُمَّ أَخَذَ بِيَدِي فَعَرَجَ بِي إِلَى السَّمَاءِ الدُّنْيَا، فَلَمَّا جِئْتُ إِلَى السَّمَاءِ الدُّنْيَا، قَالَ جِبْرِيلُ لِخَازِنِ السَّمَاءِ: افْتَحْ، قَالَ: مَنْ هَذَا ؟ قَالَ: هَذَا جِبْرِيلُ، قَالَ: هَلْ مَعَكَ أَحَدٌ ؟ قَالَ: نَعَمْ، مَعِي مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: أُرْسِلَ إِلَيْهِ ؟ قَالَ: نَعَمْ، فَلَمَّا فَتَحَ عَلَوْنَا السَّمَاءَ الدُّنْيَا، فَإِذَا رَجُلٌ قَاعِدٌ عَلَى يَمِينِهِ أَسْوِدَةٌ وَعَلَى يَسَارِهِ أَسْوِدَةٌ، إِذَا نَظَرَ قِبَلَ يَمِينِهِ ضَحِكَ وَإِذَا نَظَرَ قِبَلَ يَسَارِهِ بَكَى، فَقَالَ: مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالِابْنِ الصَّالِحِ، قُلْتُ لِجِبْرِيلَ: مَنْ هَذَا ؟ قَال: هَذَا آدَمُ، وَهَذِهِ الْأَسْوِدَةُ عَنْ يَمِينِهِ وَشِمَالِهِ نَسَمُ بَنِيهِ، فَأَهْلُ الْيَمِينِ مِنْهُمْ أَهْلُ الْجَنَّةِ وَالْأَسْوِدَةُ الَّتِي عَنْ شِمَالِهِ أَهْلُ النَّارِ ؟ فَإِذَا نَظَرَ عَنْ يَمِينِهِ ضَحِكَ، وَإِذَا نَظَرَ قِبَلَ شِمَالِهِ بَكَى حَتَّى عَرَجَ بِي إِلَى السَّمَاءِ الثَّانِيَةِ، فَقَالَ لِخَازِنِهَا: افْتَحْ، فَقَالَ لَهُ خَازِنِهَا مِثْلَ مَا قَالَ الْأَوَّلُ، فَفَتَحَ.","قَالَ أَنَسِ بْنِ مَالِكٍ: فَذَكَرَ أَنَّهُ وَجَدَ فِي السَّمَوَات آدَمَ، وَإِدْرِيسَ، وَمُوسَى، وَعِيسَى، وَإِبْرَاهِيمَ صَلَوَاتُ اللَّهِ عَلَيْهِمْ، وَلَمْ يُثْبِتْ كَيْفَ مَنَازِلُهُمْ، غَيْرَ أَنَّهُ ذَكَرَ أَنَّهُ وَجَدَ آدَمَ فِي السَّمَاءِ الدُّنْيَا، وَإِبْرَاهِيمَ فِي السَّمَاءِ السَّادِسَةِ، قَالَ أَنَسٌ: فَلَمَّا مَرَّ جِبْرِيلُ بِالنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِإِدْرِيسَ، قَالَ: مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالْأَخِ الصَّالِحِ، فَقُلْتُ: مَنْ هَذَا ؟ قَالَ: هَذَا إِدْرِيسُ، ثُمَّ مَرَرْتُ بِمُوسَى، فَقَالَ: مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالْأَخِ الصَّالِحِ، قُلْتُ: مَنْ هَذَا ؟ قَالَ: هَذَا مُوسَى، ثُمَّ مَرَرْتُ بِعِيسَى، فَقَالَ: مَرْحَبًا بِالْأَخِ الصَّالِحِ وَالنَّبِيِّ الصَّالِحِ، قُلْتُ: مَنْ هَذَا ؟ قَالَ: هَذَا عِيسَى، ثُمَّ مَرَرْتُ بِإِبْرَاهِيمَ، فَقَالَ: مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالِابْنِ الصَّالِحِ، قُلْتُ: مَنْ هَذَا ؟ قَالَ هَذَا إِبْرَاهِيمُ.","قَالَ ابْنُ شِهَابٍ: فَأَخْبَرَنِي ابْنُ حَزْمٍ، أَنَّ ابْنَ عَبَّاسٍ، وَأَبَا حَبَّةَ الْأَنْصَارِيَّ كَانَا يَقُولَانِ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ثُمَّ عُرِجَ بِي حَتَّى ظَهَرْتُ لِمُسْتَوًى أَسْمَعُ فِيهِ صَرِيفَ الْأَقْلَامِ.","قَالَ ابْنُ حَزْمٍ، وَأَنَسُ بْنُ مَالِكٍ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَفَرَضَ اللَّهُ عَلَى أُمَّتِي خَمْسِينَ صَلَاةً، فَرَجَعْتُ بِذَلِكَ حَتَّى مَرَرْتُ عَلَى مُوسَى، فَقَالَ: مَا فَرَضَ اللَّهُ لَكَ عَلَى أُمَّتِكَ ؟ قُلْتُ: فَرَضَ خَمْسِينَ صَلَاةً، قَالَ: فَارْجِعْ إِلَى رَبِّكَ، فَإِنَّ أُمَّتَكَ لَا تُطِيقُ ذَلِكَ، فَرَاجَعْتُ فَوَضَعَ شَطْرَهَا، فَرَجَعْتُ إِلَى مُوسَى، قُلْتُ: وَضَعَ شَطْرَهَا، فَقَالَ: رَاجِعْ رَبَّكَ، فَإِنَّ أُمَّتَكَ لَا تُطِيقُ، فَرَاجَعْتُ: فَوَضَعَ شَطْرَهَا، فَرَجَعْتُ إِلَيْهِ، فَقَالَ: ارْجِعْ إِلَى رَبِّكَ فَإِنَّ أُمَّتَكَ لَا تُطِيقُ ذَلِكَ، فَرَاجَعْتُهُ، فَقَالَ: هِيَ خَمْسٌ وَهِيَ خَمْسُونَ لَا يُبَدَّلُ الْقَوْلُ لَدَيَّ، فَرَجَعْتُ إِلَى مُوسَى، فَقَالَ: رَاجِعْ رَبَّكَ، فَقُلْتُ: اسْتَحْيَيْتُ مِنْ رَبِّي، ثُمَّ انْطَلَقَ بِي حَتَّى انْتَهَى بِي إِلَى سِدْرَةِ الْمُنْتَهَى، وَغَشِيَهَا أَلْوَانٌ لَا أَدْرِي مَا هِيَ، ثُمَّ أُدْخِلْتُ الْجَنَّةَ فَإِذَا فِيهَا حَبَايِلُ اللُّؤْلُؤِ وَإِذَا تُرَابُهَا الْمِسْكُ."],"takhrij":"متفق عليه: رواه البخاريّ في الصلاة (349)، ومسلم في الإيمان (163) كلاهما من حديث يونس، عن ابن شهاب، عن أنس بن مالك، قال: كان أبو ذرّ يحدّث. فذكر الحديث مثله، واللّفظ لمسلم، ولفظ البخاريّ قريب منه.","grade":"متفق عليه","chapter_ar":"باب كيف وكم فرض الله على عباده من الصلوات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon — Authentic: Narrated by al-Bukhari (349) and Muslim (163). The wording here is Muslim’s.","chapter_en":"How and how many prayers Allah obligated upon His servants","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Malik said: Abu Dharr used to narrate that the Messenger of Allah ﷺ said: “The roof of my house was opened while I was in Makkah, and Gabriel came down and opened my chest. Then he washed it with water from Zamzam. Then he brought a golden basin filled with wisdom and faith, poured it into my chest, and then sealed it. Then he took my hand and ascended with me to the sky. When we reached the lowest heaven, Gabriel said to its gatekeeper: ‘Open.’ He said: ‘Who is this?’ He said: ‘Gabriel.’ He said: ‘Do you have anyone with you?’ He said: ‘Yes, Muhammad ﷺ is with me.’ He said: ‘Has he been sent for?’ He said: ‘Yes.’ So he opened. When we ascended into the lowest heaven, there was a man with dark crowds to his right and dark crowds to his left. When he looked to his right he laughed, and when he looked to his left he wept. He said: ‘Welcome to the righteous Prophet and the righteous son.’ I said: ‘O Gabriel, who is this?’ He said: ‘This is Adam, peace be upon him. These dark crowds to his right and left are the souls of his descendants: the people on the right are the people of Paradise, and the dark crowds on his left are the people of the Fire. When he looks to his right he laughs, and when he looks to his left he weeps.’ Then Gabriel ascended with me until he reached the second heaven, and he said to its gatekeeper: ‘Open.’ The gatekeeper said to him the same as the gatekeeper of the lowest heaven had said, and he opened.”","Anas ibn Malik said: He mentioned that he encountered in the heavens Adam, Idris, Jesus, Moses, and Abraham—peace be upon them all—though he did not specify their exact levels, except that he said he found Adam in the lowest heaven and Abraham in the sixth heaven. He said: When Gabriel and the Messenger of Allah ﷺ passed by Idris, he said: ‘Welcome to the righteous Prophet and the righteous brother.’ I asked: ‘Who is this?’ He said: ‘This is Idris.’ Then I passed by Moses, who said: ‘Welcome to the righteous Prophet and the righteous brother.’ I asked: ‘Who is this?’ He said: ‘This is Moses.’ Then I passed by Jesus, who said: ‘Welcome to the righteous Prophet and the righteous brother.’ I asked: ‘Who is this?’ He said: ‘This is Jesus son of Mary.’ Then I passed by Abraham, who said: ‘Welcome to the righteous Prophet and the righteous son.’ I asked: ‘Who is this?’ He said: ‘This is Abraham.’","Ibn Shihab said: Ibn Hazm informed me that Ibn Abbas and Abu Habba al-Ansari used to say that the Messenger of Allah ﷺ said: “Then I was taken up until I reached a level where I could hear the scratching of the pens.” Ibn Hazm and Anas ibn Malik said: The Messenger of Allah ﷺ said: “Allah obligated fifty prayers upon my community.” He said: I returned with that until I passed by Moses. Moses, peace be upon him, said: “What did your Lord obligate upon your community?” I said: “He obligated fifty prayers upon them.” He said: “Go back to your Lord, for your community will not be able to bear that.” He said: So I went back to my Lord and He reduced it by half. I returned to Moses and informed him. He said: “Go back to your Lord, for your community will not be able to bear that.” So I went back to my Lord, and He said: “They are five, yet they are fifty; My word is not changed.” I returned to Moses and he said: “Go back to your Lord.” I said: “I have become too shy before my Lord.”","Then Gabriel took me until he reached the Lote Tree of the Utmost Boundary, and it was covered with colors I cannot describe. Then I was admitted into Paradise, and there were domes of pearls, and its soil was musk.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (349)، ومسلم (163)، واللفظ لمسلم."},{"num":1725,"demo":false,"sanad":"","matn":["عَنْ طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ يَقُولُ: جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ أَهْلِ نَجْدٍ ثَائِرَ الرَّأْسِ يُسْمَعُ دَوِيُّ صَوْتِهِ وَلَا يُفْقَهُ مَا يَقُولُ حَتَّى دَنَا، فَإِذَا هُوَ يَسْأَلُ عَنِ الْإِسْلَامِ ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خَمْسُ صَلَوَاتٍ فِي الْيَوْمِ وَاللَّيْلَةِ، فَقَالَ: هَلْ عَلَيَّ غَيْرُهَا ؟ قَالَ: لَا إِلَّا أَنْ تَطَوَّعَ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَصِيَامُ رَمَضَانَ، قَالَ: هَلْ عَلَيَّ غَيْرُهُ ؟ قَالَ: لَا إِلَّا أَنْ تَطَوَّعَ، قَالَ: وَذَكَرَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الزَّكَاةَ، قَالَ: هَلْ عَلَيَّ غَيْرُهَا ؟ قَالَ: لَا إِلَّا أَنْ تَطَوَّعَ، قَالَ: فَأَدْبَرَ الرَّجُلُ وَهُوَ يَقُولُ: وَاللَّهِ لَا أَزِيدُ عَلَى هَذَا وَلَا أَنْقُصُ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَفْلَحَ إِنْ صَدَقَ."],"takhrij":"متفق عليه: رواه مالك في قصر الصلاة (94) عن عمه أبي سُهيل بن مالك، عن أبيه، أنه سمع طلحة بن عبيد الله فذكر الحديث، ورواه البخاري عن إسماعيل، عن مالك في الإيمان (46)، ومسلم في الإيمان (8) عن قتيبة بن سعيد بن جميل بن طريف بن عبدالله الثقفي، عن مالك، ومضى هذا الحديث بكامله في كتاب الإيمان.","grade":"متفق عليه","chapter_ar":"باب كيف وكم فرض الله على عباده من الصلوات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon — Authentic: Malik (94), al-Bukhari (46), Muslim (8).","chapter_en":"How and how many prayers Allah obligated upon His servants","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Talhah ibn ‘Ubaydillah said: A man from the people of Najd came to the Messenger of Allah ﷺ, with unkempt hair; we could hear his loud voice but could not understand what he was saying until he came close—then it became clear that he was asking about Islam. The Messenger of Allah ﷺ said, “Five prayers in the day and night.” The man asked, “Do I have to do anything besides them?” He said, “No—unless you do extra voluntarily.” The Messenger of Allah ﷺ then said, “And fasting Ramadan.” The man asked, “Do I have to do anything besides it?” He said, “No—unless you do extra voluntarily.” Then the Messenger of Allah ﷺ mentioned zakah. The man asked, “Do I have to do anything besides it?” He said, “No—unless you do extra voluntarily.” The man turned away saying, “By Allah, I will not add to this, nor will I subtract from it.” The Messenger of Allah ﷺ said, “He has succeeded, if he is truthful.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (94)، والبخاري (46)، ومسلم (8)."},{"num":1726,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: فُرِضَتْ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةَ أُسْرِيَ بِهِ الصَّلَوَاتُ خَمْسِينَ، ثُمَّ نُقِصَتْ حَتَّى جُعِلَتْ خَمْسًا، ثُمَّ نُودِيَ: يَا مُحَمَّدُ إِنَّهُ لَا يُبَدَّلُ الْقَوْلُ لَدَيَّ وَإِنَّ لَكَ بِهَذِهِ الْخَمْسِ خَمْسِينَ."],"takhrij":"متفق عليه: رواه الترمذي في الصلاة (213) بهذا اللفظ مختصراً عن محمد بن يحيى النيسابوري، ثنا عبد الرزاق، نا معمر، عن الزهري، عن أنس.","grade":"متفق عليه","chapter_ar":"باب كيف وكم فرض الله على عباده من الصلوات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon — Authentic: al-Tirmidhi (213 — “Hasan Sahih Gharib”), al-Bukhari (3207), Muslim (163).","chapter_en":"How and how many prayers Allah obligated upon His servants","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Anas said: On the night the Prophet ﷺ was taken on the Night Journey, fifty prayers were obligated upon him, then they were reduced until they became five. Then it was called out: “O Muhammad, My decree is not changed, and for these five you will have the reward of fifty.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3207)، ومسلم (163). ورواه الترمذي (213) وقال: حسن صحيح غريب."},{"num":1727,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قال: سَأَلَ رَجُلٌ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، كَمْ افْتَرَضَ اللَّهُ عَزَّ وَجَلَّ عَلَى عِبَادِهِ مِنَ الصَّلَوَاتِ ؟ قَالَ: افْتَرَضَ اللَّهُ عَلَى عِبَادِهِ صَلَوَاتٍ خَمْسًا، قَالَ: يَا رَسُولَ اللَّهِ، هَلْ قَبْلَهُنَّ أَوْ بَعْدَهُنَّ شَيْئًا ؟ قَالَ: افْتَرَضَ اللَّهُ عَلَى عِبَادِهِ صَلَوَاتٍ خَمْسًا، فَحَلَفَ الرَّجُلُ لَا يَزِيدُ عَلَيْهِ شَيْئًا وَلَا يَنْقُصُ مِنْهُ شَيْئًا، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنْ صَدَقَ لَيَدْخُلَنَّ الْجَنَّةَ."],"takhrij":"صحيح: رواه النسائي (459) عن قتيبة قال: ثنا نوح بن قيس، عن خالد بن قيس، عن قتادة، عن أنس، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب كيف وكم فرض الله على عباده من الصلوات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: al-Nasa’i (459). (A longer version is also narrated by Muslim (10).)","chapter_en":"How and how many prayers Allah obligated upon His servants","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Anas said: A man asked the Prophet of Allah ﷺ, “O Messenger of Allah, how many prayers has Allah obligated upon His servants?” He replied, “Allah has obligated five prayers upon His servants.” The man asked, “Is there anything before them or after them (that is obligatory)?” He replied, “Allah has obligated five prayers upon His servants.” The man swore he would not add anything to them and would not subtract anything from them. The Messenger of Allah ﷺ said, “If he is truthful, he will surely enter Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (459). ورواه مسلم (10) مطولا."},{"num":1728,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ الصُّنَابِحِيِّ قَالَ: زَعَمَ أَبُو مُحَمَّدٍ أَنَّ الْوِتْرَ وَاجِبٌ، فَقَالَ عُبَادَةُ بْنُ الصَّامِتِ: كَذَبَ أَبُو مُحَمَّدٍ، أَشْهَدُ أَنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: خَمْسُ صَلَوَاتٍ افْتَرَضَهُنَّ اللَّهُ تَعَالَى، مَنْ أَحْسَنَ وُضُوءَهُنَّ وَصَلَّاهُنَّ لِوَقْتِهِنَّ وَأَتَمَّ رُكُوعَهُنَّ وَخُشُوعَهُنَّ كَانَ لَهُ عَلَى اللَّهِ عَهْدٌ أَنْ يَغْفِرَ لَهُ، وَمَنْ لَمْ يَفْعَلْ فَلَيْسَ لَهُ عَلَى اللَّهِ عَهْدٌ، إِنْ شَاءَ غَفَرَ لَهُ وَإِنْ شَاءَ عَذَّبَهُ."],"takhrij":"صحيح: رواه أبو داود (425) عن محمد بن حرب الواسطي، حدثنا يزيد بن هارون، حدثنا محمد بن مطرف، عن زيد بن أسلم، عن عطاء بن يسار، عن عبد الله ابن الصُّنابحي، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب كيف وكم فرض الله على عباده من الصلوات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Abu Dawud (425), Ahmad (22704).","chapter_en":"How and how many prayers Allah obligated upon His servants","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["‘Abdullah ibn al-Sunabihi said: Abu Muhammad claimed that witr is obligatory. ‘Ubadah ibn al-Samit said: “Abu Muhammad has lied! I testify that I heard the Messenger of Allah ﷺ say: ‘Five prayers Allah the Exalted has obligated. Whoever perfects their wudu’, prays them at their proper times, and completes their bowing and humility within them—Allah has a covenant to forgive him. Whoever does not do that has no covenant with Allah: if He wills, He will forgive him; and if He wills, He will punish him.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (425)، وأحمد (22704)."},{"num":1729,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خَمْسٌ مَنْ جَاءَ بِهِنَّ مَعَ إِيمَانٍ دَخَلَ الْجَنَّةَ: مَنْ حَافَظَ عَلَى الصَّلَوَاتِ الْخَمْسِ عَلَى وُضُوئِهِنَّ وَرُكُوعِهِنَّ وَسُجُودِهِنَّ وَمَوَاقِيتِهِنَّ، وَصَامَ رَمَضَانَ، وَحَجَّ الْبَيْتَ إِنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا، وَأَعْطَى الزَّكَاةَ طَيِّبَةً بِهَا نَفْسُهُ، وَأَدَّى الْأَمَانَةَ، قَالُوا: يَا أَبَا الدَّرْدَاءِ! وَمَا أَدَاءُ الْأَمَانَةِ ؟ قَالَ: الْغُسْلُ مِنَ الْجَنَابَةِ."],"takhrij":"حسن: رواه أبو داود (429) عن محمد بن عبد الرحمن العنبري، حدّثنا أبو علي الحنفي عبيد الله بن عبد المجيد، حدَّثنا عمران القطان، حدثنا قتادة وأبان، كلاهما عن خُليد القصري، عن أمّ الدرداء، عن أبي الدرداء فذكر مثله.","grade":"حسن","chapter_ar":"باب كيف وكم فرض الله على عباده من الصلوات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: Abu Dawud (429).","chapter_en":"How and how many prayers Allah obligated upon His servants","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu al-Darda’ said: The Messenger of Allah ﷺ said: “Five things—whoever comes with them along with faith will enter Paradise: whoever maintains the five prayers, with their wudu’, bowing, prostration, and their appointed times; fasts Ramadan; performs Hajj to the House if able to do so; gives zakah with a willing heart; and fulfills the trust.” They asked, “O Abu al-Darda’, what is fulfilling the trust?” He replied, “Performing the ritual bath after major ritual impurity (janabah).”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (429)."},{"num":1730,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: جَاءَ أَعْرَابِيٌّ مِنْ بَنِي سَعْدِ بْنِ بَكْرٍ إِلَى رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: السَّلَامُ عَلَيْكَ يَا غُلَامَ بَنِي عَبْدِ الْمُطَّلِبِ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَعَلَيْكَ السَّلَامُ . فَقَالَ: إِنِّي رَجُلٌ مِنْ أَخْوَالِكَ مِنْ بَنِي سَعْدِ بْنِ بَكْرٍ، وَأَنَا رَسُولُ قَوْمِي إِلَيْكَ وَوَافِدُهُمْ، وَإِنِّي سَائِلُكَ فَمُشْتَدَّةٌ مَسْأَلَتِي إِيَّاكَ، وَمُنَاشِدُكَ فَمُشْتَدَّةٌ مُنَاشَدَتِي إِيَّاكَ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: دُونَكَ يَا أَخَا بَنِي سَعْدٍ . فَقَالَ: مَنْ خَلَقَكَ، وَمَنْ خَلَقَ مَنْ قَبْلَكَ، وَمَنْ هُوَ خَالِقُ مَنْ بَعْدَكَ؟ قَالَ: اللهُ . قَالَ: فَنَشَدْتُكَ بِذَلِكَ، أَهُوَ أَرْسَلَكَ؟ قَالَ: نَعَمْ . قَالَ: أَخْبِرْنِي مَنْ خَلَقَ السَّمَاوَاتِ السَّبْعَ، وَالْأَرَضِينَ السَّبْعَ، وَأَجْرَى بَيْنَهُمِ الرِّزْقَ؟ قَالَ: اللهُ . قَالَ: فَنَشَدْتُكَ بِذَلِكَ، أَهُوَ أَرْسَلَكَ؟ قَالَ: نَعَمْ . قَالَ: فَإِنَّا قَدْ وَجَدْنَا فِي كِتَابِكَ، وَأَمَرَتْنَا رُسُلُكَ أَنْ نصَلِّيَ بِاللَّيْلِ وَالنَّهَارِ خَمْسَ صَلَوَاتٍ لِمَوَاقِيتِهَا، فَنَشَدْتُكَ بِذَلِكَ أَهُوَ أَمَرَكَ؟ قَالَ: نَعَمْ . قَالَ: فَإِنَّا قَدْ وَجَدْنَا فِي كِتَابِكَ، وَأَمَرَتْنَا رُسُلُكَ أَنْ نَصُومَ شَهْرَ رَمَضَانَ، فَنَشَدْتُكَ بِذَلِكَ، أَهُوَ أَمَرَكَ؟ قَالَ: نَعَمْ . قَالَ: فَإِنَّا قَدْ وَجَدْنَا فِي كِتَابِكَ، وَأَمَرَتْنَا رُسُلُكَ أَنْ تَأْخُذَ مِنْ حَوَاشِي أَمْوَالِنَا، فَتَجْعَلَهُ فِي فُقَرَائِنَا، فَنَشَدْتُكَ بِذَلِكَ، أَهُوَ أَمَرَكَ؟ قَالَ: نَعَمْ . قَالَ: أَمَّا الْخَامِسَةُ فَلَسْتُ سَائِلًا عَنْهَا، وَلَا أَرَبَ لِي فِيهَا يَعْنِي الْفَوَاحِشَ ثُمَّ قَالَ: أَمَا وَالَّذِي بَعَثَكَ بِالْحَقِّ لَأَعْمَلَنَّ بِهَا، وَمَنْ أَطَاعَنِي مِنْ قَوْمِي، ثُمَّ رَجَعَ فَضَحِكَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى بَدَتْ نَوَاجِذُهُ، ثُمَّ قَالَ: لَئِنْ صَدَقَ لَيَدْخُلَنَّ الْجَنَّةَ."],"takhrij":"صحيح: رواه الطبراني في الكبير (8151) وابن خزيمة (2383) والدارمي (677) وابن أبي شيبة (14914) كلهم من حديث محمد بن فضيل بن غزوان، ثنا عطاء بن السائب وموسى بن السائب أبو جعفر، عن سالم بن أبي الجعد، عن ابن عباس فذكره. ومحمد بن فضيل حسن الحديث مع تشيعه لكنه توبع.","grade":"صحيح","chapter_ar":"باب كيف وكم فرض الله على عباده من الصلوات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authenticated as sound: al-Tabarani, al-Mu‘jam al-Kabir (Volume 8, p. 366), Ibn Khuzaymah (2383), Ibn Abi Shaybah (14914).","chapter_en":"How and how many prayers Allah obligated upon His servants","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Ibn ‘Abbas said: A Bedouin from Banu Sa‘d ibn Bakr came to the Messenger of Allah ﷺ and said, “Peace be upon you, O young man of Banu ‘Abd al-Muttalib.” The Prophet ﷺ replied, “And peace be upon you.” He said, “I am a man from your maternal relatives of Banu Sa‘d ibn Bakr. I am my people’s envoy to you and their delegate. I will question you, and my questioning will be intense, and my appeal to you will be intense.” The Prophet ﷺ said, “Go ahead, O brother of Banu Sa‘d.” The man said, “Who created you, and who created those before you, and who will be the Creator after you?” He replied, “Allah.” He said, “I ask you by that: did He send you?” He replied, “Yes.” He said, “Tell me: who created the seven heavens and the seven earths and caused provision to flow among them?” He replied, “Allah.” He said, “I ask you by that: did He send you?” He replied, “Yes.” He said, “We have found in your Book, and your messengers commanded us, that we should pray five prayers by day and night at their appointed times—so I ask you by that: did He command you with this?” He replied, “Yes.” He said, “And we have found in your Book, and your messengers commanded us, that we should fast the month of Ramadan—so I ask you by that: did He command you with this?” He replied, “Yes.” He said, “And we have found in your Book, and your messengers commanded us, that you take a portion from our wealth and give it to our poor—so I ask you by that: did He command you with this?” He replied, “Yes.” He said, “As for the fifth, I will not ask about it, and I have no desire for it”—meaning indecencies. Then he said, “By the One who sent you with the truth, I will surely act upon these, and so will whoever obeys me from my people.” Then he left. The Messenger of Allah ﷺ laughed until his molar teeth became visible, then said, “If he is truthful, he will surely enter Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في المعجم الكبير (8151)، وابن خزيمة (2383)، وابن أبي شيبة (14914)."},{"num":1731,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّهَا سَمِعَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ اللَّهَ افْتَرَضَ عَلَى الْعِبَادِ خَمْسَ صَلَوَاتٍ فِي كُلِّ يَوْمٍ وَلَيْلَةٍ."],"takhrij":"حسن: رواه الطبراني في الأوسط (7268)، مجمع البحرين (523) عن محمد بن راشد، ثنا عصام بن روّاد بن الجراح، ثنا أبي، ثنا نافع بن عمر، عن ابن أبي مليكة، عن عروة، حدثتني عائشة فذكرتْه.","grade":"حسن","chapter_ar":"باب كيف وكم فرض الله على عباده من الصلوات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: al-Tabarani, al-Mu‘jam al-Awsat (also cited in Majma‘ al-Bahrayn, item 523).","chapter_en":"How and how many prayers Allah obligated upon His servants","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["‘A’ishah reported that she heard the Messenger of Allah ﷺ say: “Allah has obligated upon the servants five prayers in every day and night.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في المعجم الأوسط، كما في مجمع البحرين (523)."},{"num":1732,"demo":false,"sanad":"","matn":["عَنْ جَرِيرِ بْنِ عَبْدِ اللَّهِ قَالَ: بَايَعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى إِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَالنُّصْحِ لِكُلِّ مُسْلِمٍ."],"takhrij":"متفق عليه: رواه البخاريّ في مواقيت الصّلاة (524)، ومسلم في الإيمان (56) كلاهما من حديث إسماعيل بن أبي خالد، عن قيس، عن جرير بن عبد الله، فذكره.","grade":"متفق عليه","chapter_ar":"باب البيعة على إقامة الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon — Authentic: al-Bukhari (524), Muslim (56).","chapter_en":"The pledge (bay‘ah) to establish the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Jarir ibn ‘Abdillah said: I pledged allegiance to the Messenger of Allah ﷺ to establish the prayer, to give zakah, and to sincerely advise every Muslim."]}},"tuhfa":{},"full":1,"rep":[144],"tks":"متفق عليه: رواه البخاري (524)، ومسلم (56)."},{"num":1733,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: لَمَّا تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَاسْتُخْلِفَ أَبُو بَكْر بَعْدَهُ، وَكَفَرَ مَنْ كَفَرَ مِنَ الْعَرَبِ، قَالَ عُمَرُ بْنُ الْخَطَّابِ لِأَبِي بَكْرٍ: كَيْفَ تُقَاتِلُ النَّاسَ ؟ وَقَدْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ، حَتَّى يَقُولُوا، لَا إِلَهَ إِلَّا اللَّهُ، فَمَنْ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ، فَقَدْ عَصَمَ مِنِّي مَالَهُ وَنَفْسَهُ إِلَّا بِحَقِّهِ، وَحِسَابُهُ عَلَى اللَّهِ، فَقَالَ أَبُو بَكْرٍ: وَاللَّهِ لَأُقَاتِلَنَّ مَنْ فَرَّقَ بَيْنَ الصَّلَاةِ وَالزَّكَاةِ، فَإِنَّ الزَّكَاةَ حَقُّ الْمَالِ، وَاللَّهِ لَوْ مَنَعُونِي عِقَالًا كَانُوا يُؤَدُّونَهُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَقَاتَلْتُهُمْ عَلَى مَنْعِهِ، فَقَالَ عُمَرُ بْنُ الْخَطَّابِ: فَوَاللَّهِ مَا هُوَ إِلَّا أَنْ رَأَيْتُ اللَّهَ عَزَّ وَجَلَّ، قَدْ شَرَحَ صَدْرَ أَبِي بَكْرٍ لِلْقِتَالِ، فَعَرَفْتُ أَنَّهُ الْحَقُّ."],"takhrij":"متفق عليه: رواه البخاريّ في الزّكاة (1399)، ومسلم في الإيمان (20) كلاهما من حديث الزهري، قال: أخبرني عبيد الله بن عبد الله بن عتبة بن مسعود، عن أبي هريرة، فذكره، واللّفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب قتال تارك الصلاة والزكاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon — Authentic: al-Bukhari (1399), Muslim (20) — wording here is Muslim’s.","chapter_en":"Fighting those who abandon prayer and zakah","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah said: When the Messenger of Allah ﷺ passed away and Abu Bakr became the caliph after him, and some of the Arabs fell into disbelief, ‘Umar ibn al-Khattab said to Abu Bakr: “How can you fight the people when the Messenger of Allah ﷺ said: ‘I have been commanded to fight the people until they say: There is no god but Allah. Whoever says: There is no god but Allah—his life and wealth are protected from me except by its due right, and his reckoning is with Allah’?” Abu Bakr replied: “By Allah, I will fight whoever separates between prayer and zakah, for zakah is the due right of wealth. By Allah, if they withhold from me even a rope (or tether) that they used to give to the Messenger of Allah ﷺ, I will fight them over withholding it.” ‘Umar said: “By Allah, it was only that I saw Allah, Mighty and Majestic, had expanded Abu Bakr’s chest to fight, and I knew it was the truth.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1399)، ومسلم (20)، واللفظ لمسلم."},{"num":1734,"demo":false,"sanad":"","matn":["عَنْ جَابِرًا يَقُولُ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ بَيْنَ الرَّجُلِ وَبَيْنَ الشِّرْكِ وَالْكُفْرِ تَرْكَ الصَّلَاةِ."],"takhrij":"صحيح: رواه مسلم في الإيمان (82) من طريقين: أبو سفيان، وأبو الزبير، كلاهما عن جابر بن عبد الله قال: فذكره.","grade":"صحيح","chapter_ar":"باب حكم تارك الصلاة متعمداً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Muslim (82).","chapter_en":"The ruling regarding one who deliberately abandons the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Jabir said: I heard the Prophet ﷺ say: “Between a person and shirk and kufr is abandoning the prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (82)."},{"num":1735,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ حُصَيْبٍ الأَسْلَمِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الْعَهْدَ الَّذِي بَيْنَنَا وَبَيْنَهُمُ الصَّلَاةُ، فَمَنْ تَرَكَهَا فَقَدْ كَفَرَ."],"takhrij":"حسن: رواه الترمذي (2621)، والنسائي (462) وابن ماجه(1079) كلهم من طريق حسين بن واقد، قال: حدثنا عبدالله بن بريدة، عن أبيه فذكر مثله.","grade":"حسن","chapter_ar":"باب حكم تارك الصلاة متعمداً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Good: al-Tirmidhi (2621), al-Nasa’i (464), and Ibn Majah (1079). Al-Tirmidhi said: “Hasan Sahih Gharib.”","chapter_en":"The ruling regarding one who deliberately abandons the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Buraydah ibn al-Husayb al-Aslami said: The Messenger of Allah ﷺ said: “The covenant between us and them is the prayer; whoever abandons it has committed disbelief.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2621)، والنسائي (462)، وابن ماجه (1079). وقال الترمذي: حسن صحيح غريب."},{"num":1736,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: بَيْنَ الْعَبْدِ وَبَيْنَ الْكُفْرِ وَالْإِيمَانِ الصَّلَاةُ فَإِذَا تَرَكَهَا فَقَدْ أَشْرَكَ."],"takhrij":"صحيح: رواه اللالكائيّ في أصول الاعتقاد (1521) من طريق شعيب بن إسحاق الدّمشقيّ، ثنا أبو المغيرة (هو عبد القدوس بن الحجاج)، ثنا الأوزاعي، ثنا الوليد بن هشام، ثنا معدان بن أبي طلحة، قال: قلت لثوبان مولى رسول الله صلى الله عليه وسلم حدّثنا حديثاً ينفعنا الله به، فسكت، فقلت: حدّثنا حديثاً ينفعنا الله به، قال (فذكره).","grade":"صحيح","chapter_ar":"باب حكم تارك الصلاة متعمداً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: al-Lālakā’ī, Sharḥ Uṣūl I‘tiqād Ahl al-Sunnah (1521).","chapter_en":"The ruling regarding one who deliberately abandons the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Thawban, the freed slave of the Messenger of Allah ﷺ, said: I heard the Messenger of Allah ﷺ say: “Between a servant and disbelief and faith is the prayer; if he abandons it, then he has committed shirk.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه اللالكائي في شرح أصول اعتقاد أهل السنة (1521)."},{"num":1737,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ قَالَ: أَوْصَانِي خَلِيلِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ لَا تُشْرِكْ بِاللَّهِ شَيْئًا، وَإِنْ قُطِّعْتَ وَحُرِّقْتَ، وَلَا تَتْرُكْ صَلَاةً مَكْتُوبَةً مُتَعَمِّدًا فَمَنْ تَرَكَهَا مُتَعَمِّدًا فَقَدْ بَرِئَتْ مِنْهُ الذِّمَّةُ، وَلَا تَشْرَبْ الْخَمْرَ، فَإِنَّهَا مِفْتَاحُ كُلِّ شَرٍّ."],"takhrij":"حسن: رواه ابن ماجه (4034) من طريق راشد أبي محمد الحِمَّاني، عن شهر","grade":"حسن","chapter_ar":"باب حكم تارك الصلاة متعمداً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: Ibn Mājah (4034), al-Bukhārī in al-Adab al-Mufrad (18).","chapter_en":"The ruling regarding one who deliberately abandons the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Abu al-Darda’ said: The Prophet ﷺ, my close friend, advised me: “Do not associate anything with Allah, even if you are cut to pieces and burned. Do not deliberately leave an obligatory prayer—whoever deliberately leaves it, protection (covenant) is disavowed from him. And do not drink wine, for it is the key to every evil.”"]},"buhuth":{"en":["What is meant by “abandoning the prayer” here is abandoning it while denying that it is obligatory. As for someone who leaves one or two prayers out of laziness and negligence, or prays only occasionally, then the apparent meaning is that he is not judged a disbeliever—because he has not abandoned prayer entirely, and the wording of the hadith is “abandoning the prayer.”","So this is abandoning “a prayer” (a single prayer), not abandoning “the prayer” altogether. The default ruling is that a person remains within Islam, and he is not removed from it except with certainty. Whatever is established with certainty is not removed except with certainty. See: al-Sharḥ al-Mumti‘ (2/24–28)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (4034)، والبخاري في الأدب المفرد (18)."},{"num":1738,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَعْظَمُ النَّاسِ أَجْرًا فِي الصَّلَاةِ أَبْعَدُهُمْ فَأَبْعَدُهُمْ مَمْشًى، وَالَّذِي يَنْتَظِرُ الصَّلَاةَ حَتَّى يُصَلِّيَهَا مَعَ الْإِمَامِ أَعْظَمُ أَجْرًا مِنَ الَّذِي يُصَلِّي ثُمَّ يَنَامُ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (651) واللفظ له، ومسلم في المساجد (662) كلاهما من طريق أبي أسامة، عن يزيد بن عبد الله، عن أبي بردة، عن أبي موسى، وزاد حتى يصليها مع الإمام في جماعة.","grade":"متفق عليه","chapter_ar":"باب فضل المشي إلى الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon — Authentic: al-Bukhari (651 — wording here is his), Muslim (662). (Muslim includes the addition: “with the imam in congregation.”)","chapter_en":"The virtue of walking to the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abu Musa reported that the Prophet ﷺ said: “The people with the greatest reward in prayer are those who walk the farthest (to it). And the one who waits for the prayer until he prays it with the imam has a greater reward than the one who prays and then sleeps.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (651) واللفظ له، ومسلم (662). وفي رواية مسلم زيادة: «مع الإمام في جماعة»."},{"num":1739,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ غَدَا إِلَى الْمَسْجِدِ وَرَاحَ أَعَدَّ اللَّهُ لَهُ نُزُلَهُ مِنَ الْجَنَّةِ كُلَّمَا غَدَا أَوْ رَاحَ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (662)، ومسلم في المساجد (669)، كلاهما من طريق يزيد بن هارون، قال: أخبرنا محمد بن مُطَرِّف، عن زيد بن أسلم، عن عطاء بن يسار، عن أبي هريرة واللفظ للبخاري، وفي لفظ مسلم: في الجنة نزُلاً.والنُزل: هو ما يُهيأ للضيف عند قدومه.","grade":"متفق عليه","chapter_ar":"باب فضل المشي إلى الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon — Authentic: al-Bukhari (662 — wording here is his), Muslim (669).","chapter_en":"The virtue of walking to the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “Whoever goes to the mosque in the morning and in the evening—Allah prepares for him his hospitality in Paradise each time he goes or returns.”"]},"buhuth":{"ar":["والنُّزل: هو ما يُهيَّأ للضيف عند قدومه."],"en":["“Hospitality” (nuzul) is what is prepared for a guest upon his arrival."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (662) واللفظ له، ومسلم (669)."},{"num":1740,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا بَنِي سَلِمَةَ، أَلَا تَحْتَسِبُونَ آثَارَكُمْ ؟.","قَالَ مُجَاهِدٌ فِي قَوْلِهِ: ﴿وَنَكْتُبُ مَا قَدَّمُوا وَآثَارَهُمْ﴾ [ يس: 12]، قَالَ خُطَاهُمْ."],"takhrij":"صحيح: رواه البخاري في الأذان (655)، وفي رواية bukhari(656): أن بني سلمة أرادوا أن يتحولوا عن منازلهم، فينـزلوا قريباً من النبي صلى الله عليه وسلم قال: فكره رسول الله صلى الله عليه وسلم أن يُعرُوا المدينة فقال: ألا تحتسبون آثاركم.","grade":"صحيح","chapter_ar":"باب فضل المشي إلى الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: al-Bukhari (655). In another narration (656): Banu Salimah wanted to move from their homes to live closer to the Prophet ﷺ, and he disliked that the city be left sparse, so he said: “Will you not count your footsteps?”","chapter_en":"The virtue of walking to the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Anas reported that the Prophet ﷺ said: “O Banu Salimah, will you not count (for reward) your footsteps?” Mujahid, regarding Allah’s statement: “And We record what they sent ahead and their traces” [Ya-Sin 36:12], said: meaning their footsteps."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (655). وفي رواية له bukhari(656): أن بني سلمة أرادوا الانتقال من منازلهم إلى قرب النبي ﷺ، فكره أن تعرى المدينة، فقال: «ألا تحتسبون آثاركم؟»."},{"num":1741,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ تَطَهَّرَ فِي بَيْتِهِ، ثُمَّ مَشَى إِلَى بَيْتٍ مِنْ بُيُوتِ اللَّهِ لِيَقْضِيَ فَرِيضَةً مِنْ فَرَائِضِ اللَّهِ، كَانَتْ خَطْوَتَاهُ إِحْدَاهُمَا تَحُطُّ خَطِيئَةً، وَالأُخْرَى تَرْفَعُ دَرَجَةً."],"takhrij":"صحيح: رواه مسلم في المساجد (666) من طريق عدي بن ثابت، عن أبي حازم الأشجعي، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب فضل المشي إلى الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Muslim (666).","chapter_en":"The virtue of walking to the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Whoever purifies himself in his home, then walks to one of Allah’s houses to fulfill an obligation from Allah’s obligations—his steps: one erases a sin, and the other raises him a rank.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (666)."},{"num":1742,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: كَانَتْ دِيَارُنَا نَائِيَةً عَنِ الْمَسْجِدِ، فَأَرَدْنَا أَنْ نَبِيعَ بُيُوتَنَا، فَنَقْتَرِبَ مِنَ الْمَسْجِدِ، فَنَهَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ لَكُمْ بِكُلِّ خَطْوَةٍ دَرَجَةً.","وَفِي رِوَايَةِ: قَالَ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: خَلَتِ الْبِقَاعُ حَوْلَ الْمَسْجِدِ، فَأَرَادَ بَنُو سَلِمَةَ، أَنْ يَنْتَقِلُوا إِلَى قُرْبِ الْمَسْجِدِ، فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لَهُمْ: إِنَّهُ بَلَغَنِي أَنَّكُمْ تُرِيدُونَ أَنْ تَنْتَقِلُوا قُرْبَ الْمَسْجِدِ ؟ قَالُوا: نَعَمْ يَا رَسُولَ اللَّهِ، قَدْ أَرَدْنَا ذَلِكَ، فَقَالَ: يَا بَنِي سَلِمَةَ، دِيَارَكُمْ تُكْتَبْ آثَارُكُمْ، دِيَارَكُمْ تُكْتَبْ آثَارُكُمْ.","وَفِي رِوَايَةِ: فَقَالُوا: مَا كَانَ يَسُرُّنَا أَنَّا كُنَّا تَحَوَّلْنَا."],"takhrij":"صحيح: رواه مسلم في المساجد (664) الرواية الأولى عن أبي الزبير قال: سمعت جابر بن عبدالله، والرواية الثانية والثالثة (665) عن أبي نضرة، عن جابر.","grade":"صحيح","chapter_ar":"باب فضل المشي إلى الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Muslim (664), and the second narration in Muslim (665).","chapter_en":"The virtue of walking to the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Jabir ibn ‘Abdillah said: Our homes were far from the mosque, so we wanted to sell our houses to move closer to the mosque. The Messenger of Allah ﷺ forbade us and said: “For every step you take, you receive a rank.” In another narration, Jabir said: The areas around the mosque became vacant, so Banu Salimah wanted to move nearer to the mosque. This reached the Messenger of Allah ﷺ and he said: “I have heard that you want to move closer to the mosque?” They said: “Yes, O Messenger of Allah, we intended that.” He said: “O Banu Salimah—stay in your homes; your footsteps are written. Stay in your homes; your footsteps are written.” They said: “It would not have pleased us to have moved.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (664)، والرواية الثانية عند مسلم (665)."},{"num":1743,"demo":false,"sanad":"","matn":["عَنْ أُبَيِّ بْنِ كَعْبٍ قَالَ: كَانَ رَجُلٌ، لَا أَعْلَمُ رَجُلًا أَبْعَدَ مِنَ الْمَسْجِدِ مِنْهُ، وَكَانَ لَا تُخْطِئُهُ صَلَاةٌ، قَالَ: فَقِيلَ لَهُ: أَوْ قُلْتُ لَهُ: لَوِ اشْتَرَيْتَ حِمَارًا تَرْكَبُهُ فِي الظَّلْمَاءِ، وَفِي الرَّمْضَاءِ ؟ قَالَ: مَا يَسُرُّنِي أَنَّ مَنْزِلِي إِلَى جَنْبِ الْمَسْجِدِ، إِنِّي أُرِيدُ أَنْ يُكْتَبَ لِي مَمْشَايَ إِلَى الْمَسْجِدِ، وَرُجُوعِي، إِذَا رَجَعْتُ إِلَى أَهْلِي، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَدْ جَمَعَ اللَّهُ لَكَ ذَلِكَ كُلَّهُ.","وَفِي رِوَايَةِ: كَانَ رَجُلٌ مِنَ الأَنْصَارِ، بَيْتُهُ أَقْصَى بَيْتٍ فِي الْمَدِينَةِ، فَكَانَ لَا تُخْطِئُهُ الصَّلَاةُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: فَتَوَجَّعْنَا لَهُ، فَقُلْتُ لَهُ: يَا فُلَانُ، لَوْ أَنَّكَ اشْتَرَيْتَ حِمَارًا يَقِيكَ مِنَ الرَّمْضَاءِ، وَيَقِيكَ مِنْ هَوَامِّ الأَرْضِ، قَالَ: أَمَ وَاللَّهِ مَا أُحِبُّ أَنَّ بَيْتِي مُطَنَّبٌ بِبَيْتِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: فَحَمَلْتُ بِهِ حِمْلًا، حَتَّى أَتَيْتُ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَخْبَرْتُهُ، قَالَ: فَدَعَاهُ، فَقَالَ لَهُ مِثْلَ ذَلِكَ وَذَكَرَ لَهُ: أَنَّهُ يَرْجُو فِي أَثَرِهِ الأَجْرَ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ لَكَ مَا احْتَسَبْتَ."],"takhrij":"صحيح: رواه مسلم في المساجد (663) الأولى من طريق سليمان التيمي، والثانية من طريق عاصم، كلاهما عن أبي عثمان النهدي، عن أبي بن كعب، فذكر مثله.","grade":"صحيح","chapter_ar":"باب فضل المشي إلى الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Muslim (663).","chapter_en":"The virtue of walking to the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Ubayy ibn Ka‘b said: There was a man— I do not know of anyone whose home was farther from the mosque than his—yet he would not miss a single prayer. It was said to him (or I said to him): “If only you bought a donkey to ride in the darkness and in the scorching heat.” He replied: “It would not please me for my home to be next to the mosque. I want my walking to the mosque to be recorded for me, and my return when I return to my family as well.” So the Messenger of Allah ﷺ said: “Allah has gathered all of that for you.”","In another narration: A man from the Ansar lived in the farthest house in Madinah, yet he never missed praying with the Messenger of Allah ﷺ. We felt concern for him, and I said: “So-and-so! If only you bought a donkey to protect you from the burning ground and from harmful creatures of the earth.” He said: “By Allah, I would not love that my house be ‘pitched’ right next to the house of Muhammad ﷺ.” So I carried that thought as a heavy burden until I came to the Prophet of Allah ﷺ and told him. He called the man and said the same to him, and the man mentioned that he hoped for reward in his footsteps. So the Prophet ﷺ said: “You will have what you sought reward for.”"]},"buhuth":{"en":["The phrase “mutannab” (with the letter nūn opened) means: “I would not like my house to be fastened by tent-ropes (pegs and ropes) right up to the house of the Prophet ﷺ,” i.e., he did not wish to live immediately adjacent; rather, he preferred being farther in order to increase his reward.","And the phrase “I carried it as a burden (hamlan)” means: his statement weighed heavily on me (it troubled me), not that he literally carried something on his back."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (663)."},{"num":1744,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا تَوَضَّأَ أَحَدُكُمْ فَأَحْسَنَ وُضُوءَهُ، ثُمَّ خَرَجَ إِلَى الْمَسْجِدِ لَا يَنْزِعُهُ إِلَّا الصَّلَاةُ، لَمْ تَزَلْ رِجْلُهُ الْيُسْرَى تَمْحُو سَيِّئَةً، وَتَكْتُبُ الْأُخْرَى حَسَنَةً حَتَّى يَدْخُلَ الْمَسْجِدَ."],"takhrij":"حسن: رواه الطبراني في الكبير (13328)، والحاكم (795) كلاهما من طريق كثير بن زيد، عن أبي عبد الله القرّاظ، عن ابن عمر قال: فذكره.","grade":"حسن","chapter_ar":"باب فضل المشي إلى الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: al-Ṭabarānī in al-Mu‘jam al-Kabīr (12/355), al-Ḥākim (790).","chapter_en":"The virtue of walking to the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Ibn ‘Umar reported that the Messenger of Allah ﷺ said: “When one of you performs wudu’ and does it well, then goes out to the mosque, with nothing driving him out except the prayer—his left foot continues to erase a sin, and the other (foot) continues to write a good deed, until he enters the mosque.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في المعجم الكبير (13328)، والحاكم (795)."},{"num":1745,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لِيَبْشَرِ الْمَشَّاءُونَ فِي الظُّلَمِ إِلَى الْمَسَاجِدِ بِنُورٍ تَامٍّ يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه ابن ماجه (780) عن إبراهيم بن محمد الحلبي، حدثنا يحيى بن الحارث الشيرازي، قال: حدثنا زهير بن محمد التميمي، عن أبي حازم، عن سهل بن سعد فذكره.","grade":"حسن","chapter_ar":"باب فضل المشي إلى الصلاة في الظلام","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: Ibn Mājah (780). Ibn Khuzaymah graded it authentic in his Ṣaḥīḥ (1498).","chapter_en":"The virtue of walking to prayer in darkness","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Sahl ibn Sa‘d al-Sa‘idi reported that the Messenger of Allah ﷺ said: “Give glad tidings to those who walk in the darkness (to the prayer): they will have complete light on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (780)، وصححه ابن خزيمة في صحيحه (1498)."},{"num":1746,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ، عَنْ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا تَطَهَّرَ الرَّجُلُ، ثُمَّ مَرَّ إِلَى الْمَسْجِدِ يَرْعَى الصَّلاةَ، كَتَبَ لَهُ كَاتِبُهُ أَوْ كَاتِبَاهُ، بِكُلِّ خُطْوَةٍ يَخْطُوهَا إِلَى الْمَسْجِدِ عَشْرَ حَسَنَاتٍ، وَالْقَاعِدُ يَرْعَى لِلصَّلاةِ كَالْقَانِتِ، وَيُكْتَبُ مِنَ الْمُصَلِّينَ، مِنْ حَيْثُ يَخْرُجُ مِنْ بَيْتِهِ حَتَّى يَرْجِعَ."],"takhrij":"صحيح: رواه الطبراني في الكبير في الكبير (13/ ح 831) وابن خزيمة (1492) وابن حبان (2045،2038) والحاكم في المستدرك (771) كلّهم من طريق عبد الله بن وهب، أخبرني عمرو بن الحارث، عن أبي عُشَّانة، أنّه سمع عقبة بن عامر الجهني يحدِّث عن رسول الله صلى الله عليه وسلم فذكر مثله، واللفظ لابن خزيمة.","grade":"صحيح","chapter_ar":"باب ما جاء أن منتظر الصلاة في المسجد كالقانت","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: al-Ṭabarānī in al-Mu‘jam al-Kabīr (17/301), Ibn Khuzaymah (1492 — and this is the wording).","chapter_en":"The one who waits for prayer in the mosque is like the devout worshipper","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["‘Uqbah ibn ‘Amir al-Juhani reported that the Messenger of Allah ﷺ said: “When a man purifies himself and then goes to the mosque, watching and waiting for the prayer, his scribe—or his two scribes—write for him ten good deeds for every step he takes to the mosque. And the one who sits waiting for the prayer is like the devout worshipper (qanit). And he is recorded among those praying from the moment he leaves his home until he returns.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في المعجم الكبير (13/ ح 831)، وابن خزيمة (1492)، واللفظ له."},{"num":1747,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ، أَنَّ رَجُلًا أَصَابَ مِنَ امْرَأَةٍ قُبْلَةً، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلّ:َ ﴿وَأَقِمِ الصَّلاةَ طَرَفَيِ النَّهَارِ وَزُلَفًا مِنَ اللَّيْلِ إِنَّ الْحَسَنَاتِ يُذْهِبْنَ السَّيِّئَاتِ﴾ [سورة هود: 114] فَقَالَ الرَّجُلُ: يَا رَسُولَ اللَّهِ، أَلِي هَذَا ؟ قَالَ: لِجَمِيعِ أُمَّتِي كُلِّهِمْ."],"takhrij":"متفق عليه: رواه البخاري في مواقيت الصلاة (526)، ومسلم في كتاب التوبة (2763) كلاهما عن قتيبة بن سعيد، قال: حدثنا يزيد بن زريع، عن سليمان التيمي، عن أبي عثمان النهدي، عن ابن مسعود، فذكر الحديث، واللفظ للبخاري، وفي لفظ مسلم لمن عمل بها من أمتي.","grade":"متفق عليه","chapter_ar":"باب أن الصلاة كفارة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon — Authentic: al-Bukhari (526 — wording here is his), Muslim (2763). Muslim’s wording: “For whoever acts upon it from my Ummah.”","chapter_en":"Prayer as expiation","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Ibn Mas‘ud said: A man kissed a woman, then came to the Prophet ﷺ and told him. Then Allah revealed: “Establish prayer at the two ends of the day and at early hours of the night. Indeed, good deeds erase bad deeds.” [Hud 11:114] The man said: “O Messenger of Allah, is this for me?” He replied: “For all of my Ummah—every one of them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (526) واللفظ له، ومسلم (2763). ولفظ مسلم: «لمن عمل بها من أمتي»."},{"num":1748,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، أَصَبْتُ حَدًّا فَأَقِمْهُ عَلَيَّ، قَالَ: وَحَضَرَتِ الصَّلَاةُ، فَصَلَّى مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا قَضَى الصَّلَاةَ، قَالَ: يَا رَسُولَ اللَّهِ إِنِّي أَصَبْتُ حَدًّا، فَأَقِمْ فِيَّ كِتَابَ اللَّهِ قَالَ: هَلْ حَضَرْتَ الصَّلَاةَ مَعَنَا ؟ قَالَ: نَعَمْ، قَالَ: قَدْ غُفِرَ لَكَ."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6823)، ومسلم في التوبة (2764) كلاهما من طريق عمرو بن عاصم الكلابي، حدثنا همام بن يحيى، حدثنا إسحاق بن عبد الله بن أبي طلحة، عن أنس بن مالك فذكره، واللفظ لمسلم، وفي لفظ البخاري: إن الله قد غفر لك ذنبك، أو قال: حدَّك.","grade":"متفق عليه","chapter_ar":"باب أن الصلاة كفارة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon — Authentic: al-Bukhari (6823), Muslim (2764 — wording here is his). In al-Bukhari’s wording: “Allah has forgiven your sin,” or he said: “your punishment.”","chapter_en":"Prayer as expiation","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Anas said: A man came to the Prophet ﷺ and said: “O Messenger of Allah, I have committed an offence deserving a legal punishment, so carry it out on me.” Then the prayer time came, and he prayed with the Messenger of Allah ﷺ. When the Prophet ﷺ finished the prayer, the man said: “O Messenger of Allah, I have committed an offence deserving a legal punishment, so carry out Allah’s Book upon me.” The Prophet ﷺ said: “Did you pray with us?” He said: “Yes.” He said: “You have been forgiven.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6823)، ومسلم (2764) واللفظ له. وفي لفظ البخاري: «غفر الله لك ذنبك»، أو قال: «حدك»."},{"num":1749,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ قَالَ: بَيْنَمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْمَسْجِدِ، وَنَحْنُ قُعُودٌ مَعَهُ إِذْ جَاءَ رَجُلٌ، فَقَالَ: يَا رَسُولَ اللَّهِ إِنِّي أَصَبْتُ حَدًّا فَأَقِمْهُ عَلَيَّ، فَسَكَتَ عَنْهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ أَعَادَ، فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي أَصَبْتُ حَدًّا، فَأَقِمْهُ عَلَيَّ، فَسَكَتَ عَنْهُ وَأُقِيمَتِ الصَّلَاةُ، فَلَمَّا انْصَرَفَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ أَبُو أُمَامَةَ: فَاتَّبَعَ الرَّجُلُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ انْصَرَفَ، وَاتَّبَعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْظُرُ مَا يَرُدُّ عَلَى الرَّجُلِ، فَلَحِقَ الرَّجُلُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا رَسُولَ اللَّهِ إِنِّي أَصَبْتُ حَدًّا فَأَقِمْهُ عَلَيَّ، قَالَ أَبُو أُمَامَةَ: فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَرَأَيْتَ حِينَ خَرَجْتَ مِنْ بَيْتِكَ أَلَيْسَ قَدْ تَوَضَّأْتَ، فَأَحْسَنْتَ الْوُضُوءَ ؟ قَالَ: بَلَى، يَا رَسُولَ اللَّهِ، قَالَ: ثُمَّ شَهِدْتَ الصَّلَاةَ مَعَنَا ؟ فَقَالَ: نَعَمْ، يَا رَسُولَ اللَّهِ، قَالَ: فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَإِنَّ اللَّهَ قَدْ غَفَرَ لَكَ حَدَّكَ أَوَ قَالَ: ذَنْبَكَ."],"takhrij":"صحيح: رواه مسلم في التوبة (2765) من طريق عمر بن يونس، حدثنا عكرمة بن عمار، حدثنا شدَّاد، حدثنا أبو أمامة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب أن الصلاة كفارة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Muslim (2765).","chapter_en":"Prayer as expiation","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abu Umamah reported: While the Messenger of Allah ﷺ was in the mosque and we were sitting with him, a man came and said: “O Messenger of Allah, I have committed an offence deserving a legal punishment, so carry it out on me.” The Prophet ﷺ remained silent. Then the prayer was called, and when the Messenger of Allah ﷺ finished and departed, the man followed him. I also followed the Messenger of Allah ﷺ to see what he would say to the man. The man caught up with the Messenger of Allah ﷺ and said: “O Messenger of Allah, I have committed an offence deserving a legal punishment, so carry it out on me.” The Messenger of Allah ﷺ said: “When you left your house, did you not perform wudu’ and do it well?” He said: “Yes, O Messenger of Allah.” He said: “And then you attended the prayer with us?” He said: “Yes, O Messenger of Allah.” So the Messenger of Allah ﷺ said: “Then Allah has forgiven your punishment,” or he said: “your sin.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2765)."},{"num":1750,"demo":false,"sanad":"","matn":["عَنْ حُمْرَانَ أَنَّهُ قَالَ: فَلَمَّا تَوَضَّأَ عُثْمَانُ قَالَ: وَاللَّهِ لَأُحَدِّثَنَّكُمْ حَدِيثًا، وَاللَّهِ لَوْلَا آيَةٌ فِي كِتَابِ اللَّهِ مَا حَدَّثْتُكُمُوهُ، إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: لَا يَتَوَضَّأُ رَجُلٌ، فَيُحْسِنُ وُضُوءَهُ، ثُمَّ يُصَلِّي الصَّلَاةَ، إِلَّا غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الصَّلَاةِ الَّتِي تَلِيهَا، قَالَ عُرْوَةُ الآيَةُ: ﴿ إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنْزَلْنَا مِنَ الْبَيِّنَاتِ وَالْهُدَى﴾ إِلَى قَوْلِهِ ﴿اللَّاعِنُونَ﴾ [ سورة البقرة:159 ]."],"takhrij":"متفق عليه: رواه البخاري في الوضـوء (160)، ومسلم في الطهـارة (227: 6) كلاهما من طريق إبراهيم بن سعد، عن صالح بن كيسان، عن ابن شهاب الزهري، عن عروة، عن حمران مولى عثمان بن عفان قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب أن الصلاة كفارة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon — Authentic: al-Bukhari (160), Muslim (227).","chapter_en":"Prayer as expiation","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Humran said: When ‘Uthman performed wudu’, he said: “By Allah, I will narrate to you a hadith. By Allah, were it not for a verse in the Book of Allah, I would not have narrated it to you. I heard the Messenger of Allah ﷺ say: ‘No man performs wudu’ and does it well, then prays, except that he is forgiven (the sins) between it and the next prayer.’” ‘Urwah said: The verse is: “Indeed, those who conceal what We have sent down of clear proofs and guidance…” up to His saying: “the cursers.” [al-Baqarah 2:159]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (160)، ومسلم (227)."},{"num":1751,"demo":false,"sanad":"","matn":["عَنْ جَامِعِ بْنِ شَدَّادٍ قَالَ: سَمِعْتُ حُمْرَانَ بْنَ أَبَانَ، يُحَدِّثُ أَبَا بُرْدَةَ فِي هَذَا الْمَسْجِدِ فِي إِمَارَةِ بِشْرٍ، أَنَّ عُثْمَانَ بْنَ عَفَّانَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ أَتَمَّ الْوُضُوءَ كَمَا أَمَرَهُ اللَّهُ تَعَالَى، فَالصَّلَوَاتُ الْمَكْتُوبَاتُ، كَفَّارَاتٌ لِمَا بَيْنَهُنَّ."],"takhrij":"صحيح: رواه مسلم في الطهارة (231: 11) من طرق عن شعبة، عن جامع بن شداد قال: فذكره.","grade":"صحيح","chapter_ar":"باب أن الصلاة كفارة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Muslim (231).","chapter_en":"Prayer as expiation","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Jami‘ ibn Shaddad said: I heard Humran ibn Aban narrating to Abu Burdah in this mosque—during the governorship of Bishr—that ‘Uthman ibn ‘Affan said: The Messenger of Allah ﷺ said: “Whoever completes wudu’ as Allah the Exalted commanded, then the prescribed prayers are expiations for what is between them.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (231)."},{"num":1752,"demo":false,"sanad":"","matn":["عَنْ الْحَارِثَ مَوْلَى عُثْمَانَ بْنِ عَفَّان قَالَ: جَلَسَ عُثْمَانُ يَوْمًا وَجَلَسْنَا مَعَهُ، فَجَاءَهُ الْمُؤَذِّنُ، فَدَعَا بِمَاءٍ فِي إِنَاءٍ، أَظُنُّهُ سَيَكُونُ فِيهِ مُدٌّ، فَتَوَضَّأَ، ثُمَّ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَوَضَّأُ وُضُوئِي هَذَا، ثُمَّ قَالَ: وَمَنْ تَوَضَّأَ وُضُوئِي، ثُمَّ قَامَ فَصَلَّى صَلَاةَ الظُّهْرِ، غُفِرَ لَهُ مَا كَانَ بَيْنَهَا وَبَيْنَ الصُّبْحِ، ثُمَّ صَلَّى الْعَصْرَ، غُفِرَ لَهُ مَا بَيْنَهَا وَبَيْنَ صَلَاةِ الظُّهْرِ، ثُمَّ صَلَّى الْمَغْرِبَ، غُفِرَ لَهُ مَا بَيْنَهَا وَبَيْنَ صَلَاةِ الْعَصْرِ، ثُمَّ صَلَّى الْعِشَاءَ، غُفِرَ لَهُ مَا بَيْنَهَا وَبَيْنَ صَلَاةِ الْمَغْرِبِ، ثُمَّ لَعَلَّهُ أَنْ يَبِيتَ يَتَمَرَّغُ لَيْلَتَهُ، ثُمَّ إِنْ قَامَ فَتَوَضَّأَ وَصَلَّى الصُّبْحَ، غُفِرَ لَهُ مَا بَيْنَهَا وَبَيْنَ صَلَاةِ الْعِشَاءِ، وَهُنَّ الْحَسَنَاتُ يُذْهِبْنَ السَّيِّئَاتِ، قَالُوا: هَذِهِ الْحَسَنَاتُ، فَمَا الْبَاقِيَاتُ يَا عُثْمَانُ ؟ قَالَ: هُنَّ لَا إِلَهَ إِلَّا اللَّهُ، وَسُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَاللَّهُ أَكْبَرُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ."],"takhrij":"حسن: رواه أحمد (513)، والبزار (405)، والطبري في تفسيره (4038)، وابن أبي حاتم في تفسيره (11272) كلهم من طريق أبي عقيل، وهو زهرة بن معبد،، أنه سمع الحارث مولى عثمان بن عفان قال: فذكره.","grade":"حسن","chapter_ar":"باب أن الصلاة كفارة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan due to supporting chains: Ahmad (513), al-Bazzar (405), al-Tabari in his Tafsir (12/615).","chapter_en":"Prayer as expiation","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Al-Harith, the freedman of ‘Uthman ibn ‘Affan, said: ‘Uthman sat one day and we sat with him. The caller to prayer came, so he called for water in a vessel— I think it contained about a “mudd” (a small measure). He performed wudu’, then said: “I saw the Messenger of Allah ﷺ perform wudu’ like this wudu’ of mine, then he said: ‘Whoever performs wudu’ like my wudu’, then stands and prays the noon prayer, he is forgiven what was between it and the morning prayer. Then he prays the afternoon prayer, he is forgiven what was between it and the noon prayer. Then he prays the sunset prayer, he is forgiven what was between it and the afternoon prayer. Then he prays the night prayer, he is forgiven what was between it and the sunset prayer. Then perhaps he spends the night rolling about (committing slips). Then if he rises, performs wudu’, and prays the dawn prayer, he is forgiven what was between it and the night prayer— and these are the good deeds that wipe away bad deeds.’” They said: “These are the good deeds—so what are the enduring good deeds (al-baqiyat) O ‘Uthman?” He said: “They are: There is no god but Allah; Glory be to Allah; All praise is for Allah; Allah is the Greatest; and there is no power nor might except with Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (513)، والبزار (405)، والطبري في تفسيره (4038)."},{"num":1753,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، عَنْ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يُبْعَثُ مُنَادٍ عِنْدَ حَضْرَةِ كُلِّ صَلاةٍ، فَيَقُولُ: يَا بني آدَمَ، قُومُوا فَأَطْفِئُوا عَنْكُمْ مَا أَوْقَدْتُمْ عَلَى أَنْفُسِكُمْ، فَيَقُومُونَ فَيَتَطَهَّرُونَ وَتَسْقُطُ خَطَايَاهُمْ مِنْ أَعْيُنِهِمْ، وَيُصَلُّونَ فَيُغْفَرُ لَهُمْ مَا بَيْنَهُمَا، ثُمَّ يُوقِدُونَ فِيمَا بَيْنَ ذَلِكَ، فَإِذَا كَانَ عِنْدَ صَلاةِ الأُولَى نَادَى: يَا بني آدَمَ، قُومُوا فَأَطْفِئُوا مَا أَوْقَدْتُمْ عَلَى أَنْفُسِكُمْ، فَيَقُومُونَ فَيَتَطَهَّرُونَ وَيُصَلُّونَ فَيُغْفَرُ لَهُمْ مَا بَيْنَهُمَا، فَإِذَا حَضَرَتِ الْعَصْرُ فَمِثْلُ ذَلِكَ، فَإِذَا حَضَرَتِ الْمَغْرِبُ فَمِثْلُ ذَلِكَ، فَإِذَا حَضَرَتِ الْعَتَمَةُ فَمِثْلُ ذَلِكَ، فَيَنَامُونَ وَقَدْ غُفِرَ لَهُمْ، ثُمَّ قــــــــــَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَمُدْلِجٌ فِي خَيْرٍ، وَمُدْلِجٌ فِي شَرٍّ."],"takhrij":"حسن: رواه الطبراني في الكبير (10252) وعنه أبو نعيم في حلية الأولياء (4/189)، عن الحسن بن علي المعمري، ثنا محمد بن الخليل الخشني، ثنا أيوب بن حسان الجرشي، عن هشام بن الغاز، عن أبان يعني العطاء، عن عاصم ابن بهدلة، عن زر بن حبيش أنه حدثه، عن عبد الله بن مسعود فذكره.","grade":"حسن","chapter_ar":"باب أن الصلاة كفارة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: al-Tabarani in al-Mu‘jam al-Kabir (10/174), and from him Abu Nu‘aym in Hilyat al-Awliya’ (4/189).","chapter_en":"Prayer as expiation","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud reported that the Messenger of Allah ﷺ said: “A caller will be sent at the time of every prayer, saying: ‘O children of Adam, rise and extinguish what you have ignited against yourselves.’ So they rise, purify themselves, and their sins fall away from their eyes, then they pray and are forgiven what is between the two (prayers). Then they ignite again (i.e., commit sins) in between. When the time of the first prayer comes, he calls: ‘O children of Adam, rise and extinguish what you have ignited against yourselves.’ So they rise, purify themselves, and pray, and are forgiven what is between the two. When the afternoon prayer comes, it is the same; when the sunset prayer comes, it is the same; and when the night prayer comes, it is the same. Then they sleep having been forgiven.” Then the Messenger of Allah ﷺ said: “So one sets out by night in good, and one sets out by night in evil.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في المعجم الكبير (10252)، ومن طريقه أبو نعيم في حلية الأولياء (4/189)."},{"num":1754,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ ذَكَرَ الصَّلَاةَ يَوْمًا فَقَالَ: مَنْ حَافَظَ عَلَيْهَا كَانَتْ لَهُ نُورًا وَبُرْهَانًا وَنَجَاةً يَوْمَ الْقِيَامَةِ، وَمَنْ لَمْ يُحَافِظْ عَلَيْهَا لَمْ يَكُنْ لَهُ نُورٌ وَلَا بُرْهَانٌ وَلَا نَجَاةٌ، وَكَانَ يَوْمَ الْقِيَامَةِ مَعَ قَارُونَ وَفِرْعَوْنَ وَهَامَانَ وَأُبَيِّ بْنِ خَلَفٍ."],"takhrij":"حسن: رواه أحمد (6576) عن أبي عبد الرحمن، وهو عبد الله بن يزيد المقرئ، ثنا سعيد، وهو ابن أبي أيوب، حدثني كعب بن علقمة، عن عيسى بن هلال الصدفي، عن عبدالله بن عمرو بن العاص، فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في تأكيد الصلاة والمحافظة عليها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: Ahmad (6576), Ibn Hibban (1467), al-Tabarani in al-Awsat (as cited in Majma‘ al-Bahrayn, 538).","chapter_en":"Emphasizing the Prayer and Maintaining It","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["‘Abdullah ibn ‘Amr reported that the Prophet ﷺ mentioned the prayer one day and said: “Whoever maintains it will have light, proof, and salvation on the Day of Resurrection. And whoever does not maintain it will have no light, no proof, and no salvation, and on the Day of Resurrection he will be with Qarun, Pharaoh, Haman, and Ubayy ibn Khalaf.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8293],"tks":"حسن: رواه أحمد (6576)، وابن حبان (1467)، والطبراني في الأوسط كما في مجمع البحرين (538)."},{"num":1755,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ الْبَاهِلِيِّ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لتُنْقَضَنَّ عُرَى الْإِسْلَامِ عُرْوَةً عُرْوَةً، فَكُلَّمَا انْتَقَضَتْ عُرْوَةٌ تَشَبَّثَ النَّاسُ بِالَّتِي تَلِيهَا، وَأَوَّلُهُنّ نَقْضًا الْحُكْمُ، وَآخِرُهُنَّ الصَّلَاةُ."],"takhrij":"حسن: رواه أحمد (22160) ومن طريقه الطبراني في الكبير (7486) عن الوليد بن مسلم، حدَّثني عبد العزيز بن إسماعيل بن عبد الله، أن سليمان بن حبيب حدَّثهم، عن أبي أمامة فذكر الحديث. وصحّحه ابن حبَّان (6715)، فرواه من هذا الطريق.","grade":"حسن","chapter_ar":"باب ما جاء في تأكيد الصلاة والمحافظة عليها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: Ahmad (22160), al-Tabarani in al-Kabir (7486), and Ibn Hibban authenticated it (6715).","chapter_en":"Emphasizing the Prayer and Maintaining It","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abu Umamah al-Bahili reported that the Messenger of Allah ﷺ said: “The bonds of Islam will surely be undone one by one. Each time a bond is undone, people will cling to the one after it. The first of them to be undone will be governance/judgment, and the last of them will be the prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (22160)، والطبراني في الكبير (7486)، وصححه ابن حبان (6715)."},{"num":1756,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَالِكٍ الأَشْجَعِيّ، عَنْ أَبِيهِ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَسْلَمَ الرَّجُلُ كَانَ أَوَّلُ مَا يُعَلِّمُنَا الصَّلاةَ، أَوْ قَالَ: عَلَّمَهُ الصَّلاةَ."],"takhrij":"صحيح: رواه البزار (2765) واللفظ له، والطبراني في الكبير (8186) كلاهما من طرقٍ عن أبي مالك الأشجعي، عن أبيه قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تأكيد الصلاة والمحافظة عليها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: al-Bazzar (2765), al-Tabarani in al-Kabir (8/380). (Wording cited from al-Bazzar.)","chapter_en":"Emphasizing the Prayer and Maintaining It","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abu Malik al-Ashja‘i narrated from his father: When a man accepted Islam, the Messenger of Allah ﷺ would first teach him the prayer—or he said: he taught him the prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البزار (2765)، والطبراني في الكبير (8186)، واللفظ للبزار."},{"num":1757,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ لِكَعْبِ بْنِ عُجْرَةَ:..يَا كَعْبُ بْنَ عُجْرَةَ الصَّوْمُ جُنَّةٌ، وَالصَّدَقَةُ تُطْفِئُ الْخَطِيئَةَ، وَالصَّلَاةُ قُرْبَانٌ، أَوْ قَالَ: بُرْهَانٌ يَا كَعْبُ بْنَ عُجْرَةَ، إِنَّهُ لَا يَدْخُلُ الْجَنَّةَ لَحْمٌ نَبَتَ مِنْ سُحْتٍ، النَّارُ أَوْلَى بِهِ... الْحَدِيثَ."],"takhrij":"حسن: رواه أحمد (14441)، وأبو يعلى (1999)، والبزار – الكشف (1609)، وصحّحه ابن حبان (4514)، والحاكم (8302) كلهم من حديث عبد الرزاق، وهو في مصنفه (20719)، عن معمر، عن ابن خُثيم، عن عبد الرحمن بن سابط، عن جابر بن عبد الله فذكره في حديث طويل.","grade":"حسن","chapter_ar":"باب أن الصلاة برهان","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: Ahmad (14441), Abu Ya‘la (1999), al-Bazzar (Kashf al-Astar, 1609).","chapter_en":"Prayer Is Proof","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Jabir ibn ‘Abdullah reported that the Prophet ﷺ said to Ka‘b ibn ‘Ujrah: “O Ka‘b ibn ‘Ujrah, fasting is a shield, charity extinguishes sin, and prayer is a means of drawing near—or he said: a proof. O Ka‘b ibn ‘Ujrah, flesh that grew from unlawful earnings will not enter Paradise; the Fire is more deserving of it.” (Hadith continues.)"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (14441)، وأبو يعلى (1999)، والبزار في كشف الأستار (1609)."},{"num":1758,"demo":false,"sanad":"","matn":["عَنْ كَعْبِ بْنِ عُجْرَةَ قَالَ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ): قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا كَعْبَ بْنَ عُجْرَةَ الصَّلَاةُ بُرْهَانٌ وَالصَّوْمُ جُنَّةٌ حَصِينَةٌ، وَالصَّدَقَةُ تُطْفِئُ الْخَطِيئَةَ كَمَا يُطْفِئُ الْمَاءُ النَّارَ، يَا كَعْبَ بْنَ عُجْرَةَ إِنَّهُ لَا يَرْبُو لَحْمٌ نَبَتَ مِنْ سُحْتٍ إِلَّا كَانَتِ النَّارُ أَوْلَى بِهِ... الْحَدِيثَ."],"takhrij":"حسن: رواه الترمذي (614) عن عبد الله بن زياد القطواني الكوفي، حدثنا عبيد الله بن موسى، حدثنا غالب أبو بشر، عن أيوب بن عائذ الطائي، عن قيس بن مسلم، عن طارق بن شهاب، عن كعب بن عجرة فذكره في سياق طويل.","grade":"حسن","chapter_ar":"باب أن الصلاة برهان","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: al-Tirmidhi (614).","chapter_en":"Prayer Is Proof","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Ka‘b ibn ‘Ujrah reported: The Messenger of Allah ﷺ said to me: “O Ka‘b ibn ‘Ujrah! Prayer is proof, fasting is a strong shield, and charity extinguishes sin just as water extinguishes fire. O Ka‘b ibn ‘Ujrah! No flesh grows from unlawful earnings except that the Fire is more deserving of it.” (Hadith continues.) Al-Tirmidhi said: “This hadith is hasan and gharib.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (614)."},{"num":1759,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ مِنْ الْأَنْصَارِ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: قُمْ يَا بلَالُ، فَأَرِحْنَا بالصَّلَاةِ."],"takhrij":"صحيح: رواه أبو داود (4986)، وأحمد (23154) كلاهما من حديث إسرائيل، حدثنا عثمان بن المغيرة، عن سالم بن أبي الجعد، عن عبد الله بن محمد ابن الحنفية قال: انطلقت أنا وأبي إلى صهر لنا من الأنصار نعوده، فحضرت الصلاة، فقال لبعض أهله: يا جارية ائتوني بوضوء لعلي أصلي وأستريح قال: فأنكرنا ذلك عليه فقال: سمعت رسول الله صلى الله عليه وسلم يقول: فذكر الحديث. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الفراغ من الصلاة راحة للقلب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Abu Dawud (4986), Ahmad (23154).","chapter_en":"Completing the Prayer Is Rest for the Heart","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["A man from the Ansar reported: I heard the Messenger of Allah ﷺ say: “Get up, O Bilal, and give us rest through the prayer.” His saying, “Give us rest through the prayer,” means: establish the prayer so that we may find rest through it from the weariness and distractions of worldly life; prayer brings rest to the heart and soul through intimate communion with Allah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4986)، وأحمد (23154)."},{"num":1760,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ مِنَ اللَّيْلِ، وَامْرَأَةٌ تُصَلِّي بِصَلَاتِهِ، فَلَمَّا أَحَسَّ الْتَفَتَ إِلَيْهَا، فَقَالَ لَهَا: اضْطَجِعِي إِنْ شِئْتِ، قَالَتْ: إِنِّي أَجِدُ نَشَاطًا، قَالَ: إِنَّكِ لَسْتِ مَثَلِي، إِنَّمَا جُعِلَ قُرَّةُ عَيْنِي فِي الصَّلَاةِ."],"takhrij":"حسن: رواه ابن نصر المروزي في تعظيم قدر الصلاة (321) عن يحيى بن عثمان، ثنا هقل، عن الأوزاعي، عن إسحاق بن عبد الله بن أبي طلحة، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب قرة عين النبي ﷺ في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: Ibn Nasr al-Marwazi, Ta‘zim Qadr al-Salah (p. 321 / narration as cited).","chapter_en":"The Coolness of the Prophet’s Eye Was in Prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Anas reported that the Messenger of Allah ﷺ stood in prayer at night, and a woman was praying along with his prayer. When he noticed her, he turned to her and said: “Lie down if you wish.” She said: “I feel energetic.” He said: “You are not like me; rather, the coolness of my eye has been placed in the prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن نصر المروزي في تعظيم قدر الصلاة (ص 321)."},{"num":1761,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ، قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: جُعِلَتْ قُرَّةُ عَيْنِي فِي الصَّلَاةِ."],"takhrij":"حسن: رواه الطبراني في الكبير في الكبير (20/ح 1012) عن حفص بن عمر الرقّي ومحمد بن الحسن بن كيسان المصيصي قالا: حدثنا أبو حذيفة، ثنا سفيان، عن زياد بن علاقة، عن المغيرة بن شعبة قال: فذكره.","grade":"حسن","chapter_ar":"باب قرة عين النبي ﷺ في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: al-Tabarani in al-Mu‘jam al-Kabir (20/420).","chapter_en":"The Coolness of the Prophet’s Eye Was in Prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في وجوب الصلاة وفضلها","group_en":"A collection of what has been reported about the obligation of prayer and its virtue","part_no":9,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Al-Mughirah ibn Shu‘bah reported that the Messenger of Allah ﷺ said: “The coolness of my eye has been placed in the prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في المعجم الكبير (20/ح 1012)."},{"num":1762,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ أَنَّهُ أَخَّرَ الصَّلَاةَ يَوْمًا، فَدَخَلَ عَلَيْهِ عُرْوَةُ بْنُ الزُّبَيْرِ، فَأَخْبَرَهُ أَنَّ الْمُغِيرَةَ بْنَ شُعْبَةَ أَخَّرَ الصَّلَاةَ يَوْمًا وَهُوَ بِالْكُوفَةِ، فَدَخَلَ عَلَيْهِ أَبُو مَسْعُودٍ الْأَنْصَارِيُّ، فَقَالَ: مَا هَذَا يَا مُغِيرَةُ ؟ أَلَيْسَ قَدْ عَلِمْتَ أَنَّ جِبْرِيلَ نَزَلَ فَصَلَّى فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ صَلَّى فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ صَلَّى فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ صَلَّى فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ صَلَّى فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قَالَ: بِهَذَا أُمِرْتُ. فَقَالَ عُمَرُ بْنُ عَبْدِ الْعَزِيزِ: اعْلَمْ مَا تُحَدِّثُ بِهِ يَا عُرْوَةُ، أَوَ إِنَّ جِبْرِيلَ هُوَ الَّذِي أَقَامَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقْتَ الصَّلَاةِ ؟ قَالَ عُرْوَةُ: كَذَلِكَ كَانَ بَشِيرُ بْنُ أَبِي مَسْعُودٍ الْأَنْصَارِيُّ يُحَدِّثُ، عَنْ أَبِيهِ."],"takhrij":"متفق عليه: رواه مالك في وقوت الصلاة (1) عن ابن شهاب، عن عمر بن عبد العزيز.","grade":"متفق عليه","chapter_ar":"باب ما جاء في إمامة جبريل وتوقيت الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon / Muttafaqun ‘alayh: Narrated by Malik (1), al-Bukhari (521), and Muslim (610).","chapter_en":"The Leadership of Jibril and Setting the Prayer Times","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["‘Umar ibn ‘Abd al-‘Aziz delayed the prayer one day, so ‘Urwah ibn al-Zubayr entered upon him and informed him that al-Mughirah ibn Shu‘bah had once delayed the prayer while in Kufah. Then Abu Mas‘ud al-Ansari entered upon al-Mughirah and said: “What is this, O Mughirah? Did you not know that Jibril descended and prayed, and the Messenger of Allah ﷺ prayed; then he prayed and the Messenger of Allah ﷺ prayed; then he prayed and the Messenger of Allah ﷺ prayed; then he prayed and the Messenger of Allah ﷺ prayed; then he prayed and the Messenger of Allah ﷺ prayed; then he said: ‘This is what I was commanded with.’” So ‘Umar ibn ‘Abd al-‘Aziz said: “Be careful about what you narrate, O ‘Urwah—was it Jibril who established the time of prayer for the Messenger of Allah ﷺ?” ‘Urwah said: “Likewise, Bashir ibn Abi Mas‘ud al-Ansari used to narrate from his father.”"]},"buhuth":{"en":["Abū Dāwūd (394) added: “He prayed Fajr once in darkness, then on another occasion he prayed it when it was lighter; thereafter his practice was to pray it in the darkness of dawn until he died, and he did not return to praying it when it was light.”"]},"intro_majmu":{"ar":["قال الله سبحانه وتعالى:","﴿ إِنَّ الصَّلَاةَ كَانَتْ عَلَى الْمُؤْمِنِينَ كِتَابًا مَوْقُوتًا ﴾ [النساء: ١٠٣]","أي: فرضاً مؤقتاً","وقال تعالى:","﴿ فَسُبْحَانَ اللَّهِ حِينَ تُمْسُونَ وَحِينَ تُصْبِحُونَ ۝ وَلَهُ الْحَمْدُ فِي السَّمَاوَاتِ وَالْأَرْضِ وَعَشِيًّا وَحِينَ تُظْهِرُونَ ﴾ [الروم: ١٧-١٨]","فقوله: ( حِينَ تُمْسُونَ) أي: صلاة المغرب والعشاء.","وقوله: ( وَحِينَ تُصْبِحُونَ ) أي: صلاة الصبح.","وقوله: ( وَعَشِيًّا ) أي: صلاة العصر.","وقوله: ( وَحِينَ تُظْهِرُونَ ) أي: صلاة الظُّهْر.","وقال تعالى:","﴿ أَقِمِ الصَّلَاةَ لِدُلُوكِ الشَّمْسِ إِلَىٰ غَسَقِ اللَّيْلِ وَقُرْآنَ الْفَجْرِ ۖ إِنَّ قُرْآنَ الْفَجْرِ كَانَ مَشْهُودًا ﴾ [الإسراء: ٧٨]","أراد بالدلوك زوالها، فدخل فيه صلاة الظُّهر والعصر والمغرب والعشاء، (وَقُرْءَانَ الْفَجْرِ) أراد به صلاة الصبح، روي ذلك عن ابن مسعود."],"en":["Allah the Exalted said: “Indeed, prayer has been prescribed upon the believers at fixed times.” (Surah An-Nisa, 4:103)","Meaning: an obligation that is appointed for specific times.","Allah the Exalted said: “So glorify Allah when you reach the evening and when you reach the morning. And to Him belongs all praise in the heavens and the earth—at late afternoon and when you reach midday.” (Surah Ar-Rum, 30:17–18)","“When you reach the evening” refers to the Maghrib and ‘Isha prayers.","“When you reach the morning” refers to the Fajr prayer.","“At late afternoon” refers to the ‘Asr prayer.","“When you reach midday” refers to the Dhuhr prayer.","“Establish the prayer from the sun’s decline until the darkness of night, and the recitation at dawn. Indeed, the recitation at dawn is witnessed.” (Surah Al-Isra, 17:78)","“Duluk” here means the sun’s decline, which includes Dhuhr, ‘Asr, Maghrib, and ‘Isha. “The recitation at dawn” refers to the Fajr prayer. This was reported from Ibn Mas‘ud."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (1) والبخاري (521) ومسلم (610)."},{"num":1763,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمَّنِي جِبْرِيلُ عَلَيْهِ السَّلَام عِنْدَ الْبَيْتِ مَرَّتَيْنِ، فَصَلَّى بِيَ الظُّهْرَ حِينَ زَالَتِ الشَّمْسُ وَكَانَتْ قَدْرَ الشِّرَاكِ، وَصَلَّى بِيَ الْعَصْرَ حِينَ كَانَ ظِلُّهُ مِثْلَهُ، وَصَلَّى بِيَ يَعْنِي الْمَغْرِبَ حِينَ أَفْطَرَ الصَّائِمُ، وَصَلَّى بِيَ الْعِشَاءَ حِينَ غَابَ الشَّفَقُ، وَصَلَّى بِيَ الْفَجْرَ حِينَ حَرُمَ الطَّعَامُ وَالشَّرَابُ عَلَى الصَّائِمِ، فَلَمَّا كَانَ الْغَدُ صَلَّى بِيَ الظُّهْرَ حِينَ كَانَ ظِلُّهُ مِثْلَهُ، وَصَلَّى بِي الْعَصْرَ حِينَ كَانَ ظِلُّهُ مِثْلَيْهِ، وَصَلَّى بِيَ الْمَغْرِبَ حِينَ أَفْطَرَ الصَّائِمُ، وَصَلَّى بِيَ الْعِشَاءَ إِلَى ثُلُثِ اللَّيْلِ، وَصَلَّى بِيَ الْفَجْرَ فَأَسْفَرَ، ثُمَّ الْتَفَتَ إِلَيَّ، فَقَالَ: يَا مُحَمَّدُ، هَذَا وَقْتُ الْأَنْبِيَاءِ مِنْ قَبْلِكَ، وَالْوَقْتُ مَا بَيْنَ هَذَيْنِ الْوَقْتَيْنِ."],"takhrij":"حسن: أخرجه أبو داود (393)، والترمذي (149) كلاهما من طريق عبدالرحمن بن الحارث بن عَيَّاش بن ربيعة، عن حكيم بن حكيم، عن نافع بن جبير بن مطعم، عن ابن عباس فذكر مثله، واللفظ لأبي داود.","grade":"حسن","chapter_ar":"باب ما جاء في إمامة جبريل وتوقيت الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (393) and al-Tirmidhi (149). The wording here is from Abu Dawud.","chapter_en":"The Leadership of Jibril and Setting the Prayer Times","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Ibn ‘Abbas reported that the Messenger of Allah ﷺ said: “Jibril (peace be upon him) led me in prayer at the House twice. He prayed Dhuhr with me when the sun declined, when the shadow was about the length of a sandal-strap. He prayed ‘Asr with me when an object’s shadow was equal to it. He prayed Maghrib with me when the fasting person breaks the fast. He prayed ‘Isha with me when the twilight disappeared. And he prayed Fajr with me when food and drink become forbidden for the fasting person. Then the next day he prayed Dhuhr with me when an object’s shadow was equal to it, and he prayed ‘Asr with me when an object’s shadow was twice its length. He prayed Maghrib with me when the fasting person breaks the fast. He prayed ‘Isha with me until a third of the night. And he prayed Fajr with me when it became brighter. Then he turned to me and said: ‘O Muhammad, this is the time of the prophets before you, and the time is between these two times.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: أخرجه أبو داود (393)، والترمذي (149)، واللفظ لأبي داود."},{"num":1764,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قال: جَاءَ جِبْرِيلُ عَلَيْهِ السَّلَام إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ زَالَتِ الشَّمْسُ فَقَالَ: قُمْ يَا مُحَمَّدُ فَصَلِّ الظُّهْرَ حِينَ مَالَتِ الشَّمْسُ، ثُمَّ مَكَثَ حَتَّى إِذَا كَانَ فَيْءُ الرَّجُلِ مِثْلَهُ جَاءَهُ لِلْعَصْرِ فَقَالَ: قُمْ يَا مُحَمَّدُ فَصَلِّ الْعَصْرَ، ثُمَّ مَكَثَ حَتَّى إِذَا غَابَتِ الشَّمْسُ جَاءَهُ فَقَالَ: قُمْ فَصَلِّ الْمَغْرِبَ فَقَامَ فَصَلَّاهَا حِينَ غَابَتِ الشَّمْسُ سَوَاءً، ثُمَّ مَكَثَ حَتَّى إِذَا ذَهَبَ الشَّفَقُ جَاءَهُ، فَقَالَ: قُمْ فَصَلِّ الْعِشَاءَ فَقَامَ فَصَلَّاهَا، ثُمَّ جَاءَهُ حِينَ سَطَعَ الْفَجْرُ فِي الصُّبْحِ، فَقَالَ: قُمْ يَا مُحَمَّدُ فَصَلِّ فَقَامَ فَصَلَّى الصُّبْحَ، ثُمَّ جَاءَهُ مِنَ الْغَدِ حِينَ كَانَ فَيْءُ الرَّجُلِ مِثْلَهُ، فَقَالَ: قُمْ يَا مُحَمَّدُ فَصَلِّ فَصَلَّى الظُّهْرَ، ثُمَّ جَاءَهُ جِبْرِيلُ عَلَيْهِ السَّلَام حِينَ كَانَ فَيْءُ الرَّجُلِ مِثْلَيْهِ، فَقَالَ: قُمْ يَا مُحَمَّدُ فَصَلِّ فَصَلَّى الْعَصْرَ، ثُمَّ جَاءَهُ لِلْمَغْرِبِ حِينَ غَابَتِ الشَّمْسُ وَقْتًا وَاحِدًا لَمْ يَزُلْ عَنْهُ، فَقَالَ: قُمْ فَصَلِّ فَصَلَّى الْمَغْرِبَ، ثُمَّ جَاءَهُ لِلْعِشَاءِ حِينَ ذَهَبَ ثُلُثُ اللَّيْلِ الْأَوَّلُ، فَقَالَ: قُمْ فَصَلِّ فَصَلَّى الْعِشَاءَ، ثُمَّ جَاءَهُ لِلصُّبْحِ حِينَ أَسْفَرَ جِدًّا، فَقَالَ: قُمْ فَصَلِّ فَصَلَّى الصُّبْحَ، فَقَالَ: مَا بَيْنَ هَذَيْنِ وَقْتٌ كُلُّهُ."],"takhrij":"حسن: رواه النسائي (526) واللفظ له، والترمذي (150) كلاهما من طريق عبدالله بن المبارك، عن حسين بن علي بن حسين، قال: أخبرني وهب بن كيسان، قال: حدثنا جابر بن عبد الله فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في إمامة جبريل وتوقيت الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (526) — wording is his; and al-Tirmidhi (150).","chapter_en":"The Leadership of Jibril and Setting the Prayer Times","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Jabir ibn ‘Abdullah said: Jibril (peace be upon him) came to the Prophet ﷺ when the sun had declined and said: “Stand, O Muhammad, and pray Dhuhr when the sun has declined.” Then he waited until an object’s shadow was equal to it, then he came for ‘Asr and said: “Stand, O Muhammad, and pray ‘Asr.” Then he waited until the sun set and came and said: “Stand and pray Maghrib.” So he stood and prayed it as soon as the sun set, without delay. Then he waited until the twilight disappeared and came and said: “Stand and pray ‘Isha.” So he stood and prayed it. Then he came when dawn became bright and said: “Stand, O Muhammad, and pray Fajr.” So he stood and prayed Fajr. Then the next day he came when an object’s shadow was equal to it and said: “Stand, O Muhammad, and pray Dhuhr.” Then he came when an object’s shadow was twice its length and said: “Stand, O Muhammad, and pray ‘Asr.” So he stood and prayed ‘Asr. Then he came for Maghrib at the same time as the day before, not moving from it, and said: “Stand and pray,” so he prayed Maghrib. Then he came for ‘Isha when the first third of the night had passed and said: “Stand and pray,” so he prayed ‘Isha. Then he came for Fajr when it became very bright and said: “Stand and pray,” so he prayed Fajr. Then he said: “All the time between these two (times) is (valid) time.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (526) واللفظ له، والترمذي (150)."},{"num":1765,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قال: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَذَا جِبْرِيلُ عَلَيْهِ السَّلَام جَاءَكُمْ يُعَلِّمُكُمْ دِينَكُمْ، فَصَلَّى الصُّبْحَ حِينَ طَلَعَ الْفَجْرُ وَصَلَّى الظُّهْرَ حِينَ زَاغَتِ الشَّمْسُ، ثُمَّ صَلَّى الْعَصْرَ حِينَ رَأَى الظِّلَّ مِثْلَهُ، ثُمَّ صَلَّى الْمَغْرِبَ حِينَ غَرَبَتِ الشَّمْسُ وَحَلَّ فِطْرُ الصَّائِمِ، ثُمَّ صَلَّى الْعِشَاءَ حِينَ ذَهَبَ شَفَقُ اللَّيْلِ، ثُمَّ جَاءَهُ الْغَدَ فَصَلَّى بِهِ الصُّبْحَ حِينَ أَسْفَرَ قَلِيلًا، ثُمَّ صَلَّى بِهِ الظُّهْرَ حِينَ كَانَ الظِّلُّ مِثْلَهُ، ثُمَّ صَلَّى الْعَصْرَ حِينَ كَانَ الظِّلُّ مِثْلَيْهِ، ثُمَّ صَلَّى الْمَغْرِبَ بِوَقْتٍ وَاحِدٍ حِينَ غَرَبَتِ الشَّمْسُ وَحَلَّ فِطْرُ الصَّائِمِ، ثُمَّ صَلَّى الْعِشَاءَ حِينَ ذَهَبَ سَاعَةٌ مِنَ اللَّيْلِ، ثُمَّ قَالَ: الصَّلَاةُ مَا بَيْنَ صَلَاتِكَ أَمْسِ وَصَلَاتِكَ الْيَوْمَ."],"takhrij":"حسن: رواه النسائي (502) قال: أخبرنا الحسين بن حُريثٍ، قال: أنبأنا الفضل ابن موسى، عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في إمامة جبريل وتوقيت الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (502). Al-Hakim authenticated it (volume 1, page 194).","chapter_en":"The Leadership of Jibril and Setting the Prayer Times","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said that the Messenger of Allah ﷺ said: “This is Jibril (peace be upon him). He has come to teach you your religion. He prayed Fajr when dawn appeared, and he prayed Dhuhr when the sun declined. Then he prayed ‘Asr when the shadow of everything was equal to it. Then he prayed Maghrib when the sun set and the fasting person breaks the fast. Then he prayed ‘Isha when the twilight of the night disappeared. Then he came the next day and prayed Fajr when it became a little brighter. Then he prayed Dhuhr when the shadow was equal to it. Then he prayed ‘Asr when the shadow was twice its length. Then he prayed Maghrib at one fixed time when the sun set and the fasting person breaks the fast. Then he prayed ‘Isha when an hour of the night had passed. Then he said: ‘The prayer time is between your prayer yesterday and your prayer today.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (502)، وصححه الحاكم (1/194)."},{"num":1766,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ حَزْمٍ قَالَ: جَاءَ جَبْرَائِيلُ فَصَلَّى بِالنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَصَلَّى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالنَّاسِ حِينَ زَالَتْ الشَّمْسُ الظُّهْرَ، ثُمَّ صَلَّى الْعَصْرَ حِينَ كَانَ ظِلُّهُ مِثْلَهُ، ثُمَّ صَلَّى الْمَغْرِبَ حِينَ غَرَبَتْ الشَّمْسُ، ثُمَّ صَلَّى الْعِشَاءَ بَعْدَ ذَلِكَ، كَأَنَّهُ يُرِيدُ ذَهَابَ الشَّفَقِ، ثُمَّ صَلَّى الْفَجْرَ حِينَ فَجَرَ الْفَجْرُ بِغَلَسٍ، ثُمَّ جَاءَ جَبْرَائِيلُ مِنْ الْغَدِ فَصَلَّى الظُّهْرَ بِالنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَصَلَّى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالنَّاسِ الظُّهْرَ حِينَ كَانَ ظِلُّهُ مِثْلَهُ، ثُمَّ صَلَّى الْعَصْرَ حِينَ صَارَ ظِلُّهُ مِثْلَيْهِ، ثُمَّ صَلَّى الْمَغْرِبَ حِينَ غَرَبَتْ الشَّمْسُ لِوَقْتٍ وَاحِدٍ، ثُمَّ صَلَّى الْعِشَاءَ بَعْدَمَا ذَهَبَ هَوِيٌّ مِنْ اللَّيْلِ، ثُمَّ صَلَّى الْفَجْرَ فَأَسْفَرَ بِهَا."],"takhrij":"حسن: رواه إسحاق بن راهويه في مسنده عن عبد الرزاق، ثنا معمر، عن عبدالله بن أبي بكر بن محمد بن عمرو بن حزم، عن أبيه، عن جده، عمرو بن حزم، فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في إمامة جبريل وتوقيت الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: Narrated by Ishaq ibn Rahawayh in his Musnad, as cited in Al-Matalib al-‘Aliyah (volume 1, page 140).","chapter_en":"The Leadership of Jibril and Setting the Prayer Times","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["‘Amr ibn Hazm said: Jibril (peace be upon him) came and led the Prophet ﷺ in prayer. The Prophet ﷺ then led the people in Dhuhr when the sun declined; then he prayed ‘Asr when an object’s shadow was equal to it; then he prayed Maghrib when the sun set; then he prayed ‘Isha afterward—meaning when the twilight had gone; then he prayed Fajr in darkness when dawn first broke. Then Jibril came the next day and prayed Dhuhr with the Prophet ﷺ, and the Prophet ﷺ led the people in Dhuhr when an object’s shadow was equal to it; then he prayed ‘Asr when the shadow became twice its length; then he prayed Maghrib at the same fixed time when the sun set; then he prayed ‘Isha after part of the night had passed; then he prayed Fajr when it became very bright."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه إسحاق بن راهويه في “مسنده” كما في (المطالب العالية) (1/140)."},{"num":1767,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ إِنَّ سُئِلَ عَنِ صَلَاةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الظُّهْرَ بِالْهَاجِرَةِ، وَالْعَصْرَ وَالشَّمْسُ نَقِيَّةٌ، وَالْمَغْرِبَ إِذَا وَجَبَتْ، وَالْعِشَاءَ أَحْيَانًا وَأَحْيَانًا إِذَا رَآهُمُ اجْتَمَعُوا عَجَّلَ، وَإِذَا رَآهُمْ أَبْطَوْا أَخَّرَ، وَالصُّبْحَ كَانُوا أَوْ كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّيهَا بِغَلَسٍ."],"takhrij":"متفق عليه: رواه البخاري في المواقيت (560،565)، ومسلم في المساجد (646) كلاهما من طريق شعبة، عن سعد بن إبراهيم، عن محمد بن عمرو بن الحسن بن عَلّي قال: لما قَدِم الحجَّاجُ المدينة فسألنا جابر بن عبدالله فذكر الحديث ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب ما جاء في توقيت الصلوات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon / Muttafaqun ‘alayh: Narrated by al-Bukhari (560 and 565) and Muslim (646).","chapter_en":"What Has Been Reported About Fixing the Prayer Times","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Jabir ibn ‘Abdullah was asked about the prayer of the Messenger of Allah ﷺ. He said: The Prophet ﷺ used to pray Dhuhr in the heat of midday, and he used to pray ‘Asr while the sun was still bright and clear. He would pray Maghrib when the sun had set. As for ‘Isha, sometimes (he prayed it earlier) and sometimes (later): if he saw the people had gathered, he hastened it; and if he saw they were late, he delayed it. And he prayed Fajr in darkness (early time before it becomes bright)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (560،565)، ومسلم (646)."},{"num":1768,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَرْزَةَ، كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الصُّبْحَ، وَأَحَدُنَا يَعْرِفُ جَلِيسَهُ وَيَقْرَأُ فِيهَا مَا بَيْنَ السِّتِّينَ إِلَى الْمِائَةِ، وَيُصَلِّي الظُّهْرَ إِذَا زَالَتِ الشَّمْسُ وَالْعَصْرَ، وَأَحَدُنَا يَذْهَبُ إِلَى أَقْصَى الْمَدِينَةِ يَرْجَعَ وَالشَّمْسُ حَيَّةٌ وَنَسِيتُ مَا قَالَ فِي الْمَغْرِبِ، وَلَا يُبَالِي بِتَأْخِيرِ الْعِشَاءِ إِلَى ثُلُثِ اللَّيْلِ، ثُمَّ قَالَ إِلَى شَطْرِ اللَّيْلِ.","وَقَالَ مُعَاذٌ: قَالَ شُعْبَةُ: لَقِيتُهُ مَرَّةً فَقَالَ: أَوْ ثُلُثِ اللَّيْلِ."],"takhrij":"متفق عليه: رواه البخاري في المواقيت (541) عن حفص بن عمر، ثنا شعبة، عن أبي المنهال، عن أبي برزَة فذكر الحديث، ورواه مسلم في المساجد (647) من أوجه عن شعبة به مثله. وأبو المنهال اسمه: سيّار بن سلامة.","grade":"متفق عليه","chapter_ar":"باب ما جاء في توقيت الصلوات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon / Muttafaqun ‘alayh: Narrated by al-Bukhari (541) and Muslim (647).","chapter_en":"What Has Been Reported About Fixing the Prayer Times","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Abu Barzah said: The Prophet ﷺ used to pray Fajr when one of us could recognize the person sitting next to him, and he would recite in it between sixty and one hundred verses. He would pray Dhuhr when the sun declined. He would pray ‘Asr such that one of us could go to the farthest part of the city and return while the sun was still bright. I forgot what he said about Maghrib. And he did not mind delaying ‘Isha until a third of the night—then he said: until half the night."]},"buhuth":{"en":["In another wording in Muslim: “And he disliked sleeping before it (the ‘Isha prayer) and speaking after it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (541)، ورواه مسلم (647)."},{"num":1769,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا صَلَّيْتُمُ الْفَجْرَ فَإِنَّهُ وَقْتٌ إِلَى أَنْ يَطْلُعَ قَرْنُ الشَّمْسِ الأَوَّلُ، ثُمَّ إِذَا صَلَّيْتُمُ الظُّهْرَ، فَإِنَّهُ وَقْتٌ إِلَى أَنْ يَحْضُرَ الْعَصْرُ، فَإِذَا صَلَّيْتُمُ الْعَصْرَ، فَإِنَّهُ وَقْتٌ إِلَى أَنْ تَصْفَرَّ الشَّمْسُ، فَإِذَا صَلَّيْتُمُ الْمَغْرِبَ، فَإِنَّهُ وَقْتٌ إِلَى أَنْ يَسْقُطَ الشَّفَقُ، فَإِذَا صَلَّيْتُمُ الْعِشَاءَ، فَإِنَّهُ وَقْتٌ إِلَى نِصْفِ اللَّيْلِ.","وَفِي رِوَايَةِ: وَقْتُ الظُّهْرِ مَا لَمْ يَحْضُرِ الْعَصْرُ، وَوَقْتُ الْعَصْرِ، مَا لَمْ تَصْفَرَّ الشَّمْسُ، وَوَقْتُ الْمَغْرِبِ، مَا لَمْ يَسْقُطْ ثَوْرُ الشَّفَقِ، وَوَقْتُ الْعِشَاءِ إِلَى نِصْفِ اللَّيْلِ، وَوَقْتُ الْفَجْرِ مَا لَمْ تَطْلُعِ الشَّمْسُ.","وَفِي رِوَايَةِ: وَقْتُ الظُّهْرِ إِذَا زَالَتِ الشَّمْسُ، وَكَانَ ظِلُّ الرَّجُلِ كَطُولِهِ، مَا لَمْ يَحْضُرِ الْعَصْرُ، وَوَقْتُ الْعَصْرِ، مَا لَمْ تَصْفَرَّ الشَّمْسُ، وَوَقْتُ صَلَاةِ الْمَغْرِبِ، مَا لَمْ يَغِبْ الشَّفَقُ، وَوَقْتُ صَلَاةِ الْعِشَاءِ إِلَى نِصْفِ اللَّيْلِ الأَوْسَطِ، وَوَقْتُ صَلَاةِ الصُّبْحِ، مِنْ طُلُوعِ الْفَجْرِ، مَا لَمْ تَطْلُعِ الشَّمْسُ، فَإِذَا طَلَعَتِ الشَّمْسُ، فَأَمْسِكْ عَنِ الصَّلَاةِ، فَإِنَّهَا تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ.","وَفِي رِوَايَةِ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَنْ وَقْتِ الصَّلَوَاتِ فَقَالَ: وَقْتُ صَلَاةِ الْفَجْرِ، مَا لَمْ يَطْلُعْ قَرْنُ الشَّمْسِ الأَوَّلُ، وَوَقْتُ صَلَاةِ الظُّهْرِ، إِذَا زَالَتِ الشَّمْسُ عَنْ بَطْنِ السَّمَاءِ، مَا لَمْ يَحْضُرِ الْعَصْرُ، وَوَقْتُ صَلَاةِ الْعَصْرِ، مَا لَمْ تَصْفَرَّ الشَّمْسُ، وَيَسْقُطْ قَرْنُهَا الأَوَّلُ، وَوَقْتُ صَلَاةِ الْمَغْرِبِ، إِذَا غَابَتِ الشَّمْسُ، مَا لَمْ يَسْقُطِ الشَّفَقُ، وَوَقْتُ صَلَاةِ الْعِشَاءِ، إِلَى نِصْفِ اللَّيْلِ."],"takhrij":"صحيح: رواه مسلم في المساجد (612) كل هذه الروايات من طريق قتادة، عن أبي أيوب، عن عبدالله بن عمرو فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في توقيت الصلوات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by Muslim (612).","chapter_en":"What Has Been Reported About Fixing the Prayer Times","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["‘Abdullah ibn ‘Amr ibn al-‘As reported that the Prophet ﷺ said: “When you have prayed Fajr, its time remains until the first edge (horn) of the sun rises. When you have prayed Dhuhr, its time remains until ‘Asr begins. When you have prayed ‘Asr, its time remains until the sun becomes yellow. When you have prayed Maghrib, its time remains until the twilight disappears. When you have prayed ‘Isha, its time remains until the middle of the night.” And in another narration: “The time of Dhuhr lasts as long as ‘Asr has not begun; the time of ‘Asr lasts as long as the sun has not turned yellow; the time of Maghrib lasts as long as the spreading redness of twilight has not sunk; the time of ‘Isha lasts until midnight; and the time of Fajr lasts as long as the sun has not risen.”","And in another narration: “The time of Dhuhr begins when the sun declines, and (continues) while a man’s shadow is equal to his height, so long as ‘Asr has not begun. The time of ‘Asr lasts so long as the sun has not turned yellow. The time of Maghrib lasts so long as the twilight has not disappeared. The time of ‘Isha lasts until the middle of the night. The time of Fajr is from the appearance of dawn so long as the sun has not risen; and when the sun rises, refrain from prayer, for it rises between the two horns of Satan.”","And in another narration, when the Messenger of Allah ﷺ was asked about the prayer times, he said:","“The time of Fajr is as long as the first edge (horn) of the sun has not risen. The time of Dhuhr is when the sun declines from the middle of the sky so long as ‘Asr has not begun. The time of ‘Asr is as long as the sun has not turned yellow and its first edge (horn) has not set. The time of Maghrib is when the sun has set so long as the twilight has not disappeared. And the time of ‘Isha is until the middle of the night.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (612)."},{"num":1770,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ عَبَسَةَ السُّلَمِيِّ إِنَّهُ حِينَ أَسْلَمَ سَأَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الصَّلَاةِ قَالَ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ): صَلِّ صَلَاةَ الصُّبْحِ ثُمَّ أَقْصِرْ عَنِ الصَّلَاةِ حَتَّى تَطْلُعَ الشَّمْسُ، حَتَّى تَرْتَفِعَ فَإِنَّهَا تَطْلُعُ حِينَ تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ، وَحِينَئِذٍ يَسْجُدُ لَهَا الْكُفَّارُ، ثُمَّ صَلِّ فَإِنَّ الصَّلَاةَ مَشْهُودَةٌ مَحْضُورَةٌ، حَتَّى يَسْتَقِلَّ الظِّلُّ بِالرُّمْحِ، ثُمَّ أَقْصِرْ عَنِ الصَّلَاةِ فَإِنَّ حِينَئِذٍ تُسْجَرُ جَهَنَّمُ، فَإِذَا أَقْبَلَ الْفَيْءُ فَصَلِّ فَإِنَّ الصَّلَاةَ مَشْهُودَةٌ مَحْضُورَةٌ، حَتَّى تُصَلِّيَ الْعَصْرَ، ثُمَّ أَقْصِرْ عَنِ الصَّلَاةِ حَتَّى تَغْرُبَ الشَّمْسُ، فَإِنَّهَا تَغْرُبُ بَيْنَ قَرْنَيْ شَيْطَانٍ وَحِينَئِذٍ يَسْجُدُ لَهَا الْكُفَّارُ... الْحَدِيثَ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (832) في سياق طويل وسبق ذكره في كتاب الوضوء، في باب ما جاء في ثواب الطهور.","grade":"صحيح","chapter_ar":"باب ما جاء في توقيت الصلوات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by Muslim (832).","chapter_en":"What Has Been Reported About Fixing the Prayer Times","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["‘Amr ibn ‘Abasah al-Sulami reported that when he accepted Islam, he asked the Prophet ﷺ about prayer. He said to him: “Pray the Fajr prayer, then refrain from prayer until the sun rises and becomes elevated, for it rises between the two horns of Satan, and at that time the disbelievers prostrate to it. Then pray, for prayer is witnessed and attended, until the shadow becomes upright with the spear (i.e., the time of true midday). Then refrain from prayer, for at that time Hell is kindled. When the shadow begins to extend (after midday), then pray, for prayer is witnessed and attended, until you pray ‘Asr. Then refrain from prayer until the sun sets, for it sets between the two horns of Satan, and at that time the disbelievers prostrate to it.”"]},"buhuth":{"en":["His saying: “until the shadow becomes upright with the spear” means the shadow stands straight opposite it toward the north—neither leaning toward the west nor the east. This is the moment of solar noon (when the sun is at its highest). The hadith explicitly states the prohibition of praying at that time until the sun has passed its zenith (i.e., until it begins to decline)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (832)."},{"num":1771,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ حُصَيْبٍ الأَسْلَمِيِّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّ رَجُلًا سَأَلَهُ عَنْ وَقْتِ الصَّلَاةِ فَقَالَ لَهُ: صَلِّ، مَعَنَا هَذَيْنِ يَعْنِي الْيَوْمَيْنِ، فَلَمَّا زَالَتِ الشَّمْسُ أَمَرَ بِلَالًا فَأَذَّنَ، ثُمَّ أَمَرَهُ فَأَقَامَ الظُّهْرَ، ثُمَّ أَمَرَهُ فَأَقَامَ الْعَصْرَ، وَالشَّمْسُ مُرْتَفِعَةٌ بَيْضَاءُ نَقِيَّةٌ، ثُمَّ أَمَرَهُ فَأَقَامَ الْمَغْرِبَ، حِينَ غَابَتِ الشَّمْسُ، ثُمَّ أَمَرَهُ فَأَقَامَ الْعِشَاءَ حِينَ غَابَ الشَّفَقُ، ثُمَّ أَمَرَهُ فَأَقَامَ الْفَجْرَ حِينَ طَلَعَ الْفَجْرُ، فَلَمَّا أَنْ كَانَ الْيَوْمُ الثَّانِي، أَمَرَهُ فَأَبْرَدَ بِالظُّهْرِ، فَأَبْرَدَ بِهَا، فَأَنْعَمَ أَنْ يُبْرِدَ بِهَا، وَصَلَّى الْعَصْرَ، وَالشَّمْسُ مُرْتَفِعَةٌ، أَخَّرَهَا فَوْقَ الَّذِي كَانَ وَصَلَّى الْمَغْرِبَ، قَبْلَ أَنْ يَغِيبَ الشَّفَقُ، وَصَلَّى الْعِشَاءَ بَعْدَمَا ذَهَبَ ثُلُثُ اللَّيْلِ، وَصَلَّى الْفَجْرَ فَأَسْفَرَ بِهَا، ثُمَّ قَالَ: أَيْنَ السَّائِلُ عَنْ وَقْتِ الصَّلَاةِ ؟ فَقَالَ الرَّجُلُ: أَنَا يَا رَسُولَ اللَّهِ، قَالَ: وَقْتُ صَلَاتِكُمْ بَيْنَ مَا رَأَيْتُمْ.","وَفِي رِوَايَةِ: اشْهَدْ مَعَنَا الصَّلَاةَ، فَأَمَرَ بِلَالًا فَأَذَّنَ بِغَلَسٍ، فَصَلَّى الصُّبْحَ، حِينَ طَلَعَ الْفَجْرُ، ثُمَّ أَمَرَهُ بِالظُّهْرِ، حِينَ زَالَتِ الشَّمْسُ عَنْ بَطْنِ السَّمَاءِ، ثُمَّ أَمَرَهُ بِالْعَصْرِ، وَالشَّمْسُ مُرْتَفِعَةٌ، ثُمَّ أَمَرَهُ بِالْمَغْرِبِ حِينَ وَجَبَتِ الشَّمْسُ، ثُمَّ أَمَرَهُ بِالْعِشَاءِ حِينَ وَقَعَ الشَّفَقُ، ثُمَّ أَمَرَهُ الْغَدَ فَنَوَّرَ بِالصُّبْحِ، ثُمَّ أَمَرَهُ بِالظُّهْرِ، فَأَبْرَدَ، ثُمَّ أَمَرَهُ بِالْعَصْرِ، وَالشَّمْسُ بَيْضَاءُ نَقِيَّةٌ، لَمْ تُخَالِطْهَا صُفْرَةٌ، ثُمَّ أَمَرَهُ بِالْمَغْرِبِ، قَبْلَ أَنْ يَقَعَ الشَّفَقُ، ثُمَّ أَمَرَهُ بِالْعِشَاءِ عِنْدَ ذَهَابِ ثُلُثِ اللَّيْلِ أَوْ بَعْضِهِ، شَكَّ حَرَمِيٌّ، فَلَمَّا أَصْبَحَ، قَالَ: أَيْنَ السَّائِلُ ؟ مَا بَيْنَ مَا رَأَيْتَ وَقْتٌ."],"takhrij":"صحيح: رواه مسلم في المساجد (613) عن علقمة بن مَرْثدٍ، عن سليمان بن بُريدة، عن أبيه فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في توقيت الصلوات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by Muslim (613).","chapter_en":"What Has Been Reported About Fixing the Prayer Times","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Buraydah ibn al-Husayb reported that a man asked the Prophet ﷺ about the time of prayer. He said to him: “Pray with us these two days.” When the sun declined, he ordered Bilal to call the adhan, then he ordered him to give the iqamah for Dhuhr. Then he ordered him to give the iqamah for ‘Asr while the sun was high, bright, and clear. Then he ordered him to give the iqamah for Maghrib when the sun set. Then he ordered him to give the iqamah for ‘Isha when the twilight disappeared. Then he ordered him to give the iqamah for Fajr when dawn appeared. On the second day, he ordered that Dhuhr be delayed until it was cooler, and it was delayed considerably; he prayed ‘Asr later than the previous day while the sun was still high; he prayed Maghrib before the twilight disappeared; he prayed ‘Isha after a third of the night had passed; and he prayed Fajr when it became bright. Then he said: “Where is the one who asked about the prayer times?” The man said: “I am, O Messenger of Allah ﷺ.” He said: “The time of your prayers is between what you have seen.”","And in another narration: he said, “Attend the prayer with us.” Then he commanded Bilal to call the adhan in darkness (early) and he prayed Fajr when dawn appeared; he prayed Dhuhr when the sun passed the middle of the sky; he prayed ‘Asr while the sun was high; he prayed Maghrib when the sun set; and he prayed ‘Isha when the twilight fell. Then the next day he prayed Fajr when it was brighter; he delayed Dhuhr to a cooler time; he prayed ‘Asr while the sun was bright and clear with no yellowing; he prayed Maghrib before the twilight fell; and he prayed ‘Isha when a third of the night, or some of it, had passed. Then he said: “Where is the questioner? All the time between what you saw is (valid) time.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (613)."},{"num":1772,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى، عَنِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُ أَتَاهُ سَائِلٌ يَسْأَلُهُ عَنْ مَوَاقِيتِ الصَّلَاةِ فَلَمْ يَرُدَّ عَلَيْهِ شَيْئًا، قَالَ: فَأَقَامَ الْفَجْرَ حِينَ انْشَقَّ الْفَجْرُ، وَالنَّاسُ لَا يَكَادُ يَعْرِفُ بَعْضُهُمْ بَعْضًا، ثُمَّ أَمَرَهُ فَأَقَامَ بِالظُّهْرِ حِينَ زَالَتِ الشَّمْسُ، وَالْقَائِلُ، يَقُولُ: قَدِ انْتَصَفَ النَّهَارُ، وَهُوَ كَانَ أَعْلَمَ مِنْهُمْ، ثُمَّ أَمَرَهُ فَأَقَامَ بِالْعَصْرِ وَالشَّمْسُ مُرْتَفِعَةٌ، ثُمَّ أَمَرَهُ فَأَقَامَ بِالْمَغْرِبِ حِينَ وَقَعَتِ الشَّمْسُ، ثُمَّ أَمَرَهُ فَأَقَامَ الْعِشَاءَ حِينَ غَابَ الشَّفَقُ، ثُمَّ أَخَّرَ الْفَجْرَ مِنَ الْغَدِ حَتَّى انْصَرَفَ مِنْهَا، وَالْقَائِلُ يَقُولُ: قَدْ طَلَعَتِ الشَّمْسُ أَوْ كَادَتْ، ثُمَّ أَخَّرَ الظُّهْرَ، حَتَّى كَانَ قَرِيبًا مِنْ وَقْتِ الْعَصْرِ بِالأَمْسِ، ثُمَّ أَخَّرَ الْعَصْرَ، حَتَّى انْصَرَفَ مِنْهَا، وَالْقَائِلُ يَقُولُ: قَدِ احْمَرَّتِ الشَّمْسُ، ثُمَّ أَخَّرَ الْمَغْرِبَ حَتَّى كَانَ عِنْدَ سُقُوطِ الشَّفَقِ، ثُمَّ أَخَّرَ الْعِشَاءَ حَتَّى كَانَ ثُلُثُ اللَّيْلِ الأَوَّلِ، ثُمَّ أَصْبَحَ فَدَعَا السَّائِلَ، فَقَالَ: الْوَقْتُ بَيْنَ هَذَيْنِ."],"takhrij":"صحيح: رواه مسلم في المساجد (614) عن محمد بن عبدالله بن نمير، حدثنا أبي، حدثنا بدر بن عثمان، حدثنا أبو بكر بن أبي موسى، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في توقيت الصلوات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by Muslim (614).","chapter_en":"What Has Been Reported About Fixing the Prayer Times","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Abu Musa reported that someone came to the Messenger of Allah ﷺ asking about the prayer times, and he did not answer him verbally. Instead, he ordered the call to establish: Fajr when dawn first split, when people could hardly recognize one another. Dhuhr when the sun declined, while someone said, “Midday has passed,” though the Prophet ﷺ knew best. ‘Asr while the sun was still high. Maghrib when the sun had set. ‘Isha when the twilight disappeared. Then on the next day he delayed: Fajr until he finished it and someone said, “The sun has risen—or is about to.” Dhuhr until it was close to the time of ‘Asr the day before. ‘Asr until he finished it and someone said, “The sun has turned red.” Maghrib until near the disappearance of twilight. ‘Isha until the first third of the night. Then in the morning he called the questioner and said: “The time is between these two.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (614)."},{"num":1773,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ رَجُلًا أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَأَلَهُ عَنْ وَقْتِ صَلَاةِ الْغَدَاةِ، فَلَمَّا أَصْبَحْنَا مِنَ الْغَدِ أَمَرَ حِينَ انْشَقَّ الْفَجْرُ أَنْ تُقَامَ الصَّلَاةُ فَصَلَّى بِنَا، فَلَمَّا كَانَ مِنَ الْغَدِ أَسْفَرَ ثُمَّ أَمَرَ فَأُقِيمَتِ الصَّلَاةُ فَصَلَّى بِنَا، ثُمَّ قَالَ: أَيْنَ السَّائِلُ عَنْ وَقْتِ الصَّلَاةِ ؟ مَا بَيْنَ هَذَيْنِ وَقْتٌ."],"takhrij":"صحيح: رواه النسائي (544)، وأحمد (12119)، والبزار (6570)، وأبو يعلى (3801) كلهم من طرق عن حميد الطويل، عن أنس قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في توقيت الصلوات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by al-Nasa’i (544), Ahmad (12119), al-Bazzar (6570), and Abu Ya‘la (3801).","chapter_en":"What Has Been Reported About Fixing the Prayer Times","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Anas reported that a man came to the Prophet ﷺ and asked about the time of the dawn prayer. The next morning, when dawn first split, the Prophet ﷺ ordered the prayer to be established and led them. On the following morning, he delayed it until it became light, then ordered the prayer to be established and led them. Then he said: “Where is the one who asked about the prayer time? The time is between these two.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (544)، وأحمد (12119)، والبزار (6570)، وأبو يعلى (3801)."},{"num":1774,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قال: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الظُّهْرَ إِذَا زَالَتِ الشَّمْسُ، وَيُصَلِّي الْعَصْرَ بَيْنَ صَلَاتَيْكُمْ هَاتَيْنِ، وَيُصَلِّي الْمَغْرِبَ إِذَا غَرَبَتِ الشَّمْسُ، وَيُصَلِّي الْعِشَاءَ إِذَا غَابَ الشَّفَقُ، ثُمَّ قَالَ: عَلَى إِثْرِهِ، وَيُصَلِّي الصُّبْحَ إِلَى أَنْ يَنْفَسِحَ الْبَصَرُ."],"takhrij":"صحيح: رواه النسائي (552) قال: أخبرنا إسماعيل بن مسعود ومحمد بن عبدالأعلى قالا: حدثنا خالد، عن شُعبة، عن أبي صدقةَ، عن أنس بن مالك فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في توقيت الصلوات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by al-Nasa’i (552).","chapter_en":"What Has Been Reported About Fixing the Prayer Times","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ would pray Dhuhr when the sun declined; he would pray ‘Asr between these two prayers of yours; he would pray Maghrib when the sun set; he would pray ‘Isha when the twilight disappeared—then (the narrator) said: “immediately after that”; and he would pray Fajr until sight became clear and open (i.e., until the brightness spread)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (552)."},{"num":1775,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: سَأَلْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَيُّ الْعَمَلِ أَحَبُّ إِلَى اللَّهِ ؟ قَالَ: الصَّلَاةُ عَلَى وَقْتِهَا، قَالَ: ثُمَّ أَيٌّ ؟ قَالَ: ثُمَّ بِرُّ الْوَالِدَيْنِ، قَالَ: ثُمَّ أَيٌّ ؟ قَالَ: الْجِهَادُ فِي سَبِيلِ اللَّهِ، قَالَ: حَدَّثَنِي بِهِنَّ وَلَوِ اسْتَزَدْتُهُ لَزَادَنِي."],"takhrij":"متفق عليه: رواه البخاري في المواقيت (527) واللفظ له، ومسلم في الإيمان (85) كلاهما من حديث شعبة، عن الوليد بن العَيْزَار أنه سمع أبا عمرو الشَيْباني يقول: حدثنا صاحب هذه الدار، وأشار إلى دار عبدالله بن مسعود فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب فضل الصلاة لوقتها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (527) — wording is his — and Muslim (85).","chapter_en":"The virtue of praying at its proper time.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Ibn Mas‘ud said: I asked the Prophet ﷺ, “Which deed is most beloved to Allah?” He said: “Prayer at its proper time.” I asked, “Then what?” He said: “Kindness to parents.” I asked, “Then what?” He said: “Striving in the path of Allah.” He added: “He told me these, and if I had asked him for more, he would have told me more.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (527) واللفظ له، ومسلم (85)."},{"num":1776,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: مَا صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الصَّلاةَ لِوَقْتِهَا الآخِرِ حَتَّى قَبَضَهُ اللَّهُ."],"takhrij":"صحيح: رواه الحاكم في المستدرك (687) وعنه البيهقي في السنن (2046) عن محمد بن صالح بن هانئ، ثنا الحسين بن الفضل البجلي، ثنا هاشم بن القاسم، ثنا الليث بن سعد، عن أبي النضر، عن عمرة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب فضل الصلاة لوقتها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by al-Hakim (1/190), and also by al-Bayhaqi in al-Sunan (1/435).","chapter_en":"The virtue of praying at its proper time.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, said: The Messenger of Allah ﷺ did not delay a prayer until its last time (i.e., the very end of its time) until Allah took his soul."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الحاكم (687) وعنه البيهقي في السنن (2046)."},{"num":1777,"demo":false,"sanad":"","matn":["عَنْ أَبِي قَتَادَةَ قَالَ: خَطَبَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)... أَمَا لَكُمْ فِيَّ أُسْوَةٌ، ثُمَّ قَالَ: أَمَا إِنَّهُ لَيْسَ فِي النَّوْمِ تَفْرِيطٌ، إِنَّمَا التَّفْرِيطُ عَلَى مَنْ لَمْ يُصَلِّ الصَّلَاةَ، حَتَّى يَجِيءَ وَقْتُ الصَّلَاةِ الأُخْرَى... الْحَدِيثَ."],"takhrij":"صحيح: رواه مسلم في المساجد (681) عن شيبان بن فروخ، حدثنا سليمان (يعني ابن المغيرة)، حدثنا ثابت، عن عبدالله بن رباح، عن أبي قتادة فذكره في حديث طويل في حديث التعريس.","grade":"صحيح","chapter_ar":"باب المنع من إخراج الصلاة عن وقتها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by Muslim in the Book of Mosques (681).","chapter_en":"Prohibiting the delaying of prayer beyond its time.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Abu Qatadah said: The Messenger of Allah ﷺ delivered a sermon to us and said: “…Do you not have an example in me?” Then he said: “There is no negligence in sleep. Negligence is only upon the one who does not pray a prayer until the time of the next prayer comes.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (681)."},{"num":1778,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَيْفَ أَنْتَ إِذَا كَانَتْ عَلَيْكَ أُمَرَاءُ يُؤَخِّرُونَ الصَّلَاةَ عَنْ وَقْتِهَا، أَوْ يُمِيتُونَ الصَّلَاةَ عَنْ وَقْتِهَا ؟ قَالَ: قُلْتُ: فَمَا تَأْمُرُنِي ؟ قَالَ: صَلِّ الصَّلَاةَ لِوَقْتِهَا، فَإِنْ أَدْرَكْتَهَا مَعَهُمْ، فَصَلِّ، فَإِنَّهَا لَكَ نَافِلَةٌ.","وَفِي رِوَايَةِ: فَصَلِّ الصَّلَاةَ لِوَقْتِهَا، فَإِنْ صَلَّيْتَ لِوَقْتِهَا، كَانَتْ لَكَ نَافِلَةً، وَإِلَّا كُنْتَ قَدْ أَحْرَزْتَ صَلَاتَكَ.","وَفِي رِوَايَةِ: فَإِنْ أُقِيمَتِ الصَّلَاةُ وَأَنْتَ فِي الْمَسْجِدِ فَصَلِّ.","وَفِي رِوَايَةِ: عَنْ أَبِي الْعَالِيَةِ الْبَرَّاءِ قَالَ: أَخَّرَ ابْنُ زِيَادٍ الصَّلَاةَ، فَجَاءَنِي عَبْدُ اللَّهِ بْنُ الصَّامِتِ، فَأَلْقَيْتُ لَهُ كُرْسِيًّا، فَجَلَسَ عَلَيْهِ، فَذَكَرْتُ لَهُ صَنِيعَ ابْنِ زِيَادٍ، فَعَضَّ عَلَى شَفَتِهِ، وَضَرَبَ فَخِذِي، وَقَالَ: إِنِّي سَأَلْتُ أَبَا ذَرٍّ، كَمَا سَأَلْتَنِي، فَضَرَبَ فَخِذِي، كَمَا ضَرَبْتُ فَخِذَكَ، وَقَالَ: إِنِّي سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، كَمَا سَأَلْتَنِي، فَضَرَبَ فَخِذِي، كَمَا ضَرَبْتُ فَخِذَكَ، وَقَالَ: صَلِّ الصَّلَاةَ لِوَقْتِهَا، فَإِنْ أَدْرَكَتْكَ الصَّلَاةُ مَعَهُمْ، فَصَلِّ، وَلَا تَقُلْ إِنِّي قَدْ صَلَّيْتُ، فَلَا أُصَلِّي.","وَفِي رِوَايَةِ: فَصَلِّ الصَّلَاةَ لِوَقْتِهَا، ثُمَّ إِنْ أُقِيمَتِ الصَّلَاةُ، فَصَلِّ مَعَهُمْ، فَإِنَّهَا زِيَادَةُ خَيْرٍ.","وَفِي رِوَايَةِ: عَنْ أَبِي الْعَالِيَةِ الْبَرَّاءِ قَالَ: قُلْتُ لِعَبْدِ اللَّهِ بْنِ الصَّامِتِ: نُصَلِّي يَوْمَ الْجُمُعَةِ خَلْفَ أُمَرَاءَ فَيُؤَخِّرُونَ الصَّلَاةَ، قَالَ: فَضَرَبَ فَخِذِي ضَرْبَةً أَوْجَعَتْنِي، وَقَالَ: سَأَلْتُ أَبَا ذَرٍّ، عَنْ ذَلِكَ، فَضَرَبَ فَخِذِي وَقَالَ: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَنْ ذَلِكَ فَقَالَ: صَلُّوا الصَّلَاةَ لِوَقْتِهَا، وَاجْعَلُوا صَلَاتَكُمْ مَعَهُمْ نَافِلَةً."],"takhrij":"صحيح: هذه الروايات كلها أخرجها مسلم في المساجد (648) من طرق عن عبدالله بن الصامت، عن أبي ذر.","grade":"صحيح","chapter_ar":"باب المنع من إخراج الصلاة عن وقتها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by Muslim (648).","chapter_en":"Prohibiting the delaying of prayer beyond its time.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Abu Dharr reported: The Messenger of Allah ﷺ said to me: “How will you be when you have rulers who delay the prayer beyond its time, or cause the prayer to die by taking it outside its time?” I said: “What do you command me?” He said: “Pray the prayer at its proper time. If you catch it with them, then pray (again), for it will be a voluntary prayer for you.”","Other narrations add: “Pray the prayer at its proper time; if you prayed it at its time, then your prayer with them is voluntary; otherwise you have safeguarded your prayer.”","“If the prayer is established while you are in the mosque, then pray.”","Another narration from Abū al-ʿĀliyah al-Barrāʾ states: Ibn Ziyād delayed the prayer, so ʿAbdullāh ibn al-Ṣāmit came to me. I brought him a chair and he sat on it. I mentioned to him what Ibn Ziyād had done. He bit his lip, struck my thigh, and said: I asked Abū Dharr just as you asked me, and he struck my thigh just as I struck yours and said: I asked the Messenger of Allah ﷺ just as you asked me, and he struck my thigh just as I struck yours and said: “Pray the prayer at its proper time. If you catch the prayer with them, then pray, and do not say: ‘I have already prayed, so I will not pray.’”","“Pray at its time; then if the prayer is established, pray with them, for it is an extra good.”","Another narration from Abū al-ʿĀliyah al-Barrāʾ states: I said to ʿAbdullāh ibn al-Ṣāmit: “We pray the Friday prayer behind rulers who delay the prayer.” He struck my thigh with a blow that hurt me and said: I asked Abū Dharr about that, and he struck my thigh and said: I asked the Messenger of Allah ﷺ about that, and he said: “Pray the prayer at its proper time, and make your prayer with them a voluntary prayer.”"]},"buhuth":{"en":["The statement, “Do not say: ‘I have already prayed, so I will not pray,’” encourages complying with rulers in matters that are not sinful, so that unity is not broken and fitnah does not arise. For this reason Abū Dharr used to say: “My close friend advised me to hear and obey, even if he were an enslaved man with mutilated limbs.” Narrated by Muslim (1837)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: هذه الروايات كلها أخرجها مسلم (648). وقوله: ( ولا تقل إني قد صليت فلا أصلي). فيه الحث على موافقة الأمراء في غير المعصية، لئلا تفترق الكلمة وتقع الفتنة، ولذلك كان أبو ذر يقول: (( إن خليلي أوصاني أن أسمع وأطيع، وإن كان عبدا مجدع الأطراف )). رواه مسلم (1837)."},{"num":1779,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ مَيْمُونٍ الْأَوْدِيِّ قَالَ: قَدِمَ عَلَيْنَا مُعَاذُ بْنُ جَبَلٍ الْيَمَنَ رَسُولُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَيْنَا قَالَ: فَسَمِعْتُ تَكْبِيرَهُ مَعَ الْفَجْرِ رَجُلٌ أَجَشُّ الصَّوْتِ، قَالَ: فَأُلْقِيَتْ عَلَيْهِ مَحَبَّتِي، فَمَا فَارَقْتُهُ حَتَّى دَفَنْتُهُ بِالشَّامِ مَيِّتًا، ثُمَّ نَظَرْتُ إِلَى أَفْقَهِ النَّاسِ بَعْدَهُ، فَأَتَيْتُ ابْنَ مَسْعُودٍ فَلَزِمْتُهُ حَتَّى مَاتَ، فَقَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَيْفَ بِكُمْ إِذَا أَتَتْ عَلَيْكُمْ أُمَرَاءُ يُصَلُّونَ الصَّلَاةَ لِغَيْرِ مِيقَاتِهَا ؟ قُلْتُ: فَمَا تَأْمُرُنِي إِنْ أَدْرَكَنِي ذَلِكَ يَا رَسُولَ اللَّهِ ؟ قَالَ: صَلِّ الصَّلَاةَ لِمِيقَاتِهَا، وَاجْعَلْ صَلَاتَكَ مَعَهُمْ سُبْحَةً."],"takhrij":"صحيح: رواه أبو داود (432) عن عبدالرحمن بن إبراهيم، دُحيم، الدمشقي، حدثنا الوليد، حدثنا الأوزاعي، حدثني حسان بن عطية، عن عبدالرحمن بن سابط، عن عمرو بن ميمون فذكره.","grade":"صحيح","chapter_ar":"باب المنع من إخراج الصلاة عن وقتها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by Abu Dawud (432); authenticated by Ibn Hibban (1481). Al-Nasa’i (779) and Ibn Majah (1255) also narrate the wording: “Perhaps you will encounter people who pray the prayer outside its proper time. If you encounter them, pray in your homes at the time you know, then pray with them and make it a voluntary prayer.”","chapter_en":"Prohibiting the delaying of prayer beyond its time.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["‘Amr ibn Maymun al-Awdi reported that Mu‘adh ibn Jabal arrived to Yemen as the messenger of the Messenger of Allah ﷺ. I heard his takbīr at Fajr; he was a man with a rough, resonant voice, and I came to love him. I never left him until I buried him after his death in Syria. Then I sought the most knowledgeable person after him, went to Ibn Mas‘ud, and remained with him until he died. He then said: The Messenger of Allah ﷺ said to me: “How will you be when rulers come upon you who pray the prayer outside its appointed time?” I said: “What do you command me if I reach that?” He said: “Pray the prayer at its appointed time, and make your prayer with them a voluntary prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (432)، وصححه ابن حبان (1481). ورواه النسائي (779)، وابن ماجه (1255) قال رسول الله ﷺ: (( لعلكم ستدركون أقواما يصلون الصلاة لغير وقتها، فإن أدركتموهم فصلوا في بيوتكم للوقت الذي تعرفون، ثم صلوا معهم، واجعلوها سبحة ))."},{"num":1780,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: إِنْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيُصَلِّي الصُّبْحَ، فَيَنْصَرِفُ النِّسَاءُ مُتَلَفِّعَاتٍ بِمُرُوطِهِنَّ مَا يُعْرَفْنَ مِنَ الْغَلَسِ."],"takhrij":"متفق عليه: أخرجه مالك في الوقوت (4) عن يحيى بن سعيد، عن عمرة بنتِ عبدالرحمن، عن عائشة فذكرت الحديث. ومن طريقه أخرجه البخاري في الأذان (867)، ومسلم في المساجد (645/232) كما رواه أيضاً الشيخان من أوجه عن ابن شهاب، عن عروة، عن عائشة نحوه البخاري (372،578)، ومسلم، والبخاري وحده (872) من طريق عبدالرحمن بن القاسم، عن أبيه، عن عائشة: أن رسولَ الله صلى الله عليه وسلم كان يُصَلِّي بغَلَسٍ فيَنْصَرِفْنَ نِسَاءُ المؤمنين، لا يُعْرَفْنَ من الغَلَسِ، أو لا يَعْرِفُ بَعْضُهنَّ بعضاً.","grade":"متفق عليه","chapter_ar":"باب استحباب التبكير بصلاة الصبح وأدائها في الغلس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (4), al-Bukhari (867), and Muslim (645). His saying “wrapped in their cloaks” (mutalaffiʿāt): al-Aṣmaʿī said that talffuʿ means wrapping oneself in a garment until it covers the body. In Ibn Ḥabīb’s commentary on al-Muwaṭṭaʾ, talffuʿ occurs only with covering the head, whereas talffuf may occur with the head covered or uncovered. “Murūṭ” is the plural of mirṭ (with a kasrah on its first letter): a cloak made of khazz, wool, or other material. See Fatḥ al-Bārī (1/482).","chapter_en":"The recommendation to pray the dawn prayer early, while it is still dark.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ would pray the dawn prayer, and the women would depart wrapped in their cloaks, not being recognizable because of the darkness."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: أخرجه مالك (4)، والبخاري (867)، ومسلم (645). وقوله: (( متلفعات )) قال الأصمعي: التلفع أن تشتمل بالثوب حتى تجلل به جسدك. وفي شرح الموطأ ابن حبيب: التلفع لا يكون إلا بتغطية الرأس، والتلفف يكون بتغطية الرأس وكشفه. و(( المروط )) جمع مرط - بكسر أوله - كساء من خز، أو صوف أو غيره. انظر: (( الفتح )) (1/482)."},{"num":1781,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ يَقُولُ: كُنْتُ أَتَسَحَّرُ فِي أَهْلِي، ثُمَّ يَكُونُ سُرْعَةٌ بِي أَنْ أُدْرِكَ صَلَاةَ الْفَجْرِ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه البخاري في المواقيت (577) عن إسماعيل بن أبي أويس، عن أخيه، عن سليمان، عن أبي حازم، سمع سهل بن سعد يقول فذكر مثله.","grade":"صحيح","chapter_ar":"باب استحباب التبكير بصلاة الصبح وأدائها في الغلس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by al-Bukhari (577).","chapter_en":"The recommendation to pray the dawn prayer early, while it is still dark.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Sahl ibn Sa‘d said: I used to eat the pre-dawn meal with my family, then I would be in such haste that I would still catch the dawn prayer with the Messenger of Allah ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (577)."},{"num":1782,"demo":false,"sanad":"","matn":["عَنْ مُغِيثِ بْنِ سُمَيٍّ قَالَ: صَلَّيْتُ مَعَ عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ الصُّبْحَ بِغَلَسٍ، فَلَمَّا سَلَّمَ أَقْبَلْتُ عَلَى ابْنِ عُمَرَ، فَقُلْتُ: مَا هَذِهِ الصَّلَاةُ ؟ قَالَ: هَذِهِ صَلَاتُنَا كَانَتْ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَبِي بَكْرٍ، وَعُمَرَ فَلَمَّا طُعِنَ عُمَرُ أَسْفَرَ بِهَا عُثْمَانُ."],"takhrij":"صحيح: رواه ابن ماجة (671) قال: حدثنا عبدالرحمن بن إبراهيم الدمشْقِي، قال: حدَّثَنا الوليدُ بن مُسلم، قال: حدثنا الأوْزَاعيُّ، قال: حدثنا نَهيكُ ابن يَريمَ قال: حدثنا مُغيثُ بن سُمَيّ فذكر الحديث.","grade":"صحيح","chapter_ar":"باب استحباب التبكير بصلاة الصبح وأدائها في الغلس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by Ibn Majah (671).","chapter_en":"The recommendation to pray the dawn prayer early, while it is still dark.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Mughith ibn Sumayy said: I prayed the dawn prayer with ‘Abdullah ibn al-Zubayr while it was still dark. When he ended the prayer with the salutation, I turned to Ibn ‘Umar and said: “What is this prayer?” He replied: “This was our prayer with the Messenger of Allah ﷺ and with Abu Bakr and ‘Umar. When ‘Umar was stabbed, ‘Uthman began praying it later, when it was brighter.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (671)."},{"num":1783,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ قَالَتْ: كُنَّ نِسَاءً يَشْهَدْنَ مَعَ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الصُّبْح، فَيَنْصَرِفْنَ مُتَلَفِّعَاتٍ بِمُرُوطِهِنَّ، مَا يُعْرَفْنَ مِنَ الْغَلسِ، قَالتْ: وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا سَلَّمَ مَكَثَ مَكَانَهُ قَلِيلًا، وَكَانُوا يَرَوْنَ أَنَّ ذَلِكَ كَيْمَا يَنْفُذَ النِّسَاءُ، قَبْلَ الرِّجَالِ.."],"takhrij":"صحيح: أخرجه عبد الرزاق (2181) عن معمر، عن الزهري، عن هند بنت الحارث، عن أم سلمة فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب استحباب التبكير بصلاة الصبح وأدائها في الغلس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by ʿAbd al-Razzaq (2181).","chapter_en":"The recommendation to pray the dawn prayer early, while it is still dark.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Umm Salamah said: Women used to attend the dawn prayer with the Messenger of Allah ﷺ, then they would leave wrapped in their cloaks, not recognizable because of the darkness. She said: When the Prophet ﷺ finished with the salutation, he would remain in his place for a short while. They thought that was so the women could depart before the men."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: أخرجه عبد الرزاق (2181)."},{"num":1784,"demo":false,"sanad":"","matn":["عَنْ رَافِعِ بْنِ خَدِيجٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَصْبِحُوا بِالصُّبْحِ، فَإِنَّهُ أَعْظَمُ لِأُجُورِكُمْ أَوْ أَعْظَمُ لِلْأَجْرِ."],"takhrij":"صحيح: رواه أبو داود (424)، والترمذي (154)، والنسائي (548،549)، وابن ماجة (672) كلهم من طرق عن عاصِم بن عُمر بن قتادة، عن محمود بن لَبيد، عن رافِع بن خَديج فذكر مثله واللفظ لأبي داود، ولفظ الترمذي والنسائي: أَسْفِرُوا بالفَجْرِ، فإنه أعْظمُ للأجْرِ.","grade":"صحيح","chapter_ar":"باب ما جاء في الإسفار بالصبح","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by Abu Dawud (424), al-Tirmidhi (154), and al-Nasa’i (548 and 549). Abu Dawud’s wording is cited; al-Tirmidhi and al-Nasa’i have: “Pray the dawn prayer when the true dawn becomes clear, for that is greater in reward.” Al-Tirmidhi said: “The hadith of Rafiʿ ibn Khadij regarding the dawn prayer is hasan sahih.” He also said: “The meaning of isfār is that dawn becomes clear so that there is no doubt about it; they did not understand isfār to mean delaying the prayer.” The word yaḍiḥ is from waḍaḥa; one says waḍaḥa al-fajr when dawn becomes luminous. It has been established in the hadith of Abū Masʿūd, as mentioned previously, that the Prophet ﷺ continued performing Fajr in the darkness of early dawn until he died. Ghalas is the beginning of Fajr time. Because there was concern that people might not distinguish the beginning of the time from the actual appearance of dawn, they were instructed to wait until it became clear, in order to verify and ascertain the first appearance of dawn, which is still ghalas.","chapter_en":"What has been reported about praying the dawn prayer when it becomes lighter (after the first darkness).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Rafi‘ ibn Khadij said: The Messenger of Allah ﷺ said: “Pray the dawn prayer when morning becomes clear, for that is greater for your reward.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (424)، والترمذي (154)، والنسائي (548، 549)، واللفظ لأبي داود. ولفظ الترمذي والنسائي: (( أسفروا بالفجر، فإنه أعظم للأجر )). قال الترمذي: (( حديث رافع بن خديج حديث حسن صحيح، وقال: معنى الإسفار: أن يضح الفجر فلا يشك فيه، ولم يروا أن معنى الإسفار تأخير الصلاة )). انتهى. قوله: (( يضح )) من وضح، يقال: وضح الفجر إذا أضاء. وقد ثبت في حديث أبي مسعود - كما سبق - أن النبي ﷺ استمر في أداء صلاة الفجر في الغلس حتى مات، والغلس هو أول وقت الفجر، وخشي أن لا يفرق الناس بين أول الوقت وبين طلوع الفجر فأمرهم بالإسفار للتحقق والتبين من أول طلوع الفجر وهو الغلس."},{"num":1785,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا اشْتَدَّ الْحَرُّ فَأَبْرِدُوا عَنِ الصَّلَاةِ، فَإِنَّ شِدَّةَ الْحَرِّ مِنْ فَيْحِ جَهَنَّمَ."],"takhrij":"متفق عليه: رواه مالك في وقوت الصلاة (28،29) من طريقين، عن عبدالله بن يزيد مولى الأسود بن سفيان، عن أبي سلمة بن عبدالرحمن، وعن محمد بن عبدالرحمن بن ثوبان، عن أبي هريرة فذكر مثله، وقال فيه: وذكر أن النارَ اشْتَكتْ إلى ربِّها، فأَذِنَ لها في كل عامٍ بنَفَسَيْنِ نَفَس في الشِّتاء، ونَفَس في الصيف.","grade":"متفق عليه","chapter_ar":"باب إبراد الصلاة في شدة الحرّ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (28 and 29), al-Bukhari (533 and 534), and Muslim (617).","chapter_en":"Cooling the prayer time (delaying) during extreme heat.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “When the heat is severe, then delay the prayer until it cools, for the intensity of heat is from the blazing breath of Hell.” In another wording, the Messenger of Allah ﷺ said: “The Fire complained to its Lord and said: ‘O Lord, one part of me has consumed another.’ So He permitted it two breaths: one in winter and one in summer. Thus the most intense heat you experience and the most intense severe cold you experience are from them.”"]},"buhuth":{"en":["Another narration states: “Whatever cold or severe cold you experience is from the breath of Hell, and whatever heat or scorching heat you experience is from the breath of Hell.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (28، 29)، والبخاري (533، 534)، ومسلم (617). وفي لفظ قال رسول الله ﷺ: (( اشتكت النار إلى ربها فقالت: يا رب أكل بعضي بعضا، فأذن لها بنفسين: نفس في الشتاء، ونفس في الصيف، فهو أشد ما تجدون من الحر، وأشد ما تجدون من الزمهرير )). وفي رواية: (( فما وجدتم من برد أو زمهرير فمن نفس جهنم، وما وجدتم من حر أو حرور فمن نفس جهنم ))."},{"num":1786,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ: أَذَّنَ مُؤَذِّنُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالظُّهْرِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَبْرِدْ أَبْرِدْ، أَوَ قَالَ: انْتَظِرِ انْتَظِرِ وَقَالَ: إِنَّ شِدَّةَ الْحَرِّ مِنْ فَيْحِ جَهَنَّمَ، فَإِذَا اشْتَدَّ الْحَرُّ، فَأَبْرِدُوا عَنِ الصَّلَاةِ، قَالَ أَبُو ذَرٍّ: حَتَّى رَأَيْنَا فَيْءَ التُّلُولِ."],"takhrij":"متفق عليه: رواه البخاري في المواقيت (535)، ومسلم في المساجد (616) كلاهما من طريق شعبة، عن مهاجر أبي الحسن، قال: سَمِعتُ زيد بن وهب، يقول: سمعتُ أباذر فذكر ولفظهما قريب.","grade":"متفق عليه","chapter_ar":"باب إبراد الصلاة في شدة الحرّ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (535) and Muslim (616). Another wording in al-Bukhari (539) begins: “We were with the Prophet ﷺ on a journey…” Ibn ʿAbbas said: al-tulūl is the plural of tall, meaning every mound formed on the ground from earth, sand, or the like.","chapter_en":"Cooling the prayer time (delaying) during extreme heat.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Abu Dharr said: The caller to prayer of the Messenger of Allah ﷺ gave the call for the noon prayer, so the Prophet ﷺ said: “Delay it, delay it,” or: “Wait, wait.” And he said: “The intensity of heat is from the blazing breath of Hell; so when the heat is severe, delay the prayer until it cools.” Abu Dharr said: until we could see the shade of the small hills."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (535)، ومسلم (616). وفي لفظ للبخاري bukhari(539): كنا مع النبي ﷺ في سفر… قال ابن عباس: التلول: جمع تل، وهو كل ما اجتمع على الأرض من تراب أو رمل أو نحو ذلك."},{"num":1787,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَبْرِدُوا بِالظُّهْرِ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ فَيْحِ جَهَنَّمَ."],"takhrij":"صحيح: رواه البخاري في المواقيت (538) عن عمر بن حفص، قال: حدثنا أبي، قال: حدثنا الأعمش، حدثنا أبو صالح، عن أبي سعيد فذكر مثله.","grade":"صحيح","chapter_ar":"باب إبراد الصلاة في شدة الحرّ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by al-Bukhari (538).","chapter_en":"Cooling the prayer time (delaying) during extreme heat.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Abu Sa‘id al-Khudri reported: The Messenger of Allah ﷺ said: “Delay the noon prayer until it cools, for the intensity of heat is from the blazing breath of Hell.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (538)."},{"num":1788,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: كَانَتْ قَدْرُ صَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الصَّيْفِ ثَلَاثَةَ أَقْدَامٍ إِلَى خَمْسَةِ أَقْدَامٍ، وَفِي الشِّتَاءِ خَمْسَةَ أَقْدَامٍ إِلَى سَبْعَةِ أَقْدَامٍ."],"takhrij":"حسن: أخرجه أبو داود (400)، والنسائي (503) كلاهما من طريق عَبيدة ابن حُميد، عن أبي مالك الأشجعي سعد بن طارق، عن كثير بن مُدرك، عن الأسود، أن عبدالله بن مسعود أخبره فذكر الحديث.","grade":"حسن","chapter_ar":"باب إبراد الصلاة في شدة الحرّ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (400) and al-Nasa’i (503).","chapter_en":"Cooling the prayer time (delaying) during extreme heat.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud said: The amount of delay (before praying) for the Messenger of Allah ﷺ in summer would be the length of three feet to five feet (of shadow), and in winter five feet to seven feet."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: أخرجه أبو داود (400)، والنسائي (503)."},{"num":1789,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَبْرِدُوا بِالظُّهْرِ."],"takhrij":"صحيح: رواه ابن ماجة (681) قال: حدثنا عبدالرحمن بن عمر، قال: حدثنا عبد الوهَّاب الثقفي، عن عبيدالله، عن نافع، عن ابن عمر، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب إبراد الصلاة في شدة الحرّ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by Ibn Majah (681). Also narrated by Ibn Khuzaymah (330) with the wording: “The intensity of heat is from the blazing breath of Hell, so delay the prayer during severe heat.”","chapter_en":"Cooling the prayer time (delaying) during extreme heat.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Ibn ‘Umar reported that the Messenger of Allah ﷺ said: “Delay the noon prayer until it cools.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (681). ورواه ابن خزيمة (330) ولفظه: (( إن شدة الحر من فيح جهنم، فأبردوا الصلاة في شدة الحر))."},{"num":1790,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قَالَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَبْرِدُوا بِالظُّهْرِ فِي الْحَرِّ."],"takhrij":"صحيح: رواه مسدد في مسنده قال: حدثنا عبدالله بن داود، ثنا هشام بن عروة، عن أبيه، عن عائشة فذكرت الحديث، وفي بعض النسخ على الشك عن عائشة. انظر: المطالب العالية (280) ورواه أيضاً أبو يعلى الموصلي قال: ثنا عبد الأعلى، ثنا عبدالله بن داود به مثله المقصد العلي (188).","grade":"صحيح","chapter_ar":"باب إبراد الصلاة في شدة الحرّ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by Musaddad in his Musnad (as cited in Al-Matalib al-‘Aliyah, page 291), and by Abu Ya‘la al-Mawsili (as cited in Al-Maqsad al-‘Ali, page 188). Also narrated by al-Bazzar in Kashf al-Astar (Report 371) with the wording: “The intensity of heat is from the blazing breath of Hell, so delay the prayer.”","chapter_en":"Cooling the prayer time (delaying) during extreme heat.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, reported that the Prophet ﷺ said: “Delay the noon prayer during heat.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسدد في مسنده كما في (( المطالب العالية)) (291) وأبو يعلى الموصلي كما في (( المقصد لعلي)) (188). ورواه البزار في كشف الأستار (371) ولفظه: (( إن شدة الحر من فيح جهنم فأبردوا بالصلاة))."},{"num":1791,"demo":false,"sanad":"","matn":["عَنْ صَفْوَانَ بْنِ مَخْرَمَةَ الزُّهْرِيِّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَبْرِدُوا بِالظُّهْرِ، فَإِنَّ شِدَّةَ الْحَرِّ مِنْ فَيْحِ جَهَنَّمَ."],"takhrij":"حسن: رواه الإمام أحمد (18306) عن وكيع، ويعلى والطبراني في الكبير (7399) من طريق عبدالله بن يوسف الفريابي وأبي نعيم، كلهم عن بشير بن سليمان، عن القاسم بن صفوان الزهري، عن أبيه فذكر الحديث.","grade":"حسن","chapter_ar":"باب إبراد الصلاة في شدة الحرّ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (18306) and al-Tabarani in Al-Mu‘jam al-Kabir (8/7399).","chapter_en":"Cooling the prayer time (delaying) during extreme heat.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Safwan ibn Makhramah al-Zuhri reported that the Prophet ﷺ said: “Delay the noon prayer, for the intensity of heat is from the blazing breath of Hell.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (18306) والطبراني في الكبير (8/7399)."},{"num":1792,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كُنَّا نُصَلِّي مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فِي شِدَّةِ الْحَرِّ، فَإِذَا لَمْ يَسْتَطِعْ أَحَدُنَا أَنْ يُمَكِّنَ جَبْهَتَهُ مِنَ الأَرْضِ، بَسَطَ ثَوْبَهُ فَسَجَدَ عَلَيْهِ."],"takhrij":"متفق عليه: أخرجه البخاري في المواقيت (542)، ومسلم في المساجد (620) كلاهما من طريق غالب القطان، عن بكر بن عبدالله، عن أنس بن مالك، فذكر الحديث، واللفظ لمسلم، ولفظ البخاري: كنا إذا صَلَّيْنَا خلفَ رسول الله صلى الله عليه وسلم بالظهائر سجدْنا على ثيابنا اتقاءَ الحَرِّ، وأخرجه أيضاً في كتاب الصلاة (385) وفي كتاب العمل في الصلاة (1208) في الجميع من طريق غالب به نحوه. ومن هذا الطريق رواه أيضاً أبو يعلى في مسنده المقصد العلي رقم (185) وفيه قال أنس: كُنَّا نُصلي مع رسول الله صلى الله عليه وسلم في شدة الحرِّ فيأخذ أحدنا الحصى في يده، فإذا برد وضعه فسجد عليه.","grade":"متفق عليه","chapter_ar":"باب استحباب تعجيل الظهر في أول وقتها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (542) and Muslim (620). Muslim’s wording is cited; al-Bukhari’s wording indicates they prostrated on their clothes to avoid the heat.","chapter_en":"The recommendation to pray the noon prayer early at the beginning of its time.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Anas ibn Malik reported: We used to pray with the Messenger of Allah ﷺ in extreme heat. If one of us could not place his forehead firmly on the ground, he would spread his garment and prostrate on it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: أخرجه البخاري (542)، ومسلم (620)، واللفظ لمسلم، ولفظ البخاري: كنا إذا صلينا خلف رسول الله ﷺ بالظهائر سجدنا على ثيابنا اتقاء الحر."},{"num":1793,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ حِينَ زَاغَتِ الشَّمْسُ فَصَلَّى الظُّهْرَ...(فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)."],"takhrij":"صحيح: رواه البخاري في المواقيت (540) عن أبي اليمان، قال: أخبرنا شعيب، عن الزهري، قال: أخبرني أنس بن مالك فذكر الحديث في سياق طويل، وسيأتي في صفة الجنة والنار، ورواه الترمذي (156) من طريق عبد الرزاق، أخبرنا معمر، عن الزهري به ولفظه: أن رسول الله صلى الله عليه وسلم صلى الظُّهْر حين زالت الشمس .","grade":"صحيح","chapter_ar":"باب استحباب تعجيل الظهر في أول وقتها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by al-Bukhari (540) and al-Tirmidhi (156) with the wording: “He prayed the noon prayer when the sun had passed its zenith.”","chapter_en":"The recommendation to pray the noon prayer early at the beginning of its time.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Anas reported that the Messenger of Allah ﷺ went out when the sun had passed its zenith and prayed the noon prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (540)، ورواه الترمذي (156) ولفظه: أن رسول الله ﷺ صلى الظهر حين زالت الشمس."},{"num":1794,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يُصَلِّي الظُّهْرَ إِذَا دَحَضَتِ الشَّمْسُ."],"takhrij":"صحيح: رواه مسلم في المساجد (618) من طريق يحيى بن سعيد وابن مهدي، عن شعبة، قال: حدثنا سماك بن حرب، عن جابر فذكره، ورواه أبو داود (806) عن عبيدالله بن بن معاذ، ثنا أبي، ثنا شعبة بإسناده، وفيه: إذا دحضتِ الشمس صلى الظُّهْر وقرأ بنحو من ﴿وَاللَّيْلِ إِذَا يَغْشَى﴾ والعصر كذلك، والصلوات كذلك إلا الصبح فإنه كان يطيلها. انتهى.","grade":"صحيح","chapter_ar":"باب استحباب تعجيل الظهر في أول وقتها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by Muslim (618). The report includes: “When the sun daḥaḍat, he prayed Ẓuhr and recited approximately from ‘By the night when it covers’; and ʿAsr similarly, and the other prayers similarly, except Fajr, which he used to lengthen.” His saying “when the sun daḥaḍat”—with a fatḥah on the dāl and ḥāʾ—means: when it declined from the meridian.","chapter_en":"The recommendation to pray the noon prayer early at the beginning of its time.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Jabir ibn Samurah said: The Prophet ﷺ would pray the noon prayer when the sun had passed its zenith, and the afternoon prayer similarly (early in its time), and the other prayers similarly—except the dawn prayer, which he used to lengthen."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (618)، وفيه: (( إذا دحضت الشمس صلى الظهر وقرأ بنحو من (والليل إذا يغشى) والعصر كذلك، والصلوات كذلك إلا الصبح فإنه كان يطيلها )). انتهى. وقوله: دحضت الشمس - بفتح الدال والحاء - أي: إذا زالت."},{"num":1795,"demo":false,"sanad":"","matn":["عَنْ خَبَّابِ بْنِ الْأَرَتِّ قَالَ: أَتَيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَشَكَوْنَا إِلَيْهِ حَرَّ الرَّمْضَاءِ، فَلَمْ يُشْكِنَا."],"takhrij":"صحيح: رواه مسلم في المساجد (619) من طرق عن زهير، حدثنا أبو إسحاق، عن سعيد بن وهب، عن خباب قال: فذكره.","grade":"صحيح","chapter_ar":"باب استحباب تعجيل الظهر في أول وقتها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by Muslim (619). His saying “he did not relieve our complaint” means: he did not remove our complaint. “The heat of the ramḍāʾ” means the heat of the sun that affected their feet. This indicates praying Ẓuhr early.","chapter_en":"The recommendation to pray the noon prayer early at the beginning of its time.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Khabbab ibn al-Aratt said: We came to the Messenger of Allah ﷺ and complained to him about the scorching heat of the sun-baked ground, but he did not remove our complaint (meaning, he did not delay the prayer for that reason)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (619). وقوله: (( فلم يشكنا )) أي: لم يزل شكوانا. وقوله: حر الرمضاء - يعني ما يصيب أقدامهم من حر الشمس - فيه تبكير صلاة الظهر."},{"num":1796,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: كُنْتُ أُصَلِّي الظُّهْرَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَآخُذُ قَبْضَةً مِنَ الْحَصَى لِتَبْرُدَ فِي كَفِّي أَضَعُهَا لِجَبْهَتِي أَسْجُدُ عَلَيْهَا لِشِدَّةِ الْحَرِّ."],"takhrij":"حسن: رواه أبو داود (399)، والنسائي (1081) كلاهما من طريق عَبَّاد بن عبَّاد، ثنا محمد بن عمرو، عن سعيد بن الحارث الأنصاري، عن جابر بن عبدالله فذكر الحديث، واللفظ لأبي داود. ولفظ النسائي: فآخذ قبْضةً من حَصى في كفِّي أَبرِّده، ثم أُحوِّلُه في كَفِّي الآخرِ، فإذا سجدتُ وضعتُه لجبهتي.","grade":"حسن","chapter_ar":"باب استحباب تعجيل الظهر في أول وقتها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (399) and al-Nasa’i (1081). Abu Dawud’s wording is cited. Al-Nasa’i’s wording is: “I would take a handful of pebbles in my palm and cool them, then transfer them to my other palm; when I prostrated, I placed them beneath my forehead.”","chapter_en":"The recommendation to pray the noon prayer early at the beginning of its time.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Jabir ibn ‘Abdullah said: I used to pray the noon prayer with the Messenger of Allah ﷺ. I would take a handful of pebbles to cool them in my palm and place them for my forehead to prostrate on because of the intense heat."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2643],"tks":"حسن: رواه أبو داود (399)، والنسائي (1081)، واللفظ لأبي داود. ولفظ النسائي: (( فآخذ قبضة من حصى في كفي أبرده، ثم أحوله في كفي الآخر، فإذا سجدت وضعته لجبهتي))."},{"num":1797,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَشَدَّ تَعْجِيلًا لِلظُّهْرِ مِنْكُمْ، وَأَنْتُمْ أَشَدُّ تَعْجِيلًا لِلْعَصْرِ مِنْهُ."],"takhrij":"صحيح: رواه الترمذي (161) حدثنا علي بن حُجْر، حدثنا إسماعيل بن عُلَيَّة، عن أيوب، عن ابن أبي مُليكَة، عن أم سلمة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب استحباب تعجيل الظهر في أول وقتها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Narrated by al-Tirmidhi (161).","chapter_en":"The recommendation to pray the noon prayer early at the beginning of its time.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Umm Salamah, the Mother of the Believers, said: The Messenger of Allah ﷺ would pray the noon prayer earlier than you do, and you pray the afternoon prayer earlier than he did."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (161)."},{"num":1798,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، يَقُولُ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا نَزَلَ مَنْزِلًا لَمْ يَرْتَحِلْ حَتَّى يُصَلِّيَ الظُّهْرَ، فَقَالَ لَهُ رَجُلٌ: وَإِنْ كَانَ بِنِصْفِ النَّهَارِ ؟ قَالَ: وَإِنْ كَانَ بِنِصْفِ النَّهَارِ."],"takhrij":"حسن: أخرجه أبو داود (1205) والنسائي (498) كلاهما من حديث يحيى بن سعيد، عن شُعبة، قال: حدثني حمزة العائذي، قال: سمعت أنس بن مالك فذكر الحديث. وإسناده حسن.","grade":"حسن","chapter_ar":"باب استحباب تعجيل الظهر في أول وقتها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1205) and al-Nasa’i (498).","chapter_en":"The recommendation to pray the noon prayer early at the beginning of its time.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Anas ibn Malik said: When the Prophet ﷺ stopped at a place, he would not depart from it until he had prayed the noon prayer. A man said to him: “Even if it is midday?” He replied: “Even if it is midday.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2888],"tks":"حسن: أخرجه أبو داود (1205) والنسائي (498)."},{"num":1799,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى الْعَصْرَ وَالشَّمْسُ فِي حُجْرَتِهَا لَمْ يَظْهَرِ الْفَيْءُ مِنْ حُجْرَتِهَا."],"takhrij":"متفق عليه: رواه البخاري (545)، ومسلم (611) كلاهما عن ابن شهاب عن عروة، عن عائشة، وقد ذكره مالك والبخاري ومسلم عقب حديث أبي مسعود لبيان وقت صلاة العصر معلقاً من مقولة ابن شهاب، ثم إن الشيخين أسندا من طرقهما عن ابن شهاب ومن لفظه: كان النبي صلى الله عليه وسلم يصلي العصر، والشمسُ طالعة في حجرتي، لم يظهر الفئ بعد.","grade":"متفق عليه","chapter_ar":"باب استحباب التبكير بالعصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (545) and Muslim (611). Another wording: “The Prophet ﷺ would pray ‘Asr while the sun was still bright in my room, and the shadow had not yet appeared.”","chapter_en":"The recommendation to pray the ‘Asr (afternoon) prayer early.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب مواقيت الصلوات","group_en":"All Chapters on the Prayer Times","part_no":9,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["‘A’ishah reported that the Messenger of Allah ﷺ prayed the ‘Asr prayer while the sun was still in her room, and the shadow had not yet appeared from her room."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (545)، ومسلم (611). وفي لفظ: كان النبي ﷺ يصلي العصر، والشمس طالعة في حجرتي، لم يظهر الفيء بعد."}]);